const NON_API_DEFAULT_PROVIDER_SLUGS = new Set(['modal', 'nvidia', 'vercel', 'inferx']);
function providerSlugOf(entry) {
  return (typeof entry === 'string' ? entry : (entry && entry.slug) || '').trim().toLowerCase();
}
function providerTextOf(entry) {
  return (typeof entry === 'string' ? entry : (entry && entry.slug) || '').trim();
}
function defaultProviders() { return JSON.parse(JSON.stringify(DEFAULT_API_SETTINGS.providers)); }

function defaultModelProviders() { return JSON.parse(JSON.stringify(DEFAULT_API_SETTINGS.modelProviders)); }

function bareModelSlug(modelString) {
  const s = (modelString || '').trim();
  if (!s) return '';
  const at = s.indexOf('@preset/');
  return (at >= 0 ? s.slice(0, at) : s).trim();
}





function normalizeResponseModel(responseModel, requestedModel) {
  const resp = String(responseModel || '').trim();
  const req = bareModelSlug(requestedModel || '').trim();
  if (!resp) return req || '';
  if (!req || resp.toLowerCase() === req.toLowerCase()) return req || resp;
  const prefixAliases = [['deepseek-ai/', 'deepseek/'], ['deepseek/', 'deepseek-ai/']];
  for (const [respPrefix, reqPrefix] of prefixAliases) {
    if (resp.toLowerCase().startsWith(respPrefix) && req.toLowerCase().startsWith(reqPrefix)) {
      const rest = resp.slice(respPrefix.length);
      if (req.toLowerCase() === reqPrefix + rest.toLowerCase()) return reqPrefix + rest;
    }
  }
  return resp;
}
// Direct-API providers (AIHubMix, …) may echo their own upstream model id in
// the response's "model" field (e.g. request "coding-glm-5.2-free" → response
// "glm-5.3"). Prefer the id we actually sent so the chat bubble shows what was
// really used; fall back to the provider's echo only if we have no sent id.
function responseModelForDisplay(responseModel, requestedModel, sentModel) {
  const sent = String(sentModel || '').trim();
  if (sent) return sent;
  return normalizeResponseModel(responseModel, requestedModel);
}
function findModelProviderRule(settings, modelString) {
  if (settings.enableModelProviders === false) return null;
  const slug = fallbackListId(bareModelSlug(modelString)).toLowerCase();
  if (!slug) return null;
  const rules = settings.modelProviders || [];
  return rules.find(r => r && r.enabled !== false && fallbackListId(r.model).toLowerCase() === slug
                      && (r.providers || []).filter(Boolean).length > 0) || null;
}






function smartProviderSkipForModel(settings, modelString) {
  if (!settings || settings.smartProviderSkip !== true) return false;
  const rule = findModelProviderRule(settings, modelString);
  if (rule && (rule.smartSkip === 'on' || rule.smartSkip === 'off')) return rule.smartSkip === 'on';
  return true;
}

function effectiveProviderOrder(settings, modelString) {
  const rule = findModelProviderRule(settings, modelString);
  if (rule) {
    const globalOrder = (settings.providers || []).map(providerTextOf).filter(Boolean);
    const globalByKey = new Map();
    globalOrder.forEach(slug => {
      const key = providerSlugOf(slug);
      if (key && !globalByKey.has(key)) globalByKey.set(key, slug);
    });
    
    
    const seen = new Set();
    const order = [];
    (rule.providers || []).forEach(provider => {
      const picked = (provider || '').trim();
      const key = providerSlugOf(picked);
      if (!key || seen.has(key)) return;
      seen.add(key);
      order.push(globalByKey.get(key) || picked);
    });
    if (order.length) return { order, allowFallbacks: rule.allowFallbacks === true };
  }
  if (settings.enableProviders === false) return { order: [], allowFallbacks: false };
  const seen = new Set();
  const order = (settings.providers || [])
    .filter(p => (typeof p === 'string' ? p.trim() : p && p.enabled !== false && (p.slug || '').trim()))
    .map(providerTextOf)
    .filter(slug => {
      const key = providerSlugOf(slug);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  return { order, allowFallbacks: settings.providerAllowFallbacks !== false };
}




function toRealProviderSlug(slug) {
  const s = (slug || '').trim();
  const lower = s.toLowerCase();
  const knownPseudo = new Set(['modal(api)', 'nvidia(api)', 'vercel(api)',    'inferx(api)', 'zenmux(api)', 'orcarouter(api)', 'llm7(api)', 'navy(api)', 'aihubmix(api)', 'unorouter(api)', 'literouter(api)', 'apinex(api)', 'anyapi(api)', 'nara(api)', 'zen(api)', 'openrouter(free)']);
  if (!s || knownPseudo.has(lower) || lower === 'openrouter') return '';
  
  return s.replace(/\((api|free)\)\s*$/i, '').trim();
}


function isFreePricedModel(model) {
  return !!(model && Number(model.pricing && model.pricing.prompt) === 0 && Number(model.pricing && model.pricing.completion) === 0);
}

function catalogHasFreeVariant(baseId) {
  const base = String(baseId || '').trim().replace(/:[^/]*$/, '');
  if (!base) return false;
  const wanted = (base + ':free').toLowerCase();
  const catalog = (state.modelCatalog && state.modelCatalog.models) || [];
  return catalog.some(m => (m.id || '').trim().toLowerCase() === wanted);
}

// OpenRouter's ":free" variants are ordinary catalog entries, and everything
// that answers "is this free on OpenRouter?" — the free-model list for the
// OpenRouter (Free) provider, catalogHasFreeVariant, the '$0 pricing' checks —
// is derived from that one catalog snapshot. state.modelCatalog persists in
// localStorage and its fetchedAt was written but never read, so nothing ever
// aged the snapshot out: a catalog fetched before OpenRouter published a free
// variant kept reporting that model as "not available" forever.
const MODEL_CATALOG_MAX_AGE_MS = 6 * 60 * 60 * 1000;
