  if (literouterIsFreeModel(directApiModelName('literouter', slug))) return true;
  if (apinexIsFreeModel(directApiModelName('apinex', slug))) return true;
  if (anyapiIsFreeModel(directApiModelName('anyapi', slug))) return true;
  if (naraIsFreeModel(directApiModelName('nara', slug))) return true;
  if (inferxIsFreeModel(directApiModelName('inferx', slug))) return true;
