let isFetchingProviders = false;
async function fetchProviderCatalog(silent) {
  if (isFetchingProviders) return;
  isFetchingProviders = true;
  const btn = document.getElementById('refreshProviderCatalogBtn');
  if (btn) { btn.disabled = true; btn.textContent = '…'; }
  try {
    const base = (state.apiSettings.apiUrl || '').replace(/\/chat\/completions\/?$/, '') || 'https://openrouter.ai/api/v1';
    const headers = {};
    if (state.apiSettings.apiKey) headers['Authorization'] = `Bearer ${state.apiSettings.apiKey}`;
    const resp = await fetch(`${base}/providers`, { headers });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const body = await resp.json();
    const providers = (body.data || [])
      .map(p => ({
        slug: (p.slug || '').trim(),
        name: (p.name || p.slug || '').trim(),
        headquarters: (p.headquarters || '').trim(),
      }))
      .filter(p => p.slug);
    providers.sort((a, b) => a.name.localeCompare(b.name) || a.slug.localeCompare(b.slug));
    if (!providers.length) throw new Error('empty list');
    state.providerCatalog = { fetchedAt: new Date().toISOString(), providers };
    saveState();
    renderProviderPickerOptions();
    renderProvidersEditor();
    if (!silent) showToast(`Loaded ${providers.length} providers from OpenRouter`, 'success');
  } catch (e) {
    if (!silent) showToast(`Could not load provider list: ${e.message}`, 'error');
  } finally {
    isFetchingProviders = false;
    const b2 = document.getElementById('refreshProviderCatalogBtn');
    if (b2) { b2.disabled = false; b2.textContent = '⟳ Refresh provider list'; }
  }
}


let providerPickerOpen = false;
function renderProviderPickerOptions() {
  const list = document.getElementById('providerPickerList'); if (!list) return;
  
  
  
  const scrollTop = list.scrollTop;
  const scrollLeft = list.scrollLeft;
  const restoreScroll = () => { list.scrollTop = scrollTop; list.scrollLeft = scrollLeft; };
  const catalog = getProviderCatalogEntries();
  const q = ((document.getElementById('providerPickerSearch') || {}).value || '').trim().toLowerCase();
  const already = new Set((providersDraft || []).map(p => (p.slug || '').trim().toLowerCase()).filter(Boolean));
  if (!catalog.length) {
    list.innerHTML = `<div class="mpk-empty">No provider list loaded yet. Click <strong>⟳ Refresh provider list</strong> to fetch every provider from OpenRouter, or type a slug below.</div>`;
    restoreScroll();
    return;
  }
  const matches = catalog.filter(p => {
    if (!q) return true;
    return p.slug.toLowerCase().includes(q) || (p.name || '').toLowerCase().includes(q)
      || (p.headquarters || '').toLowerCase().includes(q);
  }).slice(0, 300);
  if (!matches.length) {
    list.innerHTML = `<div class="mpk-empty">No providers match “${escapeHtml(q)}”.</div>`;
    restoreScroll();
    return;
  }
  list.innerHTML = matches.map(p => {
    const added = already.has(p.slug.toLowerCase());
    const hq = p.headquarters ? p.headquarters : '';
    const nameStr = (p.name && p.name !== p.slug) ? `<span>${escapeHtml(p.name)}</span>` : '';
    return `<div class="mpk-item ${added ? 'added' : ''}" data-slug="${escapeHtml(p.slug)}" data-name="${escapeHtml(p.name || p.slug)}" data-added="${added}" title="${added ? 'Already in the list' : 'Click to add'}">
      ${nameStr}<span class="mpk-id">${escapeHtml(p.slug)}</span><span class="mpk-ctx">${added ? '✓ added' : escapeHtml(hq)}</span>${added ? '<button type="button" class="mpk-remove" title="Remove from the list">Remove</button>' : ''}
    </div>`;
  }).join('');
  restoreScroll();
  list.querySelectorAll('.mpk-item').forEach(item => {
    item.onclick = () => { if (item.dataset.added !== 'true') addProviderToDraft(item.dataset.slug, item.dataset.name); };
    const remove = item.querySelector('.mpk-remove');
    if (remove) remove.onclick = (e) => {
      e.stopPropagation();
      removeProviderFromDraft(item.dataset.slug);
    };
  });
}
function removeProviderFromDraft(slug) {
  const id = (slug || '').trim().toLowerCase();
  const idx = (providersDraft || []).findIndex(p => (p.slug || '').trim().toLowerCase() === id);
  if (idx < 0) return;
  providersDraft.splice(idx, 1);
  openProviderInfo.clear();
  renderProvidersEditor();
  renderProviderPickerOptions();
  renderModelProvidersEditor();
  showToast(`Removed ${slug}`, 'success');
}
function addProviderToDraft(slug, name) {
  const id = (slug || '').trim();
  if (!id) return;
  const display = (name || '').trim() || providerDisplayName(id) || id;
  const existingIdx = (providersDraft || []).findIndex(p => (p.slug || '').trim().toLowerCase() === id.toLowerCase());
  if (existingIdx >= 0) { showToast(`${id} is already in the list`, 'info'); return; }
  const blankIdx = (providersDraft || []).findIndex(p => !(p.slug || '').trim());
  if (blankIdx >= 0) providersDraft[blankIdx] = { name: display, slug: id, enabled: true };
  else providersDraft.push({ name: display, slug: id, enabled: true });
  renderProvidersEditor();
  renderProviderPickerOptions();
  renderModelProvidersEditor();
  showToast(`Added ${display}`, 'success');
}
function toggleProviderPicker(force) {
  const box = document.getElementById('providerPicker'); if (!box) return;
  providerPickerOpen = force != null ? force : !providerPickerOpen;
  box.classList.toggle('open', providerPickerOpen);
  if (providerPickerOpen) {
    renderProviderPickerOptions();
    const search = document.getElementById('providerPickerSearch');
    if (search) { search.focus(); search.select(); }
    // Missing *or aged out*: an empty check alone left a cached list in place
    // forever. No-op when the snapshot is fresh.
    ensureProviderCatalog().catch(() => {});
  }
}
function initProviderPicker() {
  const search = document.getElementById('providerPickerSearch');
  if (search) search.oninput = () => renderProviderPickerOptions();
  const closeBtn = document.getElementById('providerPickerCloseBtn');
  if (closeBtn) closeBtn.onclick = () => toggleProviderPicker(false);
  const refreshBtn = document.getElementById('refreshProviderCatalogBtn');
  if (refreshBtn) refreshBtn.onclick = () => fetchProviderCatalog(false);
  const manual = document.getElementById('providerPickerManual');
  const manualAdd = document.getElementById('providerPickerManualAdd');
  const doManual = () => {
    if (!manual || !manual.value.trim()) return;
    const raw = manual.value.trim();
    
    let slug = raw, name = '';
    if (raw.includes('/')) {
      
      const m = raw.match(/^(.*?)\s*[(\[]\s*([a-z0-9][a-z0-9_-]*)\s*[)\]]\s*$/i);
      if (m) { name = m[1].trim(); slug = m[2].trim(); }
    }
    const slugOnly = slug.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9_-]/g, '');
    addProviderToDraft(slugOnly || slug, name || providerDisplayName(slugOnly || slug) || slug);
    manual.value = '';
  };
  if (manualAdd) manualAdd.onclick = doManual;
  if (manual) manual.onkeydown = (e) => { if (e.key === 'Enter') { e.preventDefault(); doManual(); } };
}


let webSearchProvidersDraft = [];
