function defaultFallbackModels() { return JSON.parse(JSON.stringify(DEFAULT_API_SETTINGS.fallbackModels)); }

function getFallbackModelSlugs(preset) {
  if (preset) {
    const p = getPresetSettings(preset);
    if (p && p.fallbackModels && Array.isArray(p.fallbackModels)) {
      const fbs = p.fallbackModels.map(m => (m && m.slug ? m.slug.trim() : '')).filter(Boolean);
      if (fbs.length > 0) return fbs;
    }
    return [];
  }
  return (state.apiSettings.fallbackModels || []).map(m => m.slug);
}


function getDefaultBigChatModel() {
  const all = (state.apiSettings.fallbackModels || []).map(m => (m.slug || '').trim()).filter(Boolean);
  const bigs = (state.apiSettings.fallbackModels || []).filter(m => m.size === 'big').map(m => (m.slug || '').trim()).filter(Boolean);
  return bigs[0] || all[0] || '';
}
function getBigModelSlugs() { return (state.apiSettings.fallbackModels || []).filter(m => m.size === 'big').map(m => m.slug); }
function getSmallModelSlugs() { return (state.apiSettings.fallbackModels || []).filter(m => m.size === 'small').map(m => m.slug); }

// "Auto" model mode: the thread's model field is empty, which means requests
// walk the ordered fallback list from Settings → Models & Routing (big models
// first, then small models) instead of being pinned to a single model.
function isBigChatAutoModel(model) { return !String(model || '').trim(); }
function bigChatAutoModelChain() {
  const list = state.apiSettings.fallbackModels || [];
  const seen = new Set();
  const chain = [];
  for (const m of list) {
    const slug = String((m && m.slug) || '').trim();
    if (!slug) continue;
    const key = slug.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    chain.push(slug);
  }
  return chain;
}
function bigChatModelsToTry(thread, model) {
  if (isBigChatAutoModel(model)) {
    const chain = bigChatAutoModelChain();
    if (chain.length) return chain;
  }
  return [model || getDefaultBigChatModel()];
}
// Auto mode has no single context window, and *every* model in the chain can
// serve any step (the run walks the list and falls back on failure), so the
// safe ceiling is the SMALLEST known window in the chain, not the largest.
// Sizing requests for the biggest entry is what let a ~321 KB prompt reach a
// smaller gateway, which answered by dropping the oldest messages — the system
// prompt and the user's request — instead of failing.
//
// When no window is known at all (the model list was never loaded, or the slug
// is served by a direct API OpenRouter does not list) the ceiling must still
// exist: a guard that quietly switches itself off is worse than a conservative
// one, because the failure it is meant to prevent is silent.
const AGENT_CONTEXT_UNKNOWN_FALLBACK = 32000;
function getBigChatAutoContextLimit() {
  let min = 0;
  for (const slug of bigChatAutoModelChain()) {
    const ctx = getModelContextLength(slug) || 0;
    if (ctx > 0 && (min === 0 || ctx < min)) min = ctx;
  }
  return min;
}
// The one place the run loop and the context meter resolve their ceiling.
function bigChatContextLimit(model) {
  return getModelContextLength(model) || getBigChatAutoContextLimit() || AGENT_CONTEXT_UNKNOWN_FALLBACK;
}
function getDefaultTtsModel() { return (state.apiSettings.defaultTtsModel || '').trim(); }
function getDefaultTtsVoice() {
  const saved = (state.apiSettings.defaultTtsVoice || '').trim();
  const model = getDefaultTtsModel();
  const cat = getCatalogModel(model);
  const voices = cat && Array.isArray(cat.voices) ? cat.voices : [];
  
  
  
  
  
  const savedForThisModel = (state.apiSettings.defaultTtsVoiceModel || '') === model;
  if (saved) {
    if (voices.length) {
      
      
      
      const match = voices.find(v => String(v).toLowerCase() === saved.toLowerCase());
      if (match) return match;
      return voices[0] || '';
    }
    return savedForThisModel ? saved : '';
  }
  return voices[0] || '';
}
function getDefaultTtsFormat() {
  
  
  
  
  return 'mp3';
}
function getDefaultTtsVolume() {
  const v = parseFloat(state.apiSettings.defaultTtsVolume);
  return isFinite(v) ? Math.max(0, Math.min(1, v)) : 1.0;
}
function getDefaultTtsSpeed() {
  const s = parseFloat(state.apiSettings.defaultTtsSpeed);
  return isFinite(s) ? Math.max(0.25, Math.min(4, s)) : 1.0;
}
function isSpeechModel(m) {
  if (!m) return false;
  const out = (m.outMod || []).map(x => String(x).toLowerCase());
  const params = (m.params || []).map(x => String(x).toLowerCase());
  const identity = `${m.id || ''} ${m.name || ''}`;
  
  
  return out.includes('speech') || out.includes('audio')
    || params.includes('speech') || params.includes('audio')
    || /tts|text[- ]to[- ]speech|speech|voice|kokoro|orpheus|zonos|aura|voxtral/i.test(identity);
}
function getTtsCatalogModels() {
  const catalog = (state.modelCatalog && state.modelCatalog.models) || [];
  return catalog.filter(isSpeechModel);
}

let fallbackDraft = [];


const bigChatRuns = {};            


const bigChatSubagentActivities = {}; 
const bigChatSubagentSelection = {};   
let nextBigChatSubagentActivityId = 1;
// Thread the workspace writes should attribute themselves to. The workspace is
// a global (agentFS) but per-thread snapshots live on the thread record; if the
// user switches threads mid-run, writes would otherwise be snapshotted onto
// whichever thread is NOW active. The run pins its own thread here (set/cleared
// by sendBigChatMessage; fall back to the active thread outside a run).
let workspaceOwnerThreadId = null;
function isThreadSending(id) { return !!(id && bigChatRuns[id]); }
function isActiveThreadSending() { const bc = getBigChatData(); return isThreadSending(bc.activeThreadId); }

function getBigChatSubagentActivities(threadId) {
  if (threadId && Array.isArray(bigChatSubagentActivities[threadId])) {
    return bigChatSubagentActivities[threadId];
  }
  // Persisted history: finished runs live on the thread record so they survive
  // reloads (and are deleted with the thread). Hydrate the in-memory map once.
  const thread = threadId ? getBigChatData().threads[threadId] : null;
  if (thread && Array.isArray(thread.subagentActivities)) {
    const restored = thread.subagentActivities.map((a) => ({ ...a, live: false }));
    bigChatSubagentActivities[threadId] = restored;
    return restored;
  }
  return [];
}
const BIGCHAT_SUBAGENT_DETAIL_LIMIT = 12000;
function capBigChatSubagentText(value) {
  const text = String(value == null ? '' : value);
  return text.length > BIGCHAT_SUBAGENT_DETAIL_LIMIT
    ? text.slice(0, BIGCHAT_SUBAGENT_DETAIL_LIMIT) + '\n… (truncated)'
    : text;
}
function queueBigChatSubagentSidebarRender(activity) {
  if (!activity || activity.renderQueued) return;
  activity.renderQueued = true;
  setTimeout(() => {
    activity.renderQueued = false;
    renderBigChatSubagentSidebar();
  }, 80);
}
function startBigChatSubagentActivity(thread, args, parentActivity) {
  const agentId = String((args && args.agent) || '').trim();
  const profile = Array.isArray(SUBAGENT_PROFILES) ? SUBAGENT_PROFILES.find(p => p.id === agentId) : null;
  if (!thread || !thread.id || !profile) return null;
  const now = Date.now();
  const activity = {
    id: `subagent-${now.toString(36)}-${nextBigChatSubagentActivityId++}`,
    threadId: thread.id,
    
    
    parentId: parentActivity && parentActivity.id ? parentActivity.id : null,
    depth: parentActivity ? ((parentActivity.depth || 0) + 1) : 0,
    agentId,
    name: profile.name || agentId,
    description: profile.description || '',
    task: String((args && args.task) || '').trim() || 'No task description provided.',
    context: String((args && args.context) || '').trim(),
    status: 'Starting…',
    statusHistory: [{ text: 'Starting…', at: now }],
    step: 0,
    stepTotal: 0,
    model: '',
    provider: '',
    
    
    modelOverride: '',
    thinking: '',
    output: '',
    toolEvents: [],
    
    
    
    
    transcript: [],
    live: true,
    startedAt: now,
  };
  if (!Array.isArray(bigChatSubagentActivities[thread.id])) bigChatSubagentActivities[thread.id] = [];
  const hadLiveActivity = bigChatSubagentActivities[thread.id].some(item => item.live !== false);
  bigChatSubagentActivities[thread.id].push(activity);
  if (!bigChatSubagentSelection[thread.id] || !hadLiveActivity) bigChatSubagentSelection[thread.id] = activity.id;
  renderBigChatSubagentSidebar();
  return activity;
}
function updateBigChatSubagentActivity(activity, status) {
  if (!activity) return;
  const raw = String(status || '').trim() || 'Working…';
  if (activity.status !== raw) {
    activity.status = raw;
    if (!Array.isArray(activity.statusHistory)) activity.statusHistory = [];
    activity.statusHistory.push({ text: raw, at: Date.now() });
    if (activity.statusHistory.length > 50) activity.statusHistory.splice(0, activity.statusHistory.length - 50);
  }
  const match = raw.match(new RegExp('step +([0-9]+)(?: *[/] *([0-9]+))?', 'i'));
  if (match) {
    activity.step = Number(match[1]);
    activity.stepTotal = match[2] ? Number(match[2]) : activity.stepTotal;
  }
  renderBigChatSubagentSidebar();
}
function beginBigChatSubagentRequest(activity, model, provider) {
  if (!activity) return;
  activity.model = bareModelSlug(model) || String(model || '').trim();
  activity.provider = provider || 'Auto';
  
  
  
  if (activity.thinking) activity.thinking = appendBigChatSubagentText(activity.thinking, '\n\n— next model response —\n');
  if (activity.output) activity.output = appendBigChatSubagentText(activity.output, '\n\n— next model response —\n');
  
  
  const turn = bigChatSubagentCurrentTurn(activity);
  turn.model = activity.model;
  turn.provider = activity.provider || null;
  turn.elapsed = null;
  activity.responseThinkingSeen = false;
  activity.responseContentSeen = false;
  activity.responseStartedAt = Date.now();
  activity.currentTool = '';
  queueBigChatSubagentSidebarRender(activity);
}
function appendBigChatSubagentText(current, addition) {
  const next = String(current || '') + String(addition || '');
  return capBigChatSubagentText(next);
}





let nextBigChatSubagentTurnId = 1;
function newBigChatSubagentTurnId() {
  return `t${(Date.now().toString(36))}${(nextBigChatSubagentTurnId++).toString(36)}`;
}
function ensureBigChatSubagentTranscript(activity) {
  if (!activity) return null;
  if (!Array.isArray(activity.transcript)) activity.transcript = [];
  return activity.transcript;
}
function bigChatSubagentCurrentTurn(activity) {
  const transcript = ensureBigChatSubagentTranscript(activity);
  let turn = transcript.length ? transcript[transcript.length - 1] : null;
  if (turn && turn.kind === 'assistant' && turn.active) return turn;
  turn = { id: newBigChatSubagentTurnId(), kind: 'assistant', active: true, live: true, startedAt: Date.now(), thinking: '', output: '', model: '', elapsed: null, toolEvents: [] };
  transcript.push(turn);
  return turn;
}
function finishBigChatSubagentTurn(activity) {
  if (!activity) return;
  const transcript = ensureBigChatSubagentTranscript(activity);
  const turn = transcript.length ? transcript[transcript.length - 1] : null;
  if (turn && turn.kind === 'assistant') {
    turn.active = false;
    turn.live = false;
    const start = turn.startedAt || activity.responseStartedAt;
    if (start) turn.elapsed = Math.max(0, (Date.now() - start) / 1000);
  }
}
function bigChatSubagentAppendUserTurn(activity, label, text) {
  if (!activity) return;
  const transcript = ensureBigChatSubagentTranscript(activity);
  transcript.push({ id: newBigChatSubagentTurnId(), kind: 'user', label: label || 'Message', text: String(text == null ? '' : text) });
}
function bigChatSubagentAppendAutoContinueTurn(activity, text) {
  if (!activity) return;
  const transcript = ensureBigChatSubagentTranscript(activity);
  transcript.push({ id: newBigChatSubagentTurnId(), kind: 'auto-continue', text: String(text == null ? '' : text) });
}
// Rehydrated partial response from a hard-kill recovery (see runSubagent).
function bigChatSubagentAppendRecoveredTurn(activity, content) {
  if (!activity) return;
  const transcript = ensureBigChatSubagentTranscript(activity);
  transcript.push({ id: newBigChatSubagentTurnId(), kind: 'assistant', active: false, live: false, startedAt: Date.now(), thinking: '', output: String(content || ''), model: '', elapsed: null, toolEvents: [] });
}
function updateBigChatSubagentStream(activity, delta) {
  if (!activity || !delta) return;
  if (delta.reset) {
    activity.responseThinkingSeen = false;
    activity.responseContentSeen = false;
  }
  if (delta.reasoning) {
    activity.responseThinkingSeen = true;
    activity.thinking = appendBigChatSubagentText(activity.thinking, delta.reasoning);
    const turn = bigChatSubagentCurrentTurn(activity);
    turn.thinking = appendBigChatSubagentText(turn.thinking, delta.reasoning);
  }
  if (delta.content) {
    activity.responseContentSeen = true;
    activity.output = appendBigChatSubagentText(activity.output, delta.content);
    const turn = bigChatSubagentCurrentTurn(activity);
    turn.output = appendBigChatSubagentText(turn.output, delta.content);
  }
  // Hard-kill durability: debounce a flush of the in-flight streamed reply.
  scheduleSubagentLiveFlush(activity);
  queueBigChatSubagentSidebarRender(activity);
}
function startBigChatSubagentToolEvent(activity, toolCall) {
  if (!activity) return null;
  if (!Array.isArray(activity.toolEvents)) activity.toolEvents = [];
  const event = {
    id: String((toolCall && toolCall.id) || `tool-${Date.now().toString(36)}-${activity.toolEvents.length + 1}`),
    name: String(toolCall && toolCall.function && toolCall.function.name || 'unknown tool'),
    args: parseJsonSafe(toolCall && toolCall.function && toolCall.function.arguments),
    status: 'running',
    ok: null,
    output: '',
    startedAt: Date.now(),
  };
  activity.toolEvents.push(event);
  
  const turn = bigChatSubagentCurrentTurn(activity);
  if (!Array.isArray(turn.toolEvents)) turn.toolEvents = [];
  turn.toolEvents.push(event);
  activity.currentTool = event.name;
  queueBigChatSubagentSidebarRender(activity);
  return event;
}
function finishBigChatSubagentToolEvent(activity, event, result) {
  if (!event) return;
  event.ok = result && result.ok === false ? false : true;
  event.status = event.ok ? 'done' : 'error';
  event.output = capBigChatSubagentText(result && result.content || '(no output)');
  event.finishedAt = Date.now();
  queueBigChatSubagentSidebarRender(activity);
}
function requestStopBigChatSubagent(activity) {
  if (!activity || activity.live === false) return false;
  // Cascade: stopping a parent also stops every live descendant it delegated
  // to, so no orphaned children keep running after the parent is stopped.
  const targets = new Set([activity]);
  if (activity.threadId) {
    const all = getBigChatSubagentActivities(activity.threadId);
    let grew = true;
    while (grew) {
      grew = false;
      for (const a of all) {
        if (targets.has(a) || a.live === false) continue;
        if (a.parentId && targets.has(all.find(x => x.id === a.parentId))) {
          targets.add(a);
          grew = true;
        }
      }
    }
  }
  for (const target of targets) {
    if (target.live === false) continue;
    target.stopRequested = true;
    if (target.stopController && !target.stopController.signal.aborted) {
      try { target.stopController.abort(); } catch {}
    }
    if (!String(target.status || '').includes('stopped')) {
      target.status = 'Stopping…';
      if (!Array.isArray(target.statusHistory)) target.statusHistory = [];
      target.statusHistory.push({ text: 'Stopping… (requested by user)', at: Date.now() });
    }
  }
  renderBigChatSubagentSidebar();
  return true;
}

// Run-level Stop: stop every LIVE subagent in a thread, not just the ones a
// particular sidebar ✋ targets. Aborting the parent run's fetch does not stop
// subagents — each holds its own AbortController, so without this they would
// keep spending their full step budget after the user pressed Stop.
// Also cancels delegates still queued behind the parallel-worker limit.
function requestStopAllBigChatSubagents(threadId) {
  if (!threadId) return;
  const all = getBigChatSubagentActivities(threadId);
  let stoppedAny = false;
  for (const target of all) {
    if (!target || target.live === false) continue;
    stoppedAny = true;
    target.stopRequested = true;
    if (target.stopController && !target.stopController.signal.aborted) {
      try { target.stopController.abort(); } catch {}
    }
    const st = String(target.status || '');
    if (!st.includes('stopped') && !st.includes('Stopping')) {
      target.status = 'Stopping…';
      if (!Array.isArray(target.statusHistory)) target.statusHistory = [];
      target.statusHistory.push({ text: 'Stopping… (run stopped)', at: Date.now() });
    }
  }
  if (stoppedAny) renderBigChatSubagentSidebar();
  cancelQueuedSubagentsForThread(threadId);
}

// ---- Pause (graceful, per sub-agent) ----
// Pausing is deliberately NOT stopping: it never aborts the in-flight model
// request and never writes any "stopped by user" note into the Big Chat
// transcript. The run finishes its current step, then parks at the step
// boundary and waits — holding its parallel-worker slot — until the user
// resumes it. A parked run is also safe across an app restart: the transcript
// lives in state.subagentHistory and the paused flag in state.subagentPaused,
// so a fresh delegate of the same profile continues exactly where it stopped.
// Pausing a parent cascades to its live descendants so children don't keep
// burning steps behind a parked parent.
function requestPauseBigChatSubagent(activity, opts) {
  if (!activity || activity.live === false) return false;
  if (activity.stopRequested || (activity.stopController && activity.stopController.signal.aborted)) return false;
  const autoClose = !!(opts && opts.reason === 'app-close');
  const targets = new Set([activity]);
  if (activity.threadId) {
    const all = getBigChatSubagentActivities(activity.threadId);
    let grew = true;
    while (grew) {
      grew = false;
      for (const a of all) {
        if (targets.has(a) || a.live === false) continue;
        if (a.parentId && targets.has(all.find(x => x.id === a.parentId))) {
          targets.add(a);
          grew = true;
        }
      }
    }
  }
  let pausedAny = false;
  for (const target of targets) {
    if (target.live === false || target.pauseRequested || target.stopRequested) continue;
    target.pauseRequested = true;
    pausedAny = true;
    if (!String(target.status || '').includes('Pausing')) {
      target.status = autoClose ? 'Pausing (app closing)…' : 'Pausing after this step…';
      if (!Array.isArray(target.statusHistory)) target.statusHistory = [];
      target.statusHistory.push({ text: autoClose ? 'Pausing after this step… (auto — the app is closing)' : 'Pausing after this step… (requested by user)', at: Date.now() });
    }
  }
  if (pausedAny) renderBigChatSubagentSidebar();
  return pausedAny;
}
// Wake a parked (in-session paused) sub-agent. Like pausing, resuming stays
// entirely inside the sidebar — Big Chat is not involved at all.
function requestResumePausedBigChatSubagent(activity) {
  if (!activity || activity.live === false || !activity.paused || !activity.pauseRequested) return false;
  activity.pauseRequested = false;
  return true;
}
// Parked-run bookkeeping. The paused flag lives in state.subagentPaused keyed
// by the same subagentHistory key the run saved its transcript under, so it
// survives an app restart. A later delegate of the same profile consumes it
// and tells the model to continue from the remembered transcript.
function parkPausedSubagentHistory(profileId, threadId, chain, activity) {
  if (!profileId) return;
  state.subagentPaused = state.subagentPaused || {};
  const base = subagentHistoryKey(profileId, threadId, chain);
  const exact = subagentHistoryKeyForActivity(profileId, threadId, chain, activity);
  const mark = { at: Date.now(), activityId: (activity && activity.id) || null };
  state.subagentPaused[exact] = mark;
  if (exact !== base) state.subagentPaused[base] = { ...mark };
  saveState();
}
function unparkPausedSubagentHistory(profileId, threadId, chain) {
  if (!profileId || !state.subagentPaused) return;
  const base = subagentHistoryKey(profileId, threadId, chain);
  delete state.subagentPaused[base];
  for (const k of Object.keys(state.subagentPaused)) {
    if (k.startsWith(base + '#')) delete state.subagentPaused[k];
  }
  saveState();
}
function isSubagentHistoryPaused(profileId, threadId, chain) {
  if (!state.subagentPaused) return false;
  const base = subagentHistoryKey(profileId, threadId, chain);
  if (state.subagentPaused[base]) return true;
  return Object.keys(state.subagentPaused).some(k => k.startsWith(base + '#'));
}
// Paused runs survive an app restart by being snapshotted onto the thread
// record (thread.subagentActivities) — getBigChatSubagentActivities hydrates
// them back into the sidebar on load, complete with a ▶ Continue button.
function syncPausedSubagentThreadRecord(threadId) {
  try {
    if (!threadId) return;
    const bc = getBigChatData();
    const thread = bc && bc.threads ? bc.threads[threadId] : null;
    if (!thread) return;
    const list = Array.isArray(bigChatSubagentActivities[threadId]) ? bigChatSubagentActivities[threadId] : [];
    const paused = list
      .filter(a => a && a.paused && !a.stopped)
      .map(a => {
        const { stopController, renderQueued, removeTimer, ...rest } = a;
        return JSON.parse(JSON.stringify(rest));
      });
    const prev = Array.isArray(thread.subagentActivities) ? thread.subagentActivities : [];
    if (prev.length === paused.length && JSON.stringify(prev) === JSON.stringify(paused)) return;
    thread.subagentActivities = paused;
    saveState();
  } catch (e) { /* best effort — the sidebar still works without persistence */ }
}

// ---- Hard-kill durability for live sub-agent transcripts ----
// A sub-agent's API messages used to be saved only at run exits, so a crash or
// power loss mid-step threw away every step since the run started (plus the
// response that was streaming at that moment). Each run registers its live
// transcript here; stream deltas debounce a flush that persists the messages
// array plus the in-flight partial response under the same subagentHistory
// key the resume path reads. A hard kill now loses at most ~2.5s of tokens.
const SUBAGENT_LIVE_FLUSH_MS = 2500;
const liveSubagentTranscripts = {}; // activityId -> { activity, profile, threadId, chain, messages, lastFlushAt, timer }
function registerLiveSubagentTranscript(activity, profile, threadId, chain, messages) {
  if (!activity || !activity.id || !profile || profile.maintainHistory === false) return;
  liveSubagentTranscripts[activity.id] = { activity, profile, threadId, chain, messages, lastFlushAt: 0, timer: null };
}
function unregisterLiveSubagentTranscript(activityId) {
  const entry = liveSubagentTranscripts[activityId];
  if (!entry) return;
  if (entry.timer) clearTimeout(entry.timer);
  delete liveSubagentTranscripts[activityId];
}
function scheduleSubagentLiveFlush(activity) {
  const entry = activity && liveSubagentTranscripts[activity.id];
  if (!entry || entry.timer) return;
  entry.timer = setTimeout(() => {
    entry.timer = null;
    flushSubagentLiveTranscript(activity, false);
  }, SUBAGENT_LIVE_FLUSH_MS);
}
function flushSubagentLiveTranscript(activity, force) {
  const entry = activity && liveSubagentTranscripts[activity.id];
  if (!entry) return;
  const now = Date.now();
  if (!force && now - entry.lastFlushAt < SUBAGENT_LIVE_FLUSH_MS) { scheduleSubagentLiveFlush(activity); return; }
  entry.lastFlushAt = now;
  // The in-flight partial is the active assistant turn's streamed output (a
  // finished turn means the response already lives in the messages array).
  let partial = '';
  const transcript = Array.isArray(activity.transcript) ? activity.transcript : [];
  const turn = transcript.length ? transcript[transcript.length - 1] : null;
  if (turn && turn.kind === 'assistant' && turn.active) partial = String(turn.output || '');
  rememberSubagent(entry.profile, entry.messages, entry.threadId, entry.chain, activity, partial);
}
function flushAllLiveSubagentTranscripts() {
  for (const entry of Object.values(liveSubagentTranscripts)) {
    try { flushSubagentLiveTranscript(entry.activity, true); } catch {}
  }
}

// ---- Auto-pause on window close ----
// Closing the window while sub-agents are mid-run would kill them mid-step.
// Instead, the beforeunload handler holds the window open and gracefully
// pauses every live sub-agent (their in-flight requests finish, then they
// park exactly like a manual ⏸), waits until all of them have parked, saves
// state, and only then lets the window close. Clicking close again during the
// wind-down force-closes immediately, and a hard cap bounds the wait so a
// hung request can never trap the user.
const SUBAGENT_CLOSE_WIND_DOWN_MS = 120000;
let subagentCloseWindDown = null;   // { action: 'close'|'reload', startedAt, timer }
let subagentCloseWindDownForce = false; // consumed by the next beforeunload
function liveSubagentCount() {
  let n = 0;
  for (const list of Object.values(bigChatSubagentActivities)) {
    for (const a of (list || [])) if (a && a.live !== false) n++;
  }
  return n;
}
function isSubagentCloseWindDownActive() { return !!subagentCloseWindDown; }
function beginSubagentCloseWindDown(action) {
  if (subagentCloseWindDown) return;
  subagentCloseWindDown = { action: action || 'close', startedAt: Date.now(), timer: null };
  let paused = 0;
  // Graceful ⏸ on every live sub-agent across every thread. Each run finishes
  // its current step, parks, and saves its transcript + paused flag — the same
  // state a manual pause leaves, fully resumable after relaunch.
  for (const list of Object.values(bigChatSubagentActivities)) {
    for (const a of (list || [])) {
      if (!a || a.live === false) continue;
      if (requestPauseBigChatSubagent(a, { reason: 'app-close' })) paused++;
    }
  }
  // Wind down active Big Chat orchestrator runs: the abort makes each loop end
  // right after its current tool batch resolves (the delegates park first), so
  // no further model request is started and no new sub-agents are spawned.
  // The run's own cleanup is guarded to NOT stop sub-agents while pausing.
  for (const run of Object.values(bigChatRuns)) {
    if (run && run.controller && !run.controller.signal.aborted) {
      try { run.controller.abort(); } catch {}
    }
  }
  // An open ask_user prompt would otherwise hold its tool call open forever —
  // dismiss it so the run can reach its aborted-call break cleanly.
  try { resolveAskUserQuestion(undefined); } catch {}
  try { clearBigChatQuestionQueue(); } catch {}
  if (paused) showToast(`⏸ Pausing ${paused} sub-agent${paused === 1 ? '' : 's'} before close — click close again to force`, 'info');
  finishSubagentCloseWindDownWhenParked();
}
function finishSubagentCloseWindDownWhenParked() {
  const wd = subagentCloseWindDown;
  if (!wd) return;
  if (liveSubagentCount() > 0 && Date.now() - wd.startedAt < SUBAGENT_CLOSE_WIND_DOWN_MS) {
    if (wd.timer) clearTimeout(wd.timer);
    wd.timer = setTimeout(finishSubagentCloseWindDownWhenParked, 500);
    return;
  }
  subagentCloseWindDown = null;
  if (wd.timer) clearTimeout(wd.timer);
  try { saveState(); } catch {}
  // Skip the live-subagent check in beforeunload: the wait is over (or timed
  // out) and the user asked to leave.
  subagentCloseWindDownForce = true;
  if (wd.action === 'reload') location.reload();
  else window.close();
}

// Resume a stopped/finished sub-agent run: re-invoke the same profile with the
// same delegation chain. runSubagent keys its conversation history by
// profile+thread+chain (subagentHistoryKey), so re-invoking with the same
// chain resumes the model conversation where the stop left off.
const SUBAGENT_RESUME_PROMPT = (
  'Continue the assigned task from where you stopped. Do not repeat work already '
  + 'completed; pick up from the latest state and finish the task.'
);
const SUBAGENT_MIDSTREAM_CONTINUE_PROMPT = (
  'Your previous response above was cut off mid-stream when the app shut down. '
  + 'Continue it from exactly where it stopped — do not apologize, do not start over, and do not repeat what you already wrote.'
);
function resumeBigChatSubagent(activity) {
  if (!activity || activity.live !== false) return false;
  const thread = getActiveBigChatThread();
  if (!thread || !thread.id || thread.id !== activity.threadId) return false;
  if (!getBigChatEnabledSubagentIds(thread).has(activity.agentId)) return false;
  // Rebuild the delegation chain the run originally used (fallback: direct
  // delegation from the Big Chat orchestrator).
  const chain = Array.isArray(activity.chain) && activity.chain.length
    ? activity.chain.slice(0, -1)
    : [];
  activity.live = true;
  activity.stopped = false;
  activity.stopRequested = false;
  activity.paused = false;
  activity.pauseRequested = false;
  unparkPausedSubagentHistory(activity.agentId, activity.threadId, chain);
  syncPausedSubagentThreadRecord(activity.threadId);
  activity.ok = null;
  activity.finishedAt = null;
  activity.status = 'Resuming…';
  if (!Array.isArray(activity.statusHistory)) activity.statusHistory = [];
  activity.statusHistory.push({ text: 'Resuming… (requested by user)', at: Date.now() });
  renderBigChatSubagentSidebar();
  // Memory-less profiles have no saved conversation to lean on — hand the
  // resume prompt the original task and the last output so the fresh run
  // knows what it is continuing (otherwise it would receive only a bare
  // "continue" instruction with no context at all).
  const resumeProfile = SUBAGENT_PROFILES.find(p => p && p.id === activity.agentId);
  const resumePrompt = resumeProfile && resumeProfile.maintainHistory === false
    ? `Original task: ${String(activity.task || '').trim() || '(no task recorded)'}`
      + (String(activity.output || '').trim()
        ? `\n\nYour previous run produced this before it stopped:\n\n${String(activity.output).slice(-6000)}\n\n`
        : '\n\n')
      + 'Continue the assigned task from where it stopped. Do not repeat work already completed; pick up from the latest state and finish the task.'
    : SUBAGENT_RESUME_PROMPT;
  const setStatus = (status) => updateBigChatSubagentActivity(activity, status);
  // Resumes go through the same parallel-worker slot as fresh delegates so the
  // cap stays honest; a resume cancelled while queued just finishes as stopped.
  withSubagentSlot(thread.id, () => runSubagent(activity.agentId, resumePrompt, '', state.apiSettings, setStatus, activity, chain))
    .catch((e) => {
      if (e && e.cancelledQueued) { activity.stopped = true; return { ok: false, content: 'Resume cancelled while queued behind the parallel-worker limit.' }; }
      throw e;
    })
    .finally(() => finishBigChatSubagentActivity(activity, { ok: !activity.stopped }));
  return true;
}
function finishBigChatSubagentActivity(activity, result) {
  if (!activity || !activity.threadId) return;
  unregisterLiveSubagentTranscript(activity.id);
  const list = getBigChatSubagentActivities(activity.threadId);
  if (!list.includes(activity)) return;
  activity.live = false;
  activity.ok = !!result && result.ok !== false;
  activity.paused = !!activity.paused && !activity.stopped;
  activity.pauseRequested = false;
  activity.finishedAt = Date.now();
  activity.status = activity.stopped ? 'Stopped by user' : (activity.paused ? 'Paused' : (activity.ok ? 'Completed' : 'Failed'));
  if (!Array.isArray(activity.statusHistory)) activity.statusHistory = [];
  activity.statusHistory.push({ text: activity.status, at: activity.finishedAt });
  activity.currentTool = '';
  finishBigChatSubagentTurn(activity);
  syncPausedSubagentThreadRecord(activity.threadId);
  renderBigChatSubagentSidebar();
  
  
  
}
function deleteBigChatSubagentActivity(threadId, activityId) {
  if (!threadId || !activityId) return;
  const current = getBigChatSubagentActivities(threadId);
  const idx = current.findIndex(a => a.id === activityId);
  if (idx < 0) return;
  const activity = current[idx];
  if (activity.removeTimer) clearTimeout(activity.removeTimer);
  // Removing a live (running or parked) tab ends the run — otherwise a parked
  // pause would poll forever and a running one would keep burning steps
  // invisibly.
  if (activity.live !== false) requestStopBigChatSubagent(activity);
  current.splice(idx, 1);
  if (!current.length) {
    delete bigChatSubagentActivities[threadId];
    delete bigChatSubagentSelection[threadId];
  } else if (bigChatSubagentSelection[threadId] === activityId) {
    bigChatSubagentSelection[threadId] = current[0].id;
  }
  syncPausedSubagentThreadRecord(threadId);
  renderBigChatSubagentSidebar();
}
function clearBigChatSubagentActivities(threadId) {
  const clearList = (list) => {
    (list || []).forEach(activity => {
      if (activity.removeTimer) clearTimeout(activity.removeTimer);
      if (activity.renderQueued) activity.renderQueued = false;
      // A live (running or parked) sub-agent must not outlive the clear — stop
      // it so parked pause-polls exit and running ones abort.
      if (activity && activity.live !== false) requestStopBigChatSubagent(activity);
    });
  };
  if (threadId) {
    clearList(bigChatSubagentActivities[threadId]);
    delete bigChatSubagentActivities[threadId];
    delete bigChatSubagentSelection[threadId];
    syncPausedSubagentThreadRecord(threadId);
  } else {
    const allIds = Object.keys(bigChatSubagentActivities);
    allIds.forEach(id => clearList(bigChatSubagentActivities[id]));
    allIds.forEach(id => { delete bigChatSubagentActivities[id]; syncPausedSubagentThreadRecord(id); });
    Object.keys(bigChatSubagentSelection).forEach(id => delete bigChatSubagentSelection[id]);
  }
  renderBigChatSubagentSidebar();
}

Object.defineProperty(window, 'isBigChatSending', { get: () => isActiveThreadSending() });
let bigChatAbortController = null;
let chatAbortController = null;
let runAbortController = null;
let nextTurnId = 1;
let isRunning = false;
let isChatSending = false;
let isTesting = false;


const STORAGE_KEY = 'openrouter_preset_runner_state_v3';
const BIG_CHAT_SUBAGENTS_DEFAULT_WIDTH = 286;
const BIG_CHAT_SUBAGENTS_MIN_WIDTH = 220;
const BIG_CHAT_SUBAGENTS_MAX_WIDTH = 640;
const BIG_CHAT_SUBAGENTS_MIN_MAIN_WIDTH = 320;

function normalizeBigChatSubagentsWidth(value) {
  const width = Number(value);
  if (!Number.isFinite(width)) return BIG_CHAT_SUBAGENTS_DEFAULT_WIDTH;
  return Math.round(Math.min(BIG_CHAT_SUBAGENTS_MAX_WIDTH, Math.max(BIG_CHAT_SUBAGENTS_MIN_WIDTH, width)));
}

function saveState() {
  try {
    const toSave = {
      apiSettings: state.apiSettings,
      turns: state.turns,
      conversations: state.conversations,
      nextTurnId: nextTurnId,
      activeChatPreset: state.activeChatPreset,
      activeTab: state.activeTab,
      theme: state.theme,
      themeColors: state.themeColors,
      collapsedFolders: state.collapsedFolders,
      sidebars: state.sidebars,
      sidebarsTouched: state.sidebarsTouched,
      bigChatSubagentsWidth: state.bigChatSubagentsWidth,
      defaultPresetColor: state.defaultPresetColor,
      presetPalette: state.presetPalette,
      bigChat: cloneBigChatForSave(state.bigChat),
      modelCatalog: state.modelCatalog,
      providerCatalog: state.providerCatalog,
      arenaCatalog: state.arenaCatalog,
      settingsTab: window._currentSettingsTab || 'api',
      _threadCounter: _threadCounter,
      presets: state.presets,
      subagentHistory: state.subagentHistory,
      subagentPaused: state.subagentPaused,
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(toSave));
  } catch (e) { console.warn('Could not save state:', e); }
}

// A save is cheap for a new conversation and very much not for a long one: it
// deep-clones the whole Big Chat state, stringifies everything, and writes it
// to localStorage synchronously. Input handlers that fire per keystroke must
// not pay that per key, so they coalesce into one save instead — the pagehide /
// beforeunload flush below guarantees a fast close still persists the edit.
const STATE_SAVE_DEBOUNCE_MS = 400;
let stateSaveSoonTimer = null;
function saveStateSoon() {
  if (stateSaveSoonTimer) return;
  stateSaveSoonTimer = setTimeout(() => { stateSaveSoonTimer = null; saveState(); }, STATE_SAVE_DEBOUNCE_MS);
}
function flushStateSaveSoon() {
  if (!stateSaveSoonTimer) return;
  clearTimeout(stateSaveSoonTimer);
  stateSaveSoonTimer = null;
  saveState();
}





function cloneBigChatForSave(bigChat) {
  
  
  
  
  const parked = [];
  for (const t of Object.values((bigChat && bigChat.threads) || {})) {
    if (t && t.workspace && typeof t.workspace === 'object') {
      parked.push([t, t.workspace]);
      t.workspace = { usingReal: !!t.workspace.usingReal, rootLabel: String(t.workspace.rootLabel || 'memory') };
    }
  }
  let clone;
  try {
    clone = JSON.parse(JSON.stringify(bigChat || {}));
  } finally {
    for (const [t, ws] of parked) t.workspace = ws;
  }
  for (const t of Object.values(clone.threads || {})) {
    for (const m of (t.messages || [])) {
      for (const a of (m.attachments || [])) {
        if (a && typeof a.dataUrl === 'string' && a.dataUrl.length > BIGCHAT_ATTACH_VAULT_MIN_CHARS) {
          delete a.dataUrl;
        }
      }
    }
  }
  return clone;
}

function migrateConversations() {
  
  for (const [preset, val] of Object.entries(state.conversations)) {
    if (Array.isArray(val)) {
      
      const thread = newThread('Main');
      thread.messages = val;
      state.conversations[preset] = { threads: { [thread.id]: thread }, activeThreadId: thread.id };
    } else if (val && typeof val === 'object' && !val.threads) {
      
      const thread = newThread('Main');
      state.conversations[preset] = { threads: { [thread.id]: thread }, activeThreadId: thread.id };
    }
    
    if (state.conversations[preset] && state.conversations[preset].threads) {
      for (const tid of Object.keys(state.conversations[preset].threads)) {
        const t = state.conversations[preset].threads[tid];
        if (!t.id) t.id = tid;
        if (!t.name) t.name = 'Main';
        if (!t.createdAt) t.createdAt = new Date().toISOString();
        if (!Array.isArray(t.messages)) t.messages = [];
      }
    }
  }
  
  if (state.bigChat && !state.bigChat.threads) {
    const thread = newBigChatThread('Main');
    thread.model = state.bigChat.model || '';
    thread.provider = state.bigChat.provider || '';
    if (state.bigChat.systemPrompt !== undefined) {
      thread.systemPrompt = state.bigChat.systemPrompt || '';
      thread.bigChatSystemPromptCustomized = !!thread.systemPrompt.trim();
    }
    thread.messages = Array.isArray(state.bigChat.messages) ? state.bigChat.messages : [];
    state.bigChat = { threads: { [thread.id]: thread }, activeThreadId: thread.id };
  }
  if (state.bigChat && state.bigChat.threads) {
    for (const tid of Object.keys(state.bigChat.threads)) {
      const t = state.bigChat.threads[tid];
      if (!t.id) t.id = tid;
      if (!t.name) t.name = 'Main';
      if (!t.createdAt) t.createdAt = new Date().toISOString();
      if (!Array.isArray(t.messages)) t.messages = [];
      if (t.model === undefined) t.model = ''; // Auto: walk the fallback list
      if (t.provider === undefined) t.provider = '';
      if (t.thinkingLevel === undefined) t.thinkingLevel = 'auto';
      normalizeBigChatSystemPrompt(t);
      if (!Array.isArray(t.bigChatManualTools)) t.bigChatManualTools = [];
    }
  }
}

