    if (p in agentFS.dirs) {
      const prefix = p + '/';
      for (const key of Object.keys(agentFS.mem)) if (key.startsWith(prefix)) { delete agentFS.mem[key]; fileHistory.delete(key); }
      for (const d of Object.keys(agentFS.dirs)) if (d === p || d.startsWith(prefix)) delete agentFS.dirs[d];
      snapshotWorkspaceToThread(activeWorkspaceThread());
      webappNotifyFileTouched(p);
      return p;
    }
    if (!(p in agentFS.mem)) throw new Error(`No such file: ${p}`);
