  const p = '/' + String(relPath || '').replace(/^\/+/, '');
  const base = webappLive.mode === 'inline' ? '/index.html' : (webappLive.servedPath || '/');
  if (p === base || p.startsWith(base.endsWith('/') ? base : base + '/')) webappScheduleReload();
