// Push subscription from main (disk watcher). Guarded so browser builds and
// older preloads without the bridge silently skip auto-reload.
//
// The payload names the root the watcher is on, and the subscription MUST honour
// it: main only ever has one watcher, but it is replaced lazily (on the next
// serve), so a push can still arrive from a root this preview no longer belongs
// to. Accepting it would schedule a reload that re-serves the stale root — the
// case that bites when the workspace is re-mounted while an app served from the
// old folder is still live, where every edit under the abandoned folder would
// otherwise restart the dead app.
if (IS_DESKTOP && window.desktopAgent.webappOnFilesChanged) {
  window.desktopAgent.webappOnFilesChanged((payload) => {
    if (!webappLive || webappLive.mode !== 'disk') return;
    const root = payload && payload.root;
    // Not this preview's root (an older watcher, or a root that has moved on).
    if (!root || !webappLive.servedRoot || root !== webappLive.servedRoot) return;
    // The workspace was re-mounted since this app was served: its files no
    // longer come from the mounted folder, so it must not auto-reload (its
    // reload path would re-resolve the old mount anyway).
    if (webappLive.mountRoot !== (agentFS.rootPath || '')) return;
    webappScheduleReload();
  });
}




function regexEscapeChar(c) { return /[\\^$.*+?()[\]{}|]/.test(c) ? '\\' + c : c; }
function globToRegex(pattern) {
  const p = String(pattern || '').replace(/\\/g, '/');
  let out = '^';
  for (let i = 0; i < p.length; i++) {
    const c = p[i];
    if (c === '*') {
      if (p[i + 1] === '*') {
        if (p[i + 2] === '/') { out += '(?:.*/)?'; i += 2; continue; }
        out += '.*'; i += 1; continue;
      }
      out += '[^/]*'; continue;
    }
    if (c === '?') { out += '[^/]'; continue; }
    if (c === '{') {
      const end = p.indexOf('}', i);
      if (end > i) { out += '(' + p.slice(i + 1, end).split(',').map(s => s.split('').map(regexEscapeChar).join('')).join('|') + ')'; i = end; continue; }
    }
    if (c === '[') {
      const end = p.indexOf(']', i);
      if (end > i) { out += p.slice(i, end + 1); i = end; continue; }
    }
    out += regexEscapeChar(c);
  }
  try { return new RegExp(out + '$'); } catch { return new RegExp('^$'); }
}
// Standard ignore list for workspace walks (fs_search / glob / the Files tree
