    async function walk(handle, prefix) {
      for await (const [name, h] of handle.entries()) {
        const p = prefix + '/' + name;
        if (h.kind === 'directory') {
          if (prefix === '' && WORKSPACE_IGNORED_DIRS.has(name)) continue;
          try { await walk(h, p); } catch {}
        }
        else files.push(normalizeAgentPath(p));
      }
    }
