  const dir = opts.path ? normalizeAgentPath(opts.path) : '/';
  const caseSensitive = !!opts.case_sensitive;
  let re;
  try { re = new RegExp(String(pattern), caseSensitive ? '' : 'i'); } catch (e) { throw new Error('Invalid regex: ' + e.message); }
  const context = Math.max(0, Math.min(5, Math.floor(Number(opts.context) || 0)));
  const maxResults = Math.max(1, Math.min(200, Math.floor(Number(opts.max_results) || 40)));
