async function buildMemoryContext(thread) {
  const parts = [];
  if (state.apiSettings.agentMemoryEnabled !== false) {
    try {
      const mem = await readMemoryFile();
      if (mem && mem.trim()) parts.push(`## Project memory (${memoryFilePath()})\n${mem.trim()}`);
    } catch {}
  }
  try {
    const caps = await buildEnabledCapabilitiesContext(thread);
    if (caps) parts.push(caps);
  } catch {}
  return parts.join('\n\n');
}


async function buildEnabledCapabilitiesContext(thread) {
  const sections = [];
  if (state.apiSettings.skillsEnabled !== false) {
    try {
      const skills = await listSkills();
      if (skills.length) {
        sections.push('## Enabled skills\n' + skills.map(s => `- ${s.name}: ${s.description}`).join('\n'));
      }
    } catch {}
  }
  const subagentIds = getBigChatEnabledSubagentIds(thread);
  const subagents = SUBAGENT_PROFILES.filter(p => subagentIds.has(p.id));
  if (subagents.length) {
    sections.push('## Enabled default sub-agents (delegate tool)\n' + subagents.map(p => {
      // Surface each profile's memory setting so the orchestrator composes
      // self-contained tasks for stateless sub-agents and re-delegates to
      // memory-ful ones when it wants iteration or follow-up.
      const memory = p.maintainHistory === false
        ? 'memory: none — every delegate call starts a fresh conversation, so put ALL needed context in the task itself'
        : 'memory: keeps its conversation in this thread — re-delegate to iterate, refine or follow up without restating everything';
      return `- ${p.id}: ${p.description || p.name} (${memory})`;
    }).join('\n'));
  }
  const presetIds = getBigChatEnabledPresetIds(thread);
  const presets = (state.presets || []).filter(p => presetIds.has(p.id));
  if (presets.length) {
    sections.push('## Enabled presets (call_preset / retry_preset tools)\n' + presets.map(p => `- ${p.name} (${p.id})`).join('\n'));
  }
  return sections.join('\n\n');
}


const BUILTIN_SKILLS = [
  { name: 'code-review', description: 'Systematic bug, security and style review of workspace code. Use when asked to review code or look for problems.',
    body: '# Code Review\n## Steps\n1. Read the relevant files (fs_read/fs_search) and understand intent.\n2. Check correctness: off-by-one, null handling, error paths, race conditions.\n3. Check security: injection, unsafe eval, path traversal, secrets in output.\n4. Check style and clarity: naming, duplication, dead code.\n5. Report findings ordered by severity with file:line references and a concrete fix for each.' },
  { name: 'web-research', description: 'Research a topic by searching the web and fetching public pages, then synthesising a sourced summary. Use for fact-finding and answering questions about the web.',
    body: '# Web Research\n## Steps\n1. Use web_search to discover relevant pages (ranked titles, URLs and snippets).\n2. Use fetch_url on the most authoritative, relevant sources.\n3. Cross-check claims across at least two sources when possible.\n4. Cite each source URL next to the claim it supports.\n5. Summarise findings with a short conclusion and list open questions.' },
  { name: 'plan-first', description: 'Produce a step-by-step implementation plan before making changes. Use for large or risky multi-step work.',
    body: '# Plan First\n## Steps\n1. Investigate the current state with fs_list/fs_read/fs_search.\n2. Write a numbered plan of small, verifiable steps.\n3. Record the plan with the tasks tool.\n4. Execute one step at a time, verifying after each.\n5. Update the report if the plan changes.' },
];
function parseSkillFrontmatter(body) {
  const m = /^---\n([\s\S]*?)\n---/.exec(String(body || ''));
  const out = {};
  if (m) for (const line of m[1].split('\n')) {
    const kv = /^([a-zA-Z_-]+)\s*:\s*(.*)$/.exec(line);
    if (kv) out[kv[1].trim()] = kv[2].trim();
  }
  return out;
}
async function listSkills() {
  const skills = BUILTIN_SKILLS.map(s => ({ name: s.name, description: s.description, source: 'builtin' }));
  try {
    let entries = [];
    try { entries = await agentListDir('/skills'); } catch { entries = []; }
    for (const e of entries) {
      if (e.kind !== 'directory') continue;
      const name = e.name;
      if (skills.some(s => s.name === name)) continue;
      try {
        const body = await agentReadFile(`/skills/${name}/SKILL.md`);
        const fm = parseSkillFrontmatter(body);
        skills.push({ name, description: fm.description || 'Custom workspace skill', source: 'workspace' });
      } catch {}
    }
  } catch {}
  return skills;
}





const SUBAGENT_DELEGATION_MAX_DEPTH = 4;

