  let result;
  if (!allowed.has(tname)) {
    const globalBlock = getSubagentToolGlobalBlockReason(tname);
    result = { ok: false, content: globalBlock
      ? `Tool "${tname || '?'}" is blocked by global settings: ${globalBlock}.`
      : `Tool "${tname || '?'}" is not allowed by this sub-agent profile.` };
  } else {
    if (setStatus) setStatus(`Sub-agent ${activity ? activity.name : ''}: using ${tname || 'tool'}`.trim());
    try {
      result = await executeAgentTool(tname, targs, allowed, { chain, parentActivity: activity });
    } catch (e) {
      result = { ok: false, content: `${tname || 'Tool'} failed: ${e.message}` };
    }
  }
  if (!result) result = { ok: false, content: `${tname || 'Tool'} returned no result.` };
