function buildBigChatApiMessages(threadId) {
  const bc = getBigChatData();
  const t = (threadId && bc.threads[threadId]) ? bc.threads[threadId] : getActiveBigChatThread();
  return t.messages.filter(m => !m.streaming && !m.error).map(m => {
    if (m.role === 'assistant' && m.toolCalls && m.toolCalls.length) {
      return { role: 'assistant', content: m.content || null, tool_calls: m.toolCalls.map(tc => ({ id: tc.id, type: 'function', function: { name: tc.name, arguments: JSON.stringify(tc.args || {}) } })) };
    }
    if (m.role === 'tool') {
      if (m.modelImage) {
        // Vision-capable models get the downscaled screenshot alongside the text.
        return { role: 'tool', tool_call_id: m.tool_call_id, content: [
          { type: 'text', text: String(m.content || '') },
          { type: 'image_url', image_url: { url: m.modelImage } },
        ] };
      }
      return { role: 'tool', tool_call_id: m.tool_call_id, content: m.content };
    }
    if (m.role === 'user' && Array.isArray(m.attachments) && m.attachments.some(a => a && a.id)) {
      
      const parts = buildBigChatUserContentParts(m);
      if (parts.length) return { role: m.role, content: parts };
    }
    return { role: m.role, content: m.content };
  });
}


let isFetchingModels = false;
