    ctx: Number(m.context_length || (m.top_provider && m.top_provider.context_length) || 0) || 0,
    maxOut: Number((m.top_provider && m.top_provider.max_completion_tokens) || 0) || 0,
    inMod: (m.architecture && m.architecture.input_modalities) || [],
    outMod: (m.architecture && m.architecture.output_modalities) || [],
