function populateBigPresetSelect() {
  const select = document.getElementById('bigPresetSelect'); if (!select) return;
  const t = getActiveBigChatThread();
  const requested = (t && t.preset) ? t.preset.trim() : '';
  const enabledPresets = getBigChatEnabledPresetIds(t);
  const current = enabledPresets.has(requested) ? requested : '';
  if (requested && !current) {
    t.preset = '';
    saveState();
  }
  let html = '<option value="">None (Default)</option>';
  if (state.presets && state.presets.length > 0) {
    const folders = {};
    for (const p of state.presets) {
      if (!enabledPresets.has(p.id)) continue;
      const f = p.folder || 'Among Us';
      if (!folders[f]) folders[f] = [];
      folders[f].push(p);
    }
    for (const f of Object.keys(folders)) {
      html += `<optgroup label="${escapeHtml(f)}">`;
      for (const p of folders[f]) {
        html += `<option value="${escapeHtml(p.id)}" ${p.id === current ? 'selected' : ''}>${escapeHtml(p.name)} (${escapeHtml(p.id)})</option>`;
      }
      html += `</optgroup>`;
    }
  }
  select.innerHTML = html;
  select.value = current || '';

  const hint = document.getElementById('bigChatPresetHint');
  if (hint) {
    if (current) {
      const pObj = state.presets.find(p => p.id === current);
      const name = pObj ? pObj.name : current;
      hint.textContent = `Using preset "${name}" (${current}) — fallback models enabled if configured in preset settings.`;
    } else {
      hint.textContent = `No preset chosen (default) — single model mode, will not automatically choose next model.`;
    }
  }
}



function estimateTokens(text) {
  if (!text) return 0;
  return Math.ceil(String(text).length / 4);
}
// Per-message memo. A message's cost only changes when its content, tool calls
// or attachments change, and the thread REPLACES those as a message evolves
// rather than mutating them in place, so comparing the three references says
// whether a cached cost is still valid. The one entry that legitimately misses
// is the streaming message, whose content string is rebuilt on every delta.
//
// This is what keeps the context meter cheap: it is recomputed on every
// streamed frame and on every keystroke in the composer, and a miss meant
// JSON.stringify-ing every tool call's arguments in the entire transcript each
// time — so typing and streaming got slower the longer the conversation ran.
function estimateMessagesTokens(messages) {
  const memo = estimateMessagesTokens._memo || (estimateMessagesTokens._memo = new WeakMap());
  let total = 0;
  for (const m of (messages || [])) {
    total += 4;
    const toolCalls = (m.toolCalls && m.toolCalls.length) ? m.toolCalls : null;
    const attachments = (m.attachments && m.attachments.length) ? m.attachments : null;
    const hit = memo.get(m);
    if (hit && hit.content === m.content && hit.toolCalls === toolCalls && hit.attachments === attachments
        && hit.toolCallCount === (toolCalls ? toolCalls.length : 0)
        && hit.attachmentCount === (attachments ? attachments.length : 0)) {
      total += hit.tokens;
      continue;
    }
    let tokens = estimateTokens(m.content);
    if (attachments) {
      for (const a of attachments) tokens += estimateAttachmentTokens(a) + 4;
    }
    if (toolCalls) {
      for (const tc of toolCalls) tokens += estimateTokens(tc.name) + estimateTokens(JSON.stringify(tc.args || {})) + 4;
    }
    memo.set(m, {
      content: m.content, toolCalls, attachments,
      toolCallCount: toolCalls ? toolCalls.length : 0,
      attachmentCount: attachments ? attachments.length : 0,
      tokens,
    });
    total += tokens;
  }
  return total;
}
function getModelContextLength(slug) {
  const id = (slug || '').trim();
  if (!id) return 0;
  const catalog = (state.modelCatalog && state.modelCatalog.models) || [];
  const hit = catalog.find(m => m.id === id);
  return hit && hit.ctx ? hit.ctx : 0;
}
function formatNum(n) { return Number(n || 0).toLocaleString('en-US'); }

function updateBigChatContextMeter() {
  const meter = document.getElementById('bigChatCtxMeter');
  const fill = document.getElementById('bigChatCtxFill');
  const textEl = document.getElementById('bigChatCtxText');
  if (!meter || !fill || !textEl) return;
  const t = getActiveBigChatThread();
  let used = estimateMessagesTokens(t.messages);
  if (t.systemPrompt && t.systemPrompt.trim()) used += estimateTokens(t.systemPrompt) + 4;
  const draft = document.getElementById('bigChatInput');
  if (draft && draft.value) used += estimateTokens(draft.value) + 4;
  for (const a of bigChatDraftsMap.get(t.id) || []) used += estimateAttachmentTokens(a) + 4;
  const known = getModelContextLength(t.model) || getBigChatAutoContextLimit();
  // Shown even when it is only an assumption, because this is also the number
  // auto-compact compacts against — a meter reading "unknown" while compaction
  // assumes a ceiling would be lying to the user.
  const max = known || AGENT_CONTEXT_UNKNOWN_FALLBACK;
  const pct = Math.min(100, (used / max) * 100);
  const cls = used > max ? 'over' : (pct >= 80 ? 'warn' : '');
  const width = pct + '%';
  const label = `${formatNum(used)} / ${formatNum(max)}`;
  const title = `~${formatNum(used)} of ${formatNum(max)} tokens used (${pct.toFixed(1)}%). Estimated at ~4 characters per token.`
    + (known ? '' : ` The context window for ${t.model || 'these models'} is unknown, so auto-compact assumes ${formatNum(AGENT_CONTEXT_UNKNOWN_FALLBACK)} — load the model list (⟳) to use the real one.`);
  // Written only when it actually changed. This runs per streamed frame and per
  // composer keystroke, and re-assigning an identical width/text/title still
  // cost a style recalculation — for a meter that mostly reads the same number
  // the user is not looking at.
  const last = updateBigChatContextMeter._shown || (updateBigChatContextMeter._shown = { cls: null, width: null, label: null, title: null });
  if (last.cls !== cls) {
    meter.classList.remove('warn', 'over');
    if (cls) meter.classList.add(cls);
    last.cls = cls;
  }
  if (last.width !== width) { fill.style.width = width; last.width = width; }
  if (last.label !== label) { textEl.textContent = label; last.label = label; }
  if (last.title !== title) { meter.title = title; last.title = title; }
}


function reasoningHtml(text, live) {
  if (!text || state.apiSettings.showReasoning === false) return '';
  const label = live ? 'Thinking…' : 'Thinking';
  return `<details class="think-details" ${live ? 'open' : ''}>
   <summary class="${live ? 'think-live' : ''}">🧠 ${label} <span style="opacity:.7;">(${formatNum(estimateTokens(text))} tok)</span></summary>
    <div class="think-body">${escapeHtml(text)}</div>
  </details>`;
}




function isNearChatBottom(container, threshold = 120) {
  if (!container) return true;
  return container.scrollHeight - container.scrollTop - container.clientHeight < threshold;
}


function updateStreamingMessage(live) {
  const container = document.getElementById('bigChatMessages'); if (!container) return;
  const el = container.querySelector('.message.streaming');
  if (!el) { renderBigChatMessages(); return; }
  const nearBottom = isNearChatBottom(container);
  const think = el.querySelector('.think-details');
  if (live.reasoning && state.apiSettings.showReasoning !== false) {
    if (think) {
      const body = think.querySelector('.think-body');
      if (body) { body.textContent = live.reasoning; body.scrollTop = body.scrollHeight; }
    } else {
      el.insertAdjacentHTML('afterbegin', reasoningHtml(live.reasoning, true));
    }
  }
  const textEl = el.querySelector('.stream-text');
  if (textEl) textEl.innerHTML = cachedMarkdownHtml(live, live.content);
  if (nearBottom) container.scrollTop = container.scrollHeight;
  updateBigChatContextMeter();
}


