function toolMeta(name) {
  return TOOL_META[name] || { icon: '🔧', color: '#58a6ff' };
}
function toolStatusBadge(kind, ok, retried) {
  if (kind === 'call') return '<span class="tool-status call">call</span>';
  if (!ok) return '<span class="tool-status error">✗ error</span>';
  if (retried) return '<span class="tool-status retried">↻ retried</span>';
  return '<span class="tool-status ok">✓ done</span>';
}
function prettyToolArgs(args) {
  if (!args || typeof args !== 'object' || !Object.keys(args).length) {
    return '<div style="color: var(--text-muted); font-size: 11px; font-style: italic;">(no arguments)</div>';
  }
  let str;
  try { str = JSON.stringify(args, null, 2); } catch { str = String(args); }
  if (str.length > 4000) str = str.slice(0, 4000) + '\n… (truncated)';
  return `<div class="tool-ars-label">Arguments</div><div class="tool-code">${escapeHtml(str)}</div>`;
}
function toolCodeBlock(content) {
  return `<div class="tool-code">${escapeHtml(content == null ? '' : content)}</div>`;
}

function formatBigChatSubagentElapsed(startedAt) {
  const seconds = Math.max(0, Math.floor((Date.now() - (startedAt || Date.now())) / 1000));
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ${String(seconds % 60).padStart(2, '0')}s`;
}
function refreshBigChatSubagentElapsed() {
  const detail = document.getElementById('bigChatSubagentDetail');
  if (!detail) return;
  const threadId = getBigChatData().activeThreadId;
  const activities = getBigChatSubagentActivities(threadId);
  const selectedId = bigChatSubagentSelection[threadId];
  const selected = activities.find(a => a.id === selectedId);
  const elapsed = detail.querySelector('[data-subagent-elapsed]');
  if (selected && elapsed) elapsed.textContent = formatBigChatSubagentElapsed(selected.startedAt);
}
function bigChatSubagentStatusText(activity) {
  const prefix = `Sub-agent ${activity.name}:`;
  const status = String(activity.status || 'Starting…');
  return status.indexOf(prefix) === 0 ? status.slice(prefix.length).trim() : status;
}
function renderBigChatSubagentToolEvents(activity) {
  const events = Array.isArray(activity && activity.toolEvents) ? activity.toolEvents : [];
  if (!events.length) return '';
  const rows = events.map((event, index) => {
    const state = event.status === 'running' ? 'running' : (event.ok === false ? 'error' : 'done');
    const stateLabel = state === 'running' ? 'running' : (state === 'error' ? 'error' : 'done');
    let args = '{}';
    try { args = JSON.stringify(event.args == null ? {} : event.args, null, 2); } catch { args = String(event.args || '{}'); }
    if (args.length > 3000) args = args.slice(0, 3000) + '\n… (truncated)';
    const output = event.status === 'running' ? 'Running…' : (event.output || '(no output)');
    const open = event.status === 'running' || index === events.length - 1 ? ' open' : '';
    return `<details class="bigchat-subagent-tool" data-subagent-tool="${escapeHtml(event.id)}"${open}>
      <summary><span class="bigchat-subagent-tool-name">${escapeHtml(event.name || 'unknown tool')}</span><span class="bigchat-subagent-tool-state ${state}">${stateLabel}</span></summary>
      <div class="bigchat-subagent-tool-body">
        <div class="bigchat-subagent-tool-label">Arguments</div>
        <div class="bigchat-subagent-tool-code" data-subagent-scroll="tool:${escapeHtml(event.id)}:args">${escapeHtml(args)}</div>
        <div class="bigchat-subagent-tool-label">Output / test result</div>
        <div class="bigchat-subagent-tool-code${state === 'error' ? ' error' : ''}" data-subagent-scroll="tool:${escapeHtml(event.id)}:output">${escapeHtml(output)}</div>
      </div>
    </details>`;
  }).join('');
  return `<div class="bigchat-subagent-chat-row tool"><details class="bigchat-subagent-chat-bubble tool" data-subagent-detail="tools" open>
    <summary>🧰 Tool use &amp; test output (${events.length})</summary>
    <div class="bigchat-subagent-tool-list">${rows}</div>
  </details></div>`;
}








function bigChatSubagentToolStatusLabel(status) {
  if (status === 'running') return 'running';
  return status === 'error' ? '✗ error' : '✓ done';
}
function bigChatSubagentToolIcon(name) {
  const meta = toolMeta(name);
  return `<span class="sa-tool-icon" style="--tool-color: ${meta.color}; --tool-tint: ${hexToRgba(meta.color, 0.12)};">${meta.icon}</span>`;
}
function bigChatSubagentToolHtml(event, index, eventsLength) {
  const state = event.status === 'running' ? 'running' : (event.ok === false ? 'error' : 'done');
  let args = '{}';
  try { args = JSON.stringify(event.args == null ? {} : event.args, null, 2); } catch { args = String(event.args || '{}'); }
  if (args.length > 3000) args = args.slice(0, 3000) + '\n… (truncated)';
  const output = event.status === 'running' ? 'Running…' : (event.output || '(no output)');
  const open = event.status === 'running' || index === eventsLength - 1 ? ' open' : '';
  return `<details class="sa-tool ${state}" data-subagent-tool="${escapeHtml(event.id)}"${open}>
    <summary>${bigChatSubagentToolIcon(event.name)}<span class="sa-tool-name">${escapeHtml(event.name || 'unknown tool')}</span><span class="sa-tool-status ${state}">${bigChatSubagentToolStatusLabel(event.status)}</span></summary>
    <div class="sa-tool-body">
      <div class="sa-tool-label">Arguments</div>
      <div class="sa-tool-code" data-subagent-scroll="tool:${escapeHtml(event.id)}:args">${escapeHtml(args)}</div>
      <div class="sa-tool-label">Output / test result</div>
      <div class="sa-tool-code${state === 'error' ? ' error' : ''}" data-subagent-scroll="tool:${escapeHtml(event.id)}:output">${escapeHtml(output)}</div>
    </div>
  </details>`;
}


function bigChatSubagentAssistantBubble(activity, turn) {
  const thinking = String(turn.thinking || '').trim();
  const output = String(turn.output || '').trim();
  const toolEvents = Array.isArray(turn.toolEvents) ? turn.toolEvents : [];
  const live = activity.live !== false && turn.live;
  const toolHtml = toolEvents.map((ev, i) => bigChatSubagentToolHtml(ev, i, toolEvents.length)).join('');
  const thinkHtml = thinking
    ? `<details class="sa-think" data-subagent-detail="think:${escapeHtml(turn.id)}"${live ? ' open' : ''}}><summary class="${live ? 'sa-think-live' : ''}">🧠 ${live ? 'Thinking…' : 'Thinking'} <span style="opacity:.7;">(${formatNum(estimateTokens(thinking))} tok)</span></summary><div class="sa-think-body" data-subagent-scroll="turn:${escapeHtml(turn.id)}:thinking">${escapeHtml(thinking)}</div></details>`
    : '';
  const contentHtml = output
    ? `<div class="sa-msg-content">${cachedMarkdownHtml(turn, output)}</div>`
    : '';
  const caretHtml = live ? '<span class="sa-stream-caret"></span>' : '';
  const metaBits = [];
  if (turn.model) metaBits.push(escapeHtml(turn.model) + (turn.provider && turn.provider !== 'Auto' ? ` (${escapeHtml(turn.provider)})` : ''));
  if (turn.elapsed != null) metaBits.push(`${Number(turn.elapsed).toFixed(1)}s`);
  const meta = metaBits.length
    ? `<div class="sa-msg-meta">${metaBits.join(' · ')}${toolEvents.length ? ` · ${toolEvents.length} tool call${toolEvents.length === 1 ? '' : 's'}` : ''}</div>`
    : '';
  const body = `${thinkHtml}${contentHtml}${caretHtml}${toolHtml}`;
  if (!body.trim() && !live) return '';
  return `<div class="bigchat-subagent-msg assistant" data-subagent-turn="${escapeHtml(turn.id)}"><div class="sa-msg-bubble">${body || '<span style="color:var(--text-muted);font-style:italic;">(no output)</span>'}</div>${meta}</div>`;
}
function bigChatSubagentUserBubble(label, text, metaExtra) {
  
  const body = text == null || String(text).trim() === '' ? '' : `<div class="sa-msg-bubble user">${escapeHtml(String(text))}</div>`;
  const meta = `<div class="sa-msg-meta">${escapeHtml(label)}${metaExtra ? ' · ' + metaExtra : ''}</div>`;
  return `<div class="bigchat-subagent-msg user">${body}${meta}</div>`;
}
function bigChatSubagentAutoContinueBubble(text) {
  const detail = text && String(text).trim()
    ? `<details class="sa-ac-detail"><summary>⚠️ Model stopped after thinking — auto-continued to get the actual response</summary><div class="sa-ac-body">${escapeHtml(String(text))}</div></details>`
    : `<div class="sa-auto-continue">⚠️ Model stopped after thinking — auto-continued to get the actual response</div>`;
  return `<div class="bigchat-subagent-msg user">${detail}</div>`;
}



function bigChatSubagentActivityLogHtml(activity) {
  const history = Array.isArray(activity && activity.statusHistory) ? activity.statusHistory : [];
  if (history.length < 2) return '';
  const lines = history.map(item => escapeHtml(item.text)).join('\n');
  return `<div class="bigchat-subagent-msg system"><details class="sa-system" data-subagent-detail="history" open>
    <summary>📋 Activity log (${history.length})</summary>
    <div class="sa-system-body" data-subagent-scroll="history">${lines}</div>
  </details></div>`;
}


function buildBigChatSubagentTranscript(activity) {
  const turns = Array.isArray(activity.transcript) ? activity.transcript : [];
  if (!turns.length) {
    const parts = [];
    if (String(activity.task || '').trim()) parts.push(bigChatSubagentUserBubble('Assigned task', activity.task));
    if (String(activity.context || '').trim()) parts.push(bigChatSubagentUserBubble('Additional context', activity.context));
    const events = Array.isArray(activity.toolEvents) ? activity.toolEvents : [];
    const think = String(activity.thinking || '').trim();
    const out = String(activity.output || '').trim();
    if (think || out || events.length) {
      const turn = { id: 'legacy', thinking: think, output: out, toolEvents: events, live: activity.live !== false };
      const html = bigChatSubagentAssistantBubble(activity, turn);
      if (html) parts.push(html);
    } else if (activity.live !== false) {
      parts.push(`<div class="bigchat-subagent-msg assistant"><div class="sa-msg-bubble"><span style="color:var(--text-muted);font-style:italic;">Waiting for model output, thinking, or tools…</span></div></div>`);
    }
    const logHtml = bigChatSubagentActivityLogHtml(activity);
    if (logHtml) parts.push(logHtml);
    return parts.join('');
  }
  const parts = [];
  for (let i = 0; i < turns.length; i++) {
    const turn = turns[i];
    if (turn.kind === 'user') {
      parts.push(bigChatSubagentUserBubble(turn.label || 'Message', turn.text));
    } else if (turn.kind === 'auto-continue') {
      parts.push(bigChatSubagentAutoContinueBubble(turn.text));
    } else {
      const html = bigChatSubagentAssistantBubble(activity, turn);
      if (html) parts.push(html);
    }
  }
  if (activity.live !== false && !parts.length) {
    parts.push(`<div class="bigchat-subagent-msg assistant"><div class="sa-msg-bubble"><span style="color:var(--text-muted);font-style:italic;">Waiting for model output, thinking, or tools…</span></div></div>`);
  }
  const logHtml = bigChatSubagentActivityLogHtml(activity);
  if (logHtml) parts.push(logHtml);
  return parts.join('');
}
function renderBigChatSubagentSidebar() {
  const panel = document.getElementById('bigChatSubagentsPanel');
  const tabs = document.getElementById('bigChatSubagentTabs');
  const detail = document.getElementById('bigChatSubagentDetail');
  const count = document.getElementById('bigChatSubagentCount');
  const summary = document.getElementById('bigChatSubagentSummary');
  if (!panel || !tabs || !detail) return;
  
  
  
  const modelSelectFocused = detail.contains(document.activeElement)
    && document.activeElement && document.activeElement.classList
    && document.activeElement.classList.contains('bigchat-subagent-model-select');
  if (modelSelectFocused) return;
  const detailScrollTop = detail.scrollTop;
  const detailOpenState = {};
  detail.querySelectorAll('details[data-subagent-detail], details[data-subagent-tool]').forEach(el => {
    const key = el.dataset.subagentDetail || `tool:${el.dataset.subagentTool}`;
    detailOpenState[key] = el.open;
  });
  const detailScrollState = {};
  detail.querySelectorAll('[data-subagent-scroll]').forEach(el => {
    detailScrollState[el.dataset.subagentScroll] = el.scrollTop;
  });
  const bc = getBigChatData();
  const threadId = bc.activeThreadId;
  const activities = getBigChatSubagentActivities(threadId);
  const activeCount = activities.filter(a => a.live !== false).length;
  const recentCount = activities.length - activeCount;
  if (count) {
    count.textContent = String(activities.length);
    count.classList.toggle('live', activeCount > 0);
  }
  if (summary) summary.textContent = activeCount
    ? `${activeCount} active sub-agent${activeCount === 1 ? '' : 's'}${recentCount ? ` · ${recentCount} recent` : ''}`
    : (recentCount ? `${recentCount} completed sub-agent${recentCount === 1 ? '' : 's'}` : 'Nothing running in this chat');
  if (!activities.length) {
    tabs.innerHTML = '<div class="bigchat-subagents-empty-tabs">No active sub-agents</div>';
    detail.innerHTML = `<div class="bigchat-subagents-empty"><div class="empty-icon">🧩</div><strong>Waiting for delegation</strong><p>When the Big Model calls <code>delegate</code>, each active sub-agent will appear here with its live task and current step.</p></div>`;
    return;
  }
  let selectedId = bigChatSubagentSelection[threadId];
  if (!activities.some(a => a.id === selectedId)) {
    selectedId = activities[0].id;
    bigChatSubagentSelection[threadId] = selectedId;
  }
  
  
  
  const knownIds = new Set(activities.map(a => a.id));
  const childrenByParent = {};
  for (const a of activities) {
    if (a.parentId && knownIds.has(a.parentId)) {
      (childrenByParent[a.parentId] = childrenByParent[a.parentId] || []).push(a);
    }
  }
  const tabRows = [];
  (function walk(list, depth) {
    for (const a of list) {
      tabRows.push({ activity: a, depth });
      const kids = childrenByParent[a.id];
      if (kids && kids.length) walk(kids, depth + 1);
    }
  })(activities.filter(a => !a.parentId || !knownIds.has(a.parentId)), 0);
  const occurrenceByAgent = {};
  tabs.innerHTML = tabRows.map(({ activity, depth }) => {
    occurrenceByAgent[activity.agentId] = (occurrenceByAgent[activity.agentId] || 0) + 1;
    const duplicateCount = activities.filter(a => a.agentId === activity.agentId).length;
    const tabName = duplicateCount > 1 ? `${activity.name} ${occurrenceByAgent[activity.agentId]}` : activity.name;
    const status = bigChatSubagentStatusText(activity);
    const active = activity.id === selectedId;
    const parentName = activity.parentId && knownIds.has(activity.parentId)
      ? (activities.find(a => a.id === activity.parentId) || {}).name : null;
    return `<button type="button" class="bigchat-subagent-tab${active ? ' active' : ''}${depth ? ' nested' : ''}" data-subagent-run="${escapeHtml(activity.id)}" role="tab" aria-selected="${active ? 'true' : 'false'}" title="${escapeHtml(parentName ? `Delegaed from ${parentName}: ` : '')}${escapeHtml(activity.task)}" style="${depth ? `margin-left:${depth * 12}px;` : ''}">
      ${depth ? '<span class="subagent-tab-branch">↳</span>' : ''}<span class="subagent-tab-dot${activity.live === false ? ' done' : (activity.paused ? ' paused' : '')}"></span><span class="subagent-tab-copy"><span class="subagent-tab-name">${escapeHtml(tabName)}</span><span class="subagent-tab-state">${escapeHtml((activity.live === false ? (activity.stopped ? 'Stopped' : (activity.paused ? 'Paused' : (activity.ok ? 'Completed' : 'Failed'))) : status).slice(0, 34))}</span></span>${activity.live !== false ? (activity.paused ? `<span class="subagent-tab-resume" role="button" tabindex="0" aria-label="Resume sub-agent" title="Resume this paused sub-agent — continues from its last step; Big Chat is not involved">▶</span>` : ((activity.pauseRequested || String(activity.status || '').includes('Stopping')) ? `<span class="subagent-tab-stop" role="button" tabindex="0" aria-label="Stop sub-agent" title="Stop this sub-agent">✋</span>` : `<span class="subagent-tab-pause" role="button" tabindex="0" aria-label="Pause sub-agent" title="Pause this sub-agent — finishes the current step, then parks the run; Big Chat is not told">⏸</span>`)) : ''}<span class="subagent-tab-x" role="button" tabindex="0" aria-label="Remove sub-agent tab" title="Remove this sub-agent from the sidebar">×</span>
    </button>`;
  }).join('');
  const selected = activities.find(a => a.id === selectedId) || activities[0];
  const selectedParent = selected && selected.parentId && knownIds.has(selected.parentId)
    ? activities.find(a => a.id === selected.parentId) : null;
  const selectedStatus = selected.live === false ? (selected.stopped ? 'Stopped by user' : (selected.paused ? 'Paused' : (selected.ok ? 'Completed' : 'Failed'))) : bigChatSubagentStatusText(selected);
  const stepText = selected.step ? `${selected.step}${selected.stepTotal ? ` / ${selected.stepTotal}` : ''}` : '—';
  const avatar = (selected.name || '?').trim().slice(0, 1).toUpperCase();
  const liveLabel = selected.live === false ? (selected.stopped ? 'Stopped' : (selected.paused ? 'Paused' : (selected.ok ? 'Done' : 'Failed'))) : (selected.paused ? 'Paused' : (selected.pauseRequested ? 'Pausing' : 'Live'));
  const stopBtnHtml = selected.live !== false
    ? (selected.paused
        ? `<button type="button" class="bigchat-subagent-resume" data-subagent-resume="${escapeHtml(selected.id)}" title="Resume this paused sub-agent from its last step — no work is lost, and Big Chat is not involved.">▶ Resume</button><button type="button" class="bigchat-subagent-stop" data-subagent-stop="${escapeHtml(selected.id)}" title="Stop this sub-agent (ends the parked run and reports it stopped to Big Chat)">✋ Stop</button>`
        : ((selected.pauseRequested || String(selected.status || '').includes('Stopping'))
            ? `<button type="button" class="bigchat-subagent-stop" data-subagent-stop="${escapeHtml(selected.id)}" title="Stop this sub-agent (aborts the in-flight request and ends the run)">✋ Stop</button>`
            : `<button type="button" class="bigchat-subagent-pause" data-subagent-pause="${escapeHtml(selected.id)}" title="Pause this sub-agent — finishes the current step, then parks the run. Big Chat is not told.">⏸ Pause</button><button type="button" class="bigchat-subagent-stop" data-subagent-stop="${escapeHtml(selected.id)}" title="Stop this sub-agent (aborts the in-flight request and ends the run)">✋ Stop</button>`))
    : (selected.stopped || selected.paused || selected.ok === false)
      ? `<button type="button" class="bigchat-subagent-resume" data-subagent-resume="${escapeHtml(selected.id)}" title="Continue this sub-agent from where it stopped (re-runs the same profile with its conversation history)">▶ Continue</button>`
      : '';
  const providerText = selected.provider || 'Auto';
  
  
  
  
  const modelOptions = [];
  const seenModelOpts = new Set();
  const addModelOpt = (slug) => {
    const s = String(slug || '').trim();
    if (!s || seenModelOpts.has(s.toLowerCase())) return;
    seenModelOpts.add(s.toLowerCase());
    modelOptions.push(s);
  };
  (getFallbackModelSlugs() || []).forEach(addModelOpt);
  addModelOpt(selected.model);
  addModelOpt(selected.modelOverride);
  addModelOpt(getDefaultBigChatModel());
  
  
  const currentModelNote = selected.model
    ? 'Model used for the steps completed so far. Pick a model above to switch from the next step.'
    : 'No model has run yet for this sub-agent — it will resolve through the auto chain (profile defaults → global sub-agent model → thread model).'
  const modelSelectHtml = `<div class="bigchat-subagent-meta-item full"><span title="Model used for this sub-agent. Pick one to override the automatic chain (profile defaults → global sub-agent model → thread model); blank = automatic. Applies from the next step/request.">Model</span>
      <select class="bigchat-subagent-model-select" data-subagent-model-select="${escapeHtml(selected.id)}" title="Override the model for this sub-agent. Blank = automatic (profile defaults → global sub-agent model → thread model). Applies from the next step/request.">
        <option value="">Auto (defaults → global → thread)</option>
        ${modelOptions.map(slug => `<option value="${escapeHtml(slug)}" ${String(slug).toLowerCase() === String(selected.modelOverride || '').toLowerCase() ? 'selected' : ''}>${escapeHtml(slug)}</option>`).join('')}
      </select></div>`;
  const thinkingHtml = selected.thinking
    ? `<div class="bigchat-subagent-chat-row assistant"><details class="bigchat-subagent-chat-bubble thinking" data-subagent-detail="thinking" open><summary>🧠 Thinking (${formatNum(estimateTokens(selected.thinking))} tok)</summary><div class="bigchat-subagent-chat-body" data-subagent-scroll="thinking">${escapeHtml(selected.thinking)}</div></details></div>`
    : '';
  const outputHtml = selected.output
    ? `<div class="bigchat-subagent-chat-row assistant"><details class="bigchat-subagent-chat-bubble output" data-subagent-detail="output" open><summary>💬 Model output (all steps)</summary><div class="bigchat-subagent-chat-body" data-subagent-scroll="output">${escapeHtml(selected.output)}</div></details></div>`
    : '';
  const toolEventsHtml = renderBigChatSubagentToolEvents(selected);
  const historyHtml = selected.statusHistory && selected.statusHistory.length > 1
    ? `<div class="bigchat-subagent-chat-row system"><details class="bigchat-subagent-chat-bubble system" data-subagent-detail="history"><summary>Activity log (${selected.statusHistory.length})</summary><div class="bigchat-subagent-chat-body" data-subagent-scroll="history">${selected.statusHistory.map(item => escapeHtml(item.text)).join('\n')}</div></details></div>`
    : '';
  
  
  
  
  
  const transcriptHtml = buildBigChatSubagentTranscript(selected);
  const legacyChatHtml = `<div class="bigchat-subagent-chat">
      <div class="bigchat-subagent-chat-row user"><div class="bigchat-subagent-chat-bubble user"><div class="bigchat-subagent-chat-role">Assigned task</div><div class="bigchat-subagent-chat-body">${escapeHtml(selected.task)}</div></div></div>
      ${selected.context ? `<div class="bigchat-subagent-chat-row user"><div class="bigchat-subagent-chat-bubble user context"><div class="bigchat-subagent-chat-role">Additional context</div><div class="bigchat-subagent-chat-body">${escapeHtml(selected.context)}</div></div></div>` : ''}
      ${thinkingHtml || (!selected.output && !toolEventsHtml ? '<div class="bigchat-subagent-chat-row assistant"><div class="bigchat-subagent-chat-bubble assistant">Waiting for model output, thinking, or tools…</div></div>' : '')}
      ${toolEventsHtml}
      ${outputHtml}
      ${historyHtml}
    </div>`;
  const chatSectionHtml = transcriptHtml
    ? `<div class="bigchat-subagent-transcript">${transcriptHtml}</div>`
    : legacyChatHtml;
  detail.innerHTML = `<div class="bigchat-subagent-card">
    <div class="bigchat-subagent-card-head">
      <div class="bigchat-subagent-avatar">${escapeHtml(avatar)}</div>
      <div class="bigchat-subagent-card-name"><strong>${escapeHtml(selected.name)}</strong><code>${escapeHtml(selected.agentId)}</code></div>
      <span class="bigchat-subagent-live${selected.live === false ? ' done' : ''}"><span class="bigchat-subagent-live-dot"></span>${liveLabel}</span>
    </div>
    ${selectedParent ? `<div class="bigchat-subagent-parent">↳ delegated from <strong>${escapeHtml(selectedParent.name || selectedParent.agentId)}</strong></div>` : ''}
    ${selected.description ? `<div class="bigchat-subagent-description">${escapeHtml(selected.description)}</div>` : ''}
    <div class="bigchat-subagent-status-row"><span>${selected.live === false ? (selected.stopped ? '⏹' : (selected.paused ? '⏸' : (selected.ok ? '✓' : '✗'))) : (selected.paused ? '⏸' : '◐')}</span><strong>${escapeHtml(selectedStatus)}</strong>${stopBtnHtml ? `<span class="subagent-actions">${stopBtnHtml}</span>` : ''}</div>
    <div class="bigchat-subagent-meta">${modelSelectHtml}<div class="bigchat-subagent-meta-item"><span>Current model</span><strong title="${escapeHtml(currentModelNote)}">${escapeHtml(selected.model || '(auto chain)')}</strong></div><div class="bigchat-subagent-meta-item"><span>Provider</span><strong title="${escapeHtml(providerText)}">${escapeHtml(providerText)}</strong></div><div class="bigchat-subagent-meta-item"><span>Elapsed</span><strong data-subagent-elapsed>${formatBigChatSubagentElapsed(selected.startedAt)}</strong></div><div class="bigchat-subagent-meta-item"><span>Step</span><strong>${escapeHtml(stepText)}</strong></div></div>
    ${chatSectionHtml}
  </div>`;
  
  
  
  detail.querySelectorAll('details[data-subagent-detail], details[data-subagent-tool]').forEach(el => {
    const key = el.dataset.subagentDetail || `tool:${el.dataset.subagentTool}`;
    if (Object.prototype.hasOwnProperty.call(detailOpenState, key)) el.open = detailOpenState[key];
  });
  detail.querySelectorAll('[data-subagent-scroll]').forEach(el => {
    const key = el.dataset.subagentScroll;
    if (Object.prototype.hasOwnProperty.call(detailScrollState, key)) el.scrollTop = detailScrollState[key];
  });
  detail.scrollTop = detailScrollTop;
  tabs.querySelectorAll('[data-subagent-run]').forEach(tab => {
    tab.onclick = (e) => {
      if (e.target.closest('.subagent-tab-x') || e.target.closest('.subagent-tab-stop') || e.target.closest('.subagent-tab-pause') || e.target.closest('.subagent-tab-resume')) return; 
      bigChatSubagentSelection[threadId] = tab.dataset.subagentRun;
      renderBigChatSubagentSidebar();
    };
  });
  tabs.querySelectorAll('.subagent-tab-stop').forEach(stop => {
    const doStop = (e) => {
      e.stopPropagation();
      const tab = stop.closest('[data-subagent-run]');
      if (!tab) return;
      const activity = activities.find(a => a.id === tab.dataset.subagentRun);
      if (activity) requestStopBigChatSubagent(activity);
    };
    stop.onclick = doStop;
    stop.onkeydown = (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); doStop(e); }
    };
  });
  tabs.querySelectorAll('.subagent-tab-pause').forEach(pauseBtn => {
    const doPause = (e) => {
      e.stopPropagation();
      const tab = pauseBtn.closest('[data-subagent-run]');
      if (!tab) return;
      const activity = activities.find(a => a.id === tab.dataset.subagentRun);
      if (activity) requestPauseBigChatSubagent(activity);
    };
    pauseBtn.onclick = doPause;
    pauseBtn.onkeydown = (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); doPause(e); }
    };
  });
  tabs.querySelectorAll('.subagent-tab-resume').forEach(resumeBtn => {
    const doResume = (e) => {
      e.stopPropagation();
      const tab = resumeBtn.closest('[data-subagent-run]');
      if (!tab) return;
      const activity = activities.find(a => a.id === tab.dataset.subagentRun);
      if (activity) requestResumePausedBigChatSubagent(activity);
    };
    resumeBtn.onclick = doResume;
    resumeBtn.onkeydown = (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); doResume(e); }
    };
  });
  tabs.querySelectorAll('.subagent-tab-x').forEach(x => {
    const removeTab = (e) => {
      e.stopPropagation();
      const tab = x.closest('[data-subagent-run]');
      if (!tab) return;
      deleteBigChatSubagentActivity(threadId, tab.dataset.subagentRun);
    };
    x.onclick = removeTab;
    x.onkeydown = (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); removeTab(e); }
    };
  });
  
  
  
  detail.querySelectorAll('[data-subagent-model-select]').forEach(sel => {
    sel.onchange = () => {
      const id = sel.dataset.subagentModelSelect;
      const activity = activities.find(a => a.id === id);
      if (!activity) return;
      activity.modelOverride = String(sel.value || '').trim();
      if (activity.modelOverride) activity.model = activity.modelOverride;
      renderBigChatSubagentSidebar();
    };
  });
  detail.querySelectorAll('[data-subagent-stop]').forEach(btn => {
    btn.onclick = () => {
      const id = btn.dataset.subagentStop;
      const activity = activities.find(a => a.id === id);
      if (activity) requestStopBigChatSubagent(activity);
    };
  });
  detail.querySelectorAll('[data-subagent-pause]').forEach(btn => {
    btn.onclick = () => {
      const id = btn.dataset.subagentPause;
      const activity = activities.find(a => a.id === id);
      if (activity) requestPauseBigChatSubagent(activity);
    };
  });
  detail.querySelectorAll('[data-subagent-resume]').forEach(btn => {
    btn.onclick = () => {
      const id = btn.dataset.subagentResume;
      const activity = activities.find(a => a.id === id);
      if (!activity) return;
      if (activity.live !== false) requestResumePausedBigChatSubagent(activity);
      else resumeBigChatSubagent(activity);
    };
  });
}

function renderBigChatMessages() {
  const container = document.getElementById('bigChatMessages'); if (!container) return;
  const t = getActiveBigChatThread();
  const msgs = t.messages;
  if (!msgs || msgs.length === 0) {
    const autoEmpty = isBigChatAutoModel(t.model) && bigChatAutoModelChain().length > 0;
    const emptyIntro = autoEmpty
      ? `Model is <b>⚡ Auto</b> — requests walk the fallback list from ⚙ Settings → 🧩 Models &amp; Routing until one answers. Pick a specific model above to pin the thread, or type <em>any</em> OpenRouter model slug.`
      : `Pick a model above — or type <em>any</em> OpenRouter model slug — and start chatting.`;
    container.innerHTML = `<div class="chat-empty"><h3>🧠 Big Chat</h3><p>${emptyIntro} The Big Model can call the 14 character presets directly through the <code>call_preset</code> tool so they can collaborate.</p><p style="margin-top:12px;font-size:11px;">Optionally add a System Prompt to give the Big Model its role or instructions. Use the thread selector to manage multiple conversations.</p></div>`;
    
    
    
    renderBigChatTasksPopup();
    return;
  }
  
  const nearBottomBefore = isNearChatBottom(container);
  container.innerHTML = msgs.map((m, _bcIdx) => {
    if (m.role === 'user' && m.regenerated) {
      return `<div class="message auto-continue" data-bcidx="${_bcIdx}">🔄 Regenerated from here — the previous reply and the ${formatNum(Math.max(0, (m.replaced || 1) - 1))} message(s) after it were discarded, and the goal was restated for the model<div class="meta">regenerate</div></div>`;
    }
    if (m.role === 'user' && m.autoContinue) {
      return `<div class="message auto-continue" data-bcidx="${_bcIdx}">⚠️ Model stopped after thinking — auto-continued to get the actual response<div class="meta">auto-continue</div></div>`;
    }
    if (m.role === 'user') return `<div class="message user" data-bcidx="${_bcIdx}">${msgToolsHtml(!isBigChatSending, false, !isBigChatSending)}${bigChatMessageAttachmentsHtml(m)}${escapeHtml(m.content)}<div class="meta">${versionNavHtml(m)}You</div></div>`;
    if (m.role === 'tool' && m.toolName === 'tasks') {
      
      
      const list = threadTasks(getActiveBigChatThread());
      const openN = list.filter(x => !x.done).length;
      const doneN = list.length - openN;
      return `<div class="task-result-chip" data-bcidx="${_bcIdx}">☑️ Task list updated — <b>${openN} open</b> · <b>${doneN} done</b></div>`;
    }
    if (m.role === 'tool' && m.toolName) {        const meta = toolMeta(m.toolName);
      const errCls = m.ok ? '' : ' error';
      const colorStyle = `--tool-color: ${meta.color}; --tool-tint: ${hexToRgba(meta.color, 0.08)};`;
      const img = m.image ? `<img src="${m.image}" alt="screenshot" style="max-width:100%;border:1px solid var(--border);border-radius:4px;margin-top:8px;">` : '';
      return `<div class="tool-result-wrapper">
         <details class="tool-details standalone tool-event${errCls}" style="${colorStyle}margin-top:0;width:100%;display:block;box-sizing:border-box;" ${m.image || m.diff ? 'open' : ''}>
          <summary><span class="tool-icon">${meta.icon}</span><span class="tool-name">${escapeHtml(m.toolName)}</span><span class="tool-kind">result</span>${m.diff ? '<span class="tool-status call" style="font-size:10px;">diff</span>' : ''}${toolStatusBadge('result', m.ok)}</summary>
          <div class="tool-body">${toolCodeBlock(m.content)}${m.diff ? renderDiffHtml(m.diff) : ''}${img}</div>
        </details></div>`;
    }
    if (m.role === 'tool') {
      const charInfo = CHARACTERS.find(c => c[0] === m.preset);
      const name = charInfo ? charInfo[1] : (m.preset || 'preset');
      const toolName = m.retried ? 'retry_preset' : 'call_preset';      const meta = toolMeta(toolName);
      const errCls = m.ok ? '' : ' error';
      const modelStr = m.model ? `<span class="tool-model">${escapeHtml(m.model)}</span>` : '';
      const colorStyle = `${presetColorStyle(m.preset, 0.10)} --tool-color: ${meta.color}; --tool-tint: ${hexToRgba(meta.color, 0.08)};`;
      const presetChip = m.preset ? `<span class="tool-preset-chip">${escapeHtml(name)}</span>` : '';
      return `<div class="tool-result-wrapper">
        <details class="tool-details standalone tool-event preset-colored${errCls}" style="${colorStyle}margin-top:0;width:100%;display:block;box-sizing:border-box;">
          <summary><span class="tool-icon">${meta.icon}</span><span class="tool-name">${escapeHtml(toolName)}</span>${presetChip}${toolStatusBadge('result', m.ok, m.retried)}</summary>
          <div class="tool-body">${toolCodeBlock(m.content)}${modelStr ? `<div class="tool-result-meta">${modelStr}</div>` : ''}</div>
        </details>
      </div>`;
    }
    if (m.role === 'assistant') {
      if (m.error) return `<div class="message assistant error" data-bcidx="${_bcIdx}">ERROR: ${escapeHtml(m.error)}<div class="meta">Big Model · error<span class="retry-wrap"><button class="retry-big-chat-btn" data-bcidx="${_bcIdx}" style="background: var(--bg-elev); border: 1px solid var(--border); color: var(--text); padding: 0 5px; border-radius: 4px; font-size: 11px; line-height: 1.4; cursor: pointer;" title="Regenerate this response — removes this message and everything after it, then re-runs from here">🔄</button></span></div></div>`;
      if (m.streaming) {
        const waiting = !m.content && !m.reasoning;
        return `<div class="message assistant streaming" data-bcidx="${_bcIdx}">${msgToolsHtml(false, false, false)}${reasoningHtml(m.reasoning, true)}<span class="stream-text markdown-content">${cachedMarkdownHtml(m, m.content || '')}</span><span class="stream-caret"></span><div class="meta">${waiting ? 'Waiting for first token…' : 'Generating…'}</div></div>`;
      }
      let toolCallHtml = '';
      if (m.toolCalls && m.toolCalls.length) {
        toolCallHtml = m.toolCalls.map(tc => {
          if ((tc.name || '').trim().toLowerCase() === 'tasks') {
            const args = tc.args || {};
            const verbMap = { set: 'set', add: 'updated', done: 'updated', undone: 'updated', clear: 'cleared', list: 'viewed' };
            const verb = verbMap[String(args.op || 'list').toLowerCase()] || 'updated';
            return `<span class="task-result-chip" style="margin-top:6px;" data-bcidx="${_bcIdx}">☑️ Plan ${verb} — see the top-right popup for the live list</span>`;
          }
          const meta = toolMeta(tc.name);
          const preset = tc.args && tc.args.preset;
          const charInfo = preset ? CHARACTERS.find(c => c[0] === preset) : null;
          const name = charInfo ? charInfo[1] : (preset || '');
          const isPreset = !!preset;
          const colorStyle = isPreset
            ? `${presetColorStyle(preset, 0.08)} --tool-color: ${meta.color}; --tool-tint: ${hexToRgba(meta.color, 0.08)};`
            : `--tool-color: ${meta.color}; --tool-tint: ${hexToRgba(meta.color, 0.06)};`;
          const presetChip = isPreset ? `<span class="tool-preset-chip">${escapeHtml(name)}</span>` : '';
          return `<details class="tool-details tool-event${isPreset ? ' preset-colored' : ''}" style="${colorStyle} width: 100%; display: block; box-sizing: border-box; margin-top: 6px;">
            <summary><span class="tool-icon">${meta.icon}</span><span class="tool-name">${escapeHtml(tc.name || '')}</span>${presetChip}${toolStatusBadge('call')}</summary>
            <div class="tool-body">${prettyToolArgs(tc.args)}</div>
          </details>`;
        }).join('');
      }
      const metaBits = ['Big Model'];
      if (m.model) metaBits.push(escapeHtml(m.model) + (m.provider ? ` (${escapeHtml(providerExportLabel(m.provider))})` : ''));
      if (m.elapsed != null) metaBits.push(`${m.elapsed.toFixed(1)}s`);
      if (m.recovered) metaBits.push('⚡ recovered after shutdown');
      const fbBadge = fallbackBadgeHtml(m);
      if (fbBadge) metaBits.push(fbBadge);
      const bcEditable = !isBigChatSending && !(m.toolCalls && m.toolCalls.length);
      const bcSpeak = !!(m.content && String(m.content).trim()) && !(m.toolCalls && m.toolCalls.length && !m.content);
      const bcRetry = !isBigChatSending ? `<button class="retry-big-chat-btn" data-bcidx="${_bcIdx}" style="margin-left: 6px; background: var(--bg-elev); border: 1px solid var(--border); color: var(--text); padding: 0 5px; border-radius: 4px; font-size: 11px; line-height: 1.4; cursor: pointer;" title="Regenerate this response — removes this message and everything after it, then re-runs from here">🔄</button>` : '';
      return `<div class="message assistant" data-bcidx="${_bcIdx}">${msgToolsHtml(bcEditable, bcSpeak)}${reasoningHtml(m.reasoning, false)}${m.content ? '<div class="markdown-content">' + cachedMarkdownHtml(m, m.content) + '</div>' : ''}${toolCallHtml}<div class="meta">${versionNavHtml(m)}${metaBits.join(' · ')}${bcRetry}</div></div>`;
    }
    return '';
  }).join('');
  if (nearBottomBefore) container.scrollTop = container.scrollHeight;

  renderBigChatTasksPopup();

  
  if (t && !t._attHydrating) {
    t._attHydrating = true;
    hydrateBigChatThreadAttachments(t).then(changed => {
      t._attHydrating = false;
      if (changed && getBigChatData().activeThreadId === t.id) renderBigChatMessages();
    }).catch(() => { t._attHydrating = false; });
  }

  renderBigChatSubagentSidebar();
  container.querySelectorAll('.message[data-bcidx]').forEach(bubble => {
    const idx = parseInt(bubble.dataset.bcidx);
    const msg = msgs[idx];
    if (!msg) return;
    const editBtn = bubble.querySelector('.msg-edit-btn');
    if (editBtn) editBtn.onclick = (e) => {
      e.stopPropagation();
      const scrollPos = container.scrollTop;
      openMsgEditor(bubble, msg, (changed, newText) => {
        if (changed && msg.role === 'user' && newText !== undefined) {
          branchUserMessageInPlace(msgs, idx, newText, () => { renderBigChatMessages(); sendBigChatMessage(true); });
        } else if (changed) {
          ensureMsgVersions(msg);
          const prevVer = typeof msg._prevActiveVersion === 'number' ? msg._prevActiveVersion : (msg.activeVersion > 0 ? msg.activeVersion - 1 : 0);
          msg.versions[prevVer].children = msgs.slice(idx + 1);
          msg.versions[msg.activeVersion].children = [];
          msgs.splice(idx + 1, msgs.length - (idx + 1));
          delete msg._prevActiveVersion;
          saveState();
          renderBigChatMessages();
          container.scrollTop = scrollPos;
        }
      }, msg.role === 'user');
    };
    const resendBtn = bubble.querySelector('.msg-resend-btn');
    if (resendBtn) resendBtn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      branchUserMessageInPlace(msgs, idx, msg.content || '', () => {
        renderBigChatMessages();
        sendBigChatMessage(true);
      });
    };
    const retryErrBtn = bubble.querySelector('.retry-big-chat-btn');
    if (retryErrBtn) retryErrBtn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      retryBigChatMessage(idx);
    };
    const speakBtn = bubble.querySelector('.msg-speak-btn');
    if (speakBtn) speakBtn.onclick = (e) => { e.preventDefault(); e.stopPropagation(); speakMessageText(msg.content, speakBtn); };
    const prev = bubble.querySelector('.ver-prev');
    const next = bubble.querySelector('.ver-next');
    if (prev) prev.onclick = (e) => { e.stopPropagation(); if (switchMsgVersion(msg, -1, msgs, idx)) { saveState(); renderBigChatMessages(); } };
    if (next) next.onclick = (e) => { e.stopPropagation(); if (switchMsgVersion(msg, 1, msgs, idx)) { saveState(); renderBigChatMessages(); } };
  });

  updateBigChatContextMeter();
}

function updateBigSystemPromptStatus() {
  const el = document.getElementById('bigSystemPromptStatus');
  const ta = document.getElementById('bigSystemPrompt');
  if (!el || !ta) return;
  const len = (ta.value || '').trim().length;
  el.textContent = len ? `(${len} chars)` : '(none)';
  el.classList.toggle('set', len > 0);
}

function updateBigChatInputState() {
  const input = document.getElementById('bigChatInput'), sendBtn = document.getElementById('bigChatSendBtn');
  if (!input || !sendBtn) return;
  const t = getActiveBigChatThread();
  const hasModel = !!t.model || bigChatAutoModelChain().length > 0;
  const bc = getBigChatData();
  const busy = isThreadSending(bc.activeThreadId);
  const canSend = hasModel && !!state.apiSettings.apiKey && !busy;
  input.disabled = !canSend; sendBtn.disabled = !canSend;
  renderBigChatDraftBar();
  
  const stopBtn = document.getElementById('bigChatStopBtn');
  if (stopBtn) stopBtn.style.display = busy ? '' : 'none';
  const statusEl = document.getElementById('bigChatStatus');
  if (statusEl) {
    const modalInfo = t.model ? getApiEndpointAndHeaders(t.model, state.apiSettings, (t.provider || '').trim() || null) : null;
    if (isBigChatAutoModel(t.model)) {
      statusEl.textContent = busy ? (bigChatRuns[bc.activeThreadId].status || 'Thinking...') : '⚡ Auto (fallback list)';
    } else if (modalInfo && modalInfo.isModal) {
      statusEl.textContent = busy ? (bigChatRuns[bc.activeThreadId].status || 'Thinking...') : `${t.model} → Modal.com`;
    } else if (modalInfo && modalInfo.isNvidia) {
      statusEl.textContent = busy ? (bigChatRuns[bc.activeThreadId].status || 'Thinking...') : `${t.model} → NVIDIA`;
    } else if (modalInfo && modalInfo.isVercel) {
      statusEl.textContent = busy ? (bigChatRuns[bc.activeThreadId].status || 'Thinking...') : `${t.model} → Vercel`;
    } else if (modalInfo && modalInfo.isInferx) {
      statusEl.textContent = busy ? (bigChatRuns[bc.activeThreadId].status || 'Thinking...') : `${t.model} → Inferx`;
    } else {
      statusEl.textContent = busy ? (bigChatRuns[bc.activeThreadId].status || 'Thinking...') : '';
    }
  }
  const statsEl = document.getElementById('bigChatRunStats');
  if (statsEl) {
    const r = busy ? bigChatRuns[bc.activeThreadId] : null;
    if (r && r.step) {
      const mins = ((Date.now() - (r.startedAt || Date.now())) / 60000).toFixed(1);
      statsEl.style.display = '';
      statsEl.textContent = `⚙ ${r.step} steps · ${mins}m${r.cost ? ` · $${r.cost.toFixed(3)}` : ''}`;
    } else statsEl.style.display = 'none';
  }
  updateBigChatContextMeter();
}









function bigChatEffectiveSettings(thread, model) {
  const base = state.apiSettings;
  const forced = ((thread && thread.provider) || '').trim();
  const tl = (thread && thread.thinkingLevel && thread.thinkingLevel !== 'auto') ? thread.thinkingLevel : null;
  if (!forced && !tl) return base;
  const out = Object.assign({}, base);
  if (forced) {
    const rule = { model: bareModelSlug(model), providers: [forced], allowFallbacks: false, enabled: true };
    out.enableModelProviders = true;
    out.modelProviders = [rule, ...(base.modelProviders || [])];
  }
  
  
  if (tl) out.thinkingLevel = tl;
  return out;
}

function buildBigChatToolSchemas(thread) {
  const t = normalizeBigChatCapabilities(thread);
  const tools = [];
  const enabledTools = getBigChatEnabledToolNames(t);
  const enabledSubagents = getBigChatEnabledSubagentIds(t);
  const enabledPresets = getBigChatEnabledPresetIds(t);
  if (t.bigChatToolsEnabled !== false) {
    tools.push(...buildAgentToolSchemas(enabledTools, enabledSubagents));
    tools.push({ type: 'function', function: {
      name: 'tasks',
      description: "Your persistent checklist for this run. ALWAYS call op='set' with the full plan before starting multi-step work, then op='done' as you finish each item. Re-read it with op='list' if you lose track. This survives context compaction, so it is how you remember the goal across a long run.",
      parameters: { type: 'object', properties: {
        op: { type: 'string', enum: ['set', 'add', 'done', 'undone', 'list', 'clear'] },
        items: { type: 'array', items: { type: 'string' }, description: 'Task texts for set/add.' },
        index: { type: 'number', description: '1-based task number for done/undone.' },
      }, required: ['op'] }
    }});
  }
  if (t.bigChatPresetsEnabled !== false && enabledPresets.size) {
    const presetIds = Array.from(enabledPresets);
    tools.push({ type: 'function', function: {
      name: 'call_preset',
      description: "Call one of the enabled character presets to get that character's response. Each call continues that character's conversation, so they remember what theyalready said. Use this to delegate work or collaborate with the characters.",
      parameters: { type: 'object', properties: {
        preset: { type: 'string', enum: presetIds, description: 'The preset/character to call.' },
        message: { type: 'string', description: 'The message/instruction to send to that character.' },
      }, required: ['preset', 'message'] }
    }});
    tools.push({ type: 'function', function: {
      name: 'retry_preset',
      description: "Ask an enabled preset to redo its most recent reply because it was unsatisfactory. This discards that reply and regenerates it instead of stacking another turn.",
      parameters: { type: 'object', properties: {
        preset: { type: 'string', enum: presetIds, description: 'The preset/character whose last reply should be redone.' },
        feedback: { type: 'string', description: 'What was wrong and what to do differently.' },
        temperature: { type: 'number', description: 'Optional 0-2 sampling temperature for more variety.' },
      }, required: ['preset'] }
    }});
  }
  return tools;
}

// Hard ceiling on any single tool result stored in a Big Chat thread. The whole
// transcript is re-sent on every step, so one 56 KB read is paid for on every
// later request: in the review run that motivated this, 20 reads added up to
// ~310 KB (≈78k tokens) and pushed the prompt past what the serving gateway
// would accept. Truncation is always announced, because a silently clipped
// result reads as the whole truth.
const BIGCHAT_TOOL_RESULT_MAX_CHARS = 24000;
function capBigChatToolResult(message) {
  if (!message || typeof message.content !== 'string') return message;
  if (message.content.length <= BIGCHAT_TOOL_RESULT_MAX_CHARS) return message;
  return {
    ...message,
    content: message.content.slice(0, BIGCHAT_TOOL_RESULT_MAX_CHARS) +
      `\n… (result cut at ${BIGCHAT_TOOL_RESULT_MAX_CHARS} of ${message.content.length} characters — re-run the tool with narrower arguments, or fs_read an offset window to see the rest)`,
  };
}

async function sendBigChatMessage(isRetryOrBranch = false) {
  const isRetry = isRetryOrBranch === true;
  const bc0 = getBigChatData();
  const runId = bc0.activeThreadId;                 
  if (isThreadSending(runId)) return;
  const input = document.getElementById('bigChatInput');
  if (!input) return;
  let text = '';
  let drafts = [];
  if (!isRetry) {
    text = input.value.trim();
    drafts = bigChatDraftsMap.get(runId) || [];
    if (!text && !drafts.length) return;
  }
  if (!state.apiSettings.apiKey) { openSettings('api'); alert('Please enter your OpenRouter API key in Settings first.'); return; }
  const t = getActiveBigChatThread();
  const model = t.model;
  if (!model && !bigChatAutoModelChain().length) { alert('Enter or pick a model first (any OpenRouter model slug works), or add models to the fallback list in Settings → 🧩 Models & Routing.'); return; }
  const runController = new AbortController();
  bigChatRuns[runId] = { controller: runController, status: 'Thinking...' };
  // Pin the workspace to this run's thread so mid-run thread switches cannot
  // re-attribute this run's file edits to another thread's workspace snapshot.
  const prevWorkspaceOwnerThreadId = workspaceOwnerThreadId;
  workspaceOwnerThreadId = runId;
  
  const onThisThread = () => getBigChatData().activeThreadId === runId;
  const setStatus = (txt) => { bigChatRuns[runId] && (bigChatRuns[runId].status = txt); if (onThisThread()) document.getElementById('bigChatStatus').textContent = txt; };
  updateBigChatInputState();
  setStatus('Thinking...');
  if (!isRetry) {
    const userMsg = { role: 'user', content: text };
    if (drafts.length) {
      userMsg.attachments = drafts.slice();
      bigChatDraftsMap.delete(runId);
      renderBigChatDraftBar();
    }
    t.messages.push(userMsg);
    input.value = '';
    autoGrowTextarea(input);
  }
  const paintThread = () => { if (onThisThread()) renderBigChatMessages(); };
  paintThread(); updateBadges(); renderBigChatThreadSelector();
 const settings = state.apiSettings;
  
  
  
  
 // Rebuilt each step below so mid-run edits to provider routing take effect.
  let bigModelSettings = bigChatEffectiveSettings(t, model);
  const tools = buildBigChatToolSchemas(t);
  const enabledBigChatTools = getBigChatEnabledToolNames(t);
  const bigChatToolsEnabled = t.bigChatToolsEnabled !== false;
  const enabledPresetIds = getBigChatEnabledPresetIds(t);
  let iteration = 0;
  const MAX_ITER = Math.max(1, settings.agentMaxSteps || 500);
  const runStart = Date.now();
  const run = bigChatRuns[runId];
  if (run) { run.step = 0; run.cost = 0; run.startedAt = runStart; }
  const compactAt = settings.agentCompactAt || 0.7;
  
  
  const memoryCtx = await buildMemoryContext(t);
  
  
  await hydrateBigChatThreadAttachments(t);

  while (iteration < MAX_ITER) { try {
    iteration++;
    if (run) run.step = iteration;

    // Re-derive settings every step: bigChatEffectiveSettings copies
    // state.apiSettings when the thread forces a provider/thinking level, so a
    // snapshot taken before the loop would keep using the old provider list
    // after the user edits Provider routing mid-run.
    bigModelSettings = bigChatEffectiveSettings(t, model);

    
    // Recomputed every step, like the routing above: which model and provider
    // serve this step can change mid-run (429 and error cooldowns, model
    // fallback), so a ceiling snapshotted before the loop can be calibrated for
    // a model that is no longer the one answering.
    const ctxLimit = bigChatContextLimit(model);
    if (settings.agentCompact !== false) {
      const used = estimateMessagesTokens(t.messages) + estimateTokens(t.systemPrompt || '');
      if (used > ctxLimit * compactAt) {
        const before = t.messages.length;
        const did = await compactThread(t, model || getDefaultBigChatModel(), bigModelSettings, setStatus, ctxLimit);
        if (did) { paintThread(); showToast(`Context compacted (${before} → ${t.messages.length} messages)`, 'info'); }
      }
    }

    const apiMessages = buildBigChatApiMessages(runId);
    const elapsedMin = ((Date.now() - runStart) / 60000).toFixed(1);
    const costStr = run && run.cost ? ` · $${run.cost.toFixed(3)}` : '';
    setStatus(`Step ${iteration}/${MAX_ITER} · ${elapsedMin}m${costStr}`);
    let result;
    const activePreset = (t.preset || '').trim();
    let modelsToTry;
    if (activePreset) {
      modelsToTry = getPresetModelList(activePreset, null);
    } else {
      // Auto (empty model) walks the full fallback list; a pinned model stays single.
      modelsToTry = bigChatModelsToTry(t, model);
    }
    const presetSettings = activePreset ? getPresetSettings(activePreset) : null;
    const effectiveSysPrompt = [
      (t.systemPrompt && t.systemPrompt.trim()) ? t.systemPrompt : (presetSettings && presetSettings.systemPrompt ? presetSettings.systemPrompt : ''),
      memoryCtx,
    ].filter(Boolean).join('\n\n');

    const live = { role: 'assistant', content: '', reasoning: '', streaming: true };
    let liveAdded = false;
    let raf = null;
    const paint = () => { raf = null; if (onThisThread()) updateStreamingMessage(live); };

    result = await executeWithRoutingAndRetries({
      modelsToTry,
      settings: bigModelSettings,
      forcedProvider: (t.provider || '').trim() || null,
      abortSignal: runController.signal,
      isBigChat: true,
      callOnceFn: async (modelStr, providerOverride, cbDelta) => {
        let res;
        if (settings.enableStreaming !== false) {
          if (!liveAdded) {
            t.messages.push(live);
            liveAdded = true;
            paintThread();
          }
          res = await callBigChatApiStream({
            model: modelStr,
            messages: apiMessages,
            systemPrompt: effectiveSysPrompt,
            tools,
            settings: bigModelSettings,
            abortController: runController,
            providerOverride,
            onDelta: ({ content, reasoning, reset }) => {
              if (reset) { live.content = ''; live.reasoning = ''; }
              if (content) live.content += content;
              if (reasoning) live.reasoning += reasoning;
              if (raf == null) raf = requestAnimationFrame(paint);
              // Hard-kill durability: debounce a save of the partial reply.
              scheduleBigChatLiveSave();
            }
          });
          if (res.unsupported) {
            res = await callBigChatApi({
              model: modelStr,
              messages: apiMessages,
              systemPrompt: effectiveSysPrompt,
              tools,
              settings: bigModelSettings,
              abortController: runController,
              providerOverride
            });
          }
        } else {
          res = await callBigChatApi({
            model: modelStr,
            messages: apiMessages,
            systemPrompt: effectiveSysPrompt,
            tools,
            settings: bigModelSettings,
            abortController: runController,
            providerOverride
          });
        }
        return res;
      },
      onStatusTick: (sec, errStr, modelStr, providerStr) => {
        const txt = `Error: ${errStr} — retrying in ${sec}s… (${modelStr})`;
        setStatus(txt);
        if (!liveAdded) {
          t.messages.push(live);
          liveAdded = true;
        }
        live.content = `⚠️ Error — retrying in ${sec}s…\n(${errStr})\nModel: ${modelStr}${providerStr ? ` · Provider: ${providerStr}` : ''}`;
        live.streaming = true;
        paintThread();
        // Keep the retry state visible after a hard kill too.
        scheduleBigChatLiveSave();
      }
    });

    if (raf != null) cancelAnimationFrame(raf);
    if (liveAdded) {
      const li = t.messages.indexOf(live);
      if (li >= 0) t.messages.splice(li, 1);
    }

    
    if (result.ok && run) {
      const inTok = estimateMessagesTokens(apiMessages) + estimateTokens(effectiveSysPrompt || '');
      const outMsg = result.body?.choices?.[0]?.message || {};
      const outTok = estimateTokens(outMsg.content || '') + estimateTokens(outMsg.reasoning || '');
      run.cost = (run.cost || 0) + estimateCallCost(result.model || model, inTok, outTok);
    }
    if (!result.ok) {
      if (result.aborted) { paintThread(); updateBadges(); break; }
      t.messages.push({ role: 'assistant', content: null, error: result.error, provider: result.provider }); paintThread(); updateBadges(); try { playRandomErrorSound(); } catch {} break;
    }
    
    if (run) { run._autoRetried = false; run._autoRetried2 = false; }
    const choice = result.body.choices && result.body.choices[0];
    const msg = choice ? choice.message : null
    // A repetition loop was detected mid-stream: the message is already pruned
    // (repeats removed). Run the tool calls that survived, then tell the model
    // to continue where it actually left off.
    if (msg && msg.abortedLoop && msg.tool_calls && msg.tool_calls.length) {
      const keptCalls = msg.tool_calls.map(tc => ({ id: tc.id, name: tc.function && tc.function.name, args: parseJsonSafe(tc.function && tc.function.arguments) }));
      t.messages.push({ role: 'assistant', content: msg.content || '', reasoning: msg.reasoning || '', toolCalls: keptCalls, elapsed: result.elapsed, model: (result.body && result.body.model) || modelsToTry[0], provider: result.provider, fellBack: result.fellBack || false, attemptedPairs: result.attemptedPairs || null });
      t.messages.push({ role: 'user', content: repeatLoopPrompt(msg.loopUnit), autoContinue: true });
      if (run) run.loopContinues = (run.loopContinues || 0) + 1;
      setStatus(`Repetition loop cut off (${msg.loopKind}) — auto-continuing…`);
      paintThread();
      const ctx = { bigChatToolsEnabled, enabledBigChatTools, t, enabledPresetIds, settings };
      let loopOutcomes;
      try {
        loopOutcomes = settings.parallelCallsEnabled !== false && keptCalls.length > 1
          ? await runParallelToolBatch(keptCalls, tc => runOneBigChatTool(tc, ctx), 'bigchat')
          : await runSequential(keptCalls, tc => runOneBigChatTool(tc, ctx));
      } catch (e) {
        loopOutcomes = keptCalls.map(tc => ({ message: { role: 'tool', tool_call_id: tc.id, content: `ERROR: tool dispatch failed: ${e && e.message ? e.message : e}`, toolName: tc.name, ok: false } }));
      }
      for (const out of loopOutcomes) t.messages.push(capBigChatToolResult(out.message));
      paintThread();
      // Durability checkpoint: persist the completed step (assistant tool-call
      // message and tool results) so a hard kill never loses finished work.
      flushBigChatLiveSave();
      continue;
    }
    if (msg && msg.abortedLoop) {
      // Loop in plain text/reasoning: keep the pruned reply, then nudge.
      t.messages.push({ role: 'assistant', content: msg.content || '', reasoning: msg.reasoning || '', elapsed: result.elapsed, model: (result.body && result.body.model) || modelsToTry[0] || model, provider: result.provider, fellBack: result.fellBack || false, attemptedPairs: result.attemptedPairs || null });
      t.messages.push({ role: 'user', content: repeatLoopPrompt(msg.loopUnit), autoContinue: true });
      if (run) run.loopContinues = (run.loopContinues || 0) + 1;
      setStatus(`Repetition loop cut off (${msg.loopKind}) — auto-continuing…`);
      paintThread(); updateBadges();
      continue;
    }
    if (msg && msg.tool_calls && msg.tool_calls.length) {
      const toolCalls = msg.tool_calls.map(tc => ({ id: tc.id, name: tc.function && tc.function.name, args: parseJsonSafe(tc.function && tc.function.arguments) }));
      t.messages.push({ role: 'assistant', content: msg.content || '', reasoning: msg.reasoning || '', toolCalls, elapsed: result.elapsed, model: (result.body && result.body.model) || modelsToTry[0], provider: result.provider, fellBack: result.fellBack || false, attemptedPairs: result.attemptedPairs || null });
      paintThread();
      
      
      
      
      
      const useParallel = settings.parallelCallsEnabled !== false;
      setStatus(`Running ${toolCalls.length} tool${toolCalls.length === 1 ? '' : 's'}${useParallel && toolCalls.length > 1 ? ' (parallel)' : ''}…`);
      
      
      
      let outcomes;
      try {
        const askCall = toolCalls.find(tc => (tc.name || '').trim().toLowerCase() === 'ask_user');
        if (askCall) {
          if (run) setStatus('Waiting for your answer…');
          const others = toolCalls.filter(tc => tc !== askCall);
          const ctx = { bigChatToolsEnabled, enabledBigChatTools, t, enabledPresetIds, settings };
          const first = await runOneBigChatTool(askCall, ctx);
          const rest = others.length ? await runSequential(others, tc => runOneBigChatTool(tc, ctx)) : [];
          outcomes = [first, ...rest];
          if (run && others.length) setStatus(`Running ${others.length} other tool${others.length === 1 ? '' : 's'}…`);
        } else {
          outcomes = useParallel
            ? await runParallelToolBatch(toolCalls, tc => runOneBigChatTool(tc, { bigChatToolsEnabled, enabledBigChatTools, t, enabledPresetIds, settings }), 'bigchat')
            : await runSequential(toolCalls, tc => runOneBigChatTool(tc, { bigChatToolsEnabled, enabledBigChatTools, t, enabledPresetIds, settings }));
        }
      } catch (e) {
        // A dispatch bug must never kill the run loop (that freezes the thread at
        // "Running N tools…"): report the error per tool call and let the model recover.
        outcomes = toolCalls.map(tc => ({ message: { role: 'tool', tool_call_id: tc.id, content: `ERROR: tool dispatch failed: ${e && e.message ? e.message : e}`, toolName: tc.name, ok: false } }));
      }
      for (const out of outcomes) t.messages.push(capBigChatToolResult(out.message));
      // Durability checkpoint: persist the completed step (assistant message
      // and tool results) so a hard kill never loses finished work.
      flushBigChatLiveSave();
      paintThread();
      updateBadges();
    } else {
      const finalContent = (msg && msg.content) || '';
      const finalReasoning = (msg && msg.reasoning) || '';
      const autoCount = (run && run.autoContinueCount) || 0;
      
      
      
      if (!String(finalContent).trim() && String(finalReasoning).trim() && autoCount < AUTO_CONTINUE_LIMIT) {
        if (run) run.autoContinueCount = autoCount + 1;
        setStatus(`Model replied with thinking only — auto-continuing (${autoCount + 1}/${AUTO_CONTINUE_LIMIT})…`);
        t.messages.push({ role: 'assistant', content: '', reasoning: finalReasoning, elapsed: result.elapsed, model: (result.body && result.body.model) || modelsToTry[0] || model, provider: result.provider, fellBack: result.fellBack || false, attemptedPairs: result.attemptedPairs || null });
        t.messages.push({ role: 'user', content: buildAutoContinuePrompt(finalReasoning), autoContinue: true });
        paintThread(); updateBadges();
        continue;
      }
      t.messages.push({ role: 'assistant', content: finalContent || '(no response)', reasoning: finalReasoning, elapsed: result.elapsed, model: (result.body && result.body.model) || modelsToTry[0] || model, provider: result.provider, fellBack: result.fellBack || false, attemptedPairs: result.attemptedPairs || null });
      paintThread(); updateBadges(); break;
    }
  } catch (loopErr) {
    // A dispatch bug or storage failure must never strand the thread with a
    // stuck run record, a phantom streaming bubble, or a dangling tool_calls
    // shape — sanitize (which finalizes the live message), persist, and stop.
    if (liveAdded) {
      const li = t.messages.indexOf(live);
      if (li >= 0) t.messages.splice(li, 1);
    }
    sanitizeBigChatThreadAfterCrash(t);
    flushBigChatLiveSave();
    t.messages.push({ role: 'assistant', content: null, error: (loopErr && loopErr.message) ? String(loopErr.message) : String(loopErr), provider: null });
    paintThread(); updateBadges(); try { playRandomErrorSound(); } catch {}
    break;
  } }
  if (iteration >= MAX_ITER) {
    const left = threadTasks(t).filter(x => !x.done).length;
    t.messages.push({ role: 'assistant', content: `⏸ **Step budget reached** (${MAX_ITER} steps).${left ? ` ${left} task${left === 1 ? '' : 's'} still open.` : ''} Send a message to continue where it left off, or raise "Max steps per run" in Settings → Agent Tools.` });
    paintThread();
  }
  delete bigChatRuns[runId];
  // Release the workspace pin (restore any outer value for safety, though runs
  // are not nested).
  workspaceOwnerThreadId = (prevWorkspaceOwnerThreadId === runId) ? null : prevWorkspaceOwnerThreadId;
  // Run over: stop any subagents still alive and cancel queued ones so nothing
  // keeps running (or starts) once the parent turn is done. During an
  // app-close wind-down the sub-agents are being gracefully PAUSED instead —
  // stopping them here would abort their parking mid-step.
  if (!isSubagentCloseWindDownActive()) requestStopAllBigChatSubagents(runId);
  resolveAskUserQuestion(undefined); 
  clearBigChatQuestionQueue(); 
  updateBigChatInputState();
  if (onThisThread()) { document.getElementById('bigChatStatus').textContent = ''; renderBigChatMessages(); }
  renderBigChatThreadSelector();
  flushBigChatLiveSave();
  renderBigChatSubagentSidebar();
  notifyDesktop('Big Chat — Done', `Thread "${getBigChatData().threads[runId] ? getBigChatData().threads[runId].name : 'chat'}" finished responding.`);
}


function renderFileList() {
  const list = document.getElementById('fileList');
  if (state.currentInputs.length === 0) { list.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; padding: 4px;">No files loaded.</div>'; return; }
  list.innerHTML = state.currentInputs.map((input, i) => `<div class="file-item"><span class="file-name-wrap"><span class="preset-name">${escapeHtml(input.preset)}</span>${input.runError ? '<span class="file-status-check error" title="Errored in the latest run">✗</span>' : (input.runCompleted ? '<span class="file-status-check" title="Completed in the latest run">✓</span>' : '')}</span><button class="remove" data-idx="${i}" title="Remove">×</button></div>`).join('');
  list.querySelectorAll('.remove').forEach(btn => { btn.onclick = (e) => { const idx = parseInt(e.target.dataset.idx); state.currentInputs.splice(idx, 1); renderFileList(); }; });
}

function renderTurnList() {
  const list = document.getElementById('turnList');
  if (state.turns.length === 0) { list.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; padding: 8px;">No turns run yet.</div>'; return; }
  list.innerHTML = state.turns.slice().reverse().map(turn => {
    const okCount = turn.outputs.filter(o => o.status === 'ok').length;
    const errCount = turn.outputs.filter(o => o.status === 'error').length;
    const time = new Date(turn.startedAt).toLocaleTimeString();
    return `<div class="turn-item" data-id="${turn.id}"><span>Turn ${turn.turnNumber}</span><span class="turn-meta">${okCount}✓ ${errCount}✗ · ${time}</span></div>`;
  }).join('');
}

function renderChatHistory() {
  const container = document.getElementById('chatHistory');
  if (state.turns.length === 0) { container.innerHTML = `<div class="empty-state"><h3>No chat history yet</h3><p>Load some input files and click "Run Turn" to see API responses here.</p></div>`; return; }
  const turn = state.turns[state.turns.length - 1];
  const okCount = turn.outputs.filter(o => o.status === 'ok').length;
  const errCount = turn.outputs.filter(o => o.status === 'error').length;
  const pendingCount = turn.outputs.filter(o => o.status === 'pending' || o.status === 'running').length;
  const startTime = new Date(turn.startedAt).toLocaleString();
  const historyNote = state.apiSettings.maintainHistory ? ` · History: ON` : ` · History: OFF`;
  let html = `<div class="turn-section"><div class="turn-header"><h2>Turn ${turn.turnNumber}</h2><span class="turn-stats">Started ${startTime} · ${okCount} OK · ${errCount} error${errCount === 1 ? '' : 's'} · ${pendingCount} pending${turn.completedAt ? ' · ' + Math.round((new Date(turn.completedAt) - new Date(turn.startedAt)) / 1000) + 's total' : ''}${historyNote}</span></div><div class="character-grid">`;    for (let i = 0; i < turn.outputs.length; i++) { const input = turn.inputs[i], out = turn.outputs[i], histLen = (turn.historyLength || {})[input.preset] || 1; html += renderCharacterCard(input, out, histLen, turn.id, i); }
  html += `</div></div>`; container.innerHTML = html;
  container.querySelectorAll('.card-input-toggle').forEach(el => { el.onclick = () => { const textEl = el.parentElement.querySelector('.card-input-text'); textEl.classList.toggle('hidden'); el.textContent = textEl.classList.contains('hidden') ? `▸ Show input (${el.dataset.len} chars)` : `▾ Hide input`; }; });
  container.querySelectorAll('.download-btn').forEach(btn => { btn.onclick = (e) => { e.preventDefault(); e.stopPropagation(); const preset = btn.dataset.preset, b64 = btn.dataset.content; if (!b64) return; try { const content = decodeURIComponent(escape(atob(b64))); const blob = new Blob([content], { type: 'text/markdown' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `${preset}_output.md`; a.click(); URL.revokeObjectURL(url); } catch (err) { console.error('Download failed:', err); } }; });
  container.querySelectorAll('.retry-turn-btn').forEach(btn => { btn.onclick = (e) => { e.preventDefault(); e.stopPropagation(); const turnId = parseInt(btn.dataset.turnId), presetIdx = parseInt(btn.dataset.presetIdx); retryTurnOutput(turnId, presetIdx); }; });
}

function renderCharacterCard(input, out, histLen, turnId, presetIndex) {
  const statusClass = `status-${out.status}`;
  const statusLabel = { pending: '⏳ PENDING', running: '⚡ RUNNING', ok: '✓ OK', error: '✗ ERROR' }[out.status] || out.status.toUpperCase();
  const cardClass = out.status === 'error' ? 'character-card error' : out.status === 'running' ? 'character-card running' : 'character-card';
  let bodyHtml;
  if (out.status === 'ok') bodyHtml = `<div class="output">${escapeHtml(out.content)}</div>`;
  else if (out.status === 'error') {
    const statusCode = extractStatusCode(out.error);
    const badge = statusCode ? `<span style="display:inline-block;background:rgba(248,81,73,0.2);color:var(--red);padding:1px 5px;border-radius:8px;font-size:9px;font-weight:600;margin-bottom:4px;">HTTP ${statusCode} — ${escapeHtml((HTTP_ERROR_INFO[statusCode]||{}).title||'Error')}</span>` : '';
    bodyHtml = `<div class="output error-msg">${badge}${escapeHtml(out.error)}</div>`;
  }
  else if (out.status === 'running') bodyHtml = `<div class="output" style="color: var(--text-muted);">⏳ Calling @preset/${escapeHtml(input.preset)} (${histLen} message${histLen === 1 ? '' : 's'} in history)...</div>`;
  else bodyHtml = `<div class="output" style="color: var(--text-muted);">Queued. Will send ${histLen} message${histLen === 1 ? '' : 's'} to API.</div>`;
  const elapsedStr = out.elapsed != null ? `${out.elapsed.toFixed(1)}s` : '—';
  const inputLen = input.content.length, inputEscaped = escapeHtml(input.content);
  return `<div class="${cardClass}"><div class="card-header"><div class="card-title">${escapeHtml(input.preset)}<span class="preset">@preset/${escapeHtml(input.preset)}</span></div><span class="card-status ${statusClass}">${statusLabel}</span></div><div class="card-body"><div class="card-input-toggle" data-len="${inputLen}">▸ Show input (${inputLen} chars)</div><div class="card-input-text hidden">${inputEscaped}</div>${bodyHtml}</div><div class="card-footer"><span class="meta">⏱ ${elapsedStr} · ${histLen} msg${histLen === 1 ? '' : 's'} sent${out.model ? ` · ${escapeHtml(out.model)}` : ''}${out.fellBack || (out.attemptedPairs && out.attemptedPairs.length > 1) ? ` · ${fallbackBadgeHtml(out)}` : ''}</span><span style="display: flex; gap: 4px;">${out.status !== 'running' && out.status !== 'pending' ? `<button class="retry-turn-btn small" data-turn-id="${turnId}" data-preset-idx="${presetIndex}" title="Retry this API call">🔄 Retry</button>` : ''}${out.status === 'ok' ? `<button class="download-btn small" data-preset="${escapeHtml(input.preset)}" data-content="${escapeHtmlBase64(out.content)}">⬇ .md</button>` : ''}</span></div></div>`;
}

function toggleSidebarFolder(folderName) {
  if (!folderName) return;
  if (!Array.isArray(state.collapsedFolders)) state.collapsedFolders = [];
  const i = state.collapsedFolders.indexOf(folderName);
  if (i >= 0) state.collapsedFolders.splice(i, 1);
  else state.collapsedFolders.push(folderName);
  saveState();
  renderChatSidebar();
}

function renderChatSidebar() {
  const list = document.getElementById('chatCharList');
  if (!list) return;
  
  
  
  const sidebar = document.getElementById('chatSidebarPanel');
  const savedScrollTop = list.scrollTop;
  const savedSidebarScrollTop = sidebar ? sidebar.scrollTop : 0;

  const foldersMap = {};
  for (const [preset, displayName, color, folder] of CHARACTERS) {
    const fName = folder || 'Among Us';
    if (!foldersMap[fName]) foldersMap[fName] = [];
    foldersMap[fName].push([preset, displayName, color]);
  }

  const folderNames = Object.keys(foldersMap).sort();

  let html = '';
  for (const fName of folderNames) {
    const chars = foldersMap[fName];
    const collapsed = (state.collapsedFolders || []).includes(fName);
    let folderMsgs = 0;
    for (const [p] of chars) { const d = getPresetData(p); for (const th of Object.values(d.threads)) folderMsgs += (th.messages || []).length; }
    html += `<div class="sidebar-folder-header ${collapsed ? 'collapsed' : ''}" data-folder="${escapeHtml(fName)}" title="${collapsed ? 'Show' : 'Hide'} ${escapeHtml(fName)}" style="font-size: 11px; font-weight: 700; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; padding: 10px 12px 4px; margin-top: 4px; border-top: 1px solid var(--border);"><span class="folder-caret">▼</span>📁 ${escapeHtml(fName)}<span class="folder-couunt">${collapsed ? chars.length : folderMsgs}</span></div>`;
   if (collapsed) continue;
    for (const [preset, displayName, color] of chars) {
      const pd = getPresetData(preset);
      let msgCount = 0;
      for (const t of Object.values(pd.threads)) msgCount += (t.messages || []).length;
      const hasConvo = msgCount > 0;
      const isActive = preset === state.activeChatPreset ? 'active' : '';
      const isSelected = state.selectedChatPresets.has(preset) ? 'checked' : '';
      const activeThread = pd.threads[pd.activeThreadId];
      const lastMsg = activeThread && activeThread.messages.length > 0 ? activeThread.messages[activeThread.messages.length - 1] : null;
      const preview = lastMsg ? `${lastMsg.role === 'user' ? '→' : (lastMsg.toolCall ? '🔧←' : '←')} ${lastMsg.content.slice(0, 40)}${lastMsg.content.length > 40 ? '...' : ''}` : 'No messages yet';
      html += `<div class="chat-char-item ${isActive} ${hasConvo ? 'has-convo' : ''}" data-preset="${escapeHtml(preset)}"><input type="checkbox" class="chat-char-checkbox" data-preset="${escapeHtml(preset)}" ${isSelected}><div class="color-dot" style="background: ${color};"></div><div class="char-info"><div class="char-name" title="${escapeHtml(preset)}">${escapeHtml(displayName)} <span class="preset-tag">${escapeHtml(preset)}</span></div><div class="char-preview">${escapeHtml(preview)}</div></div><div class="msg-count">${msgCount}</div></div>`;
    }
  }

  list.innerHTML = html;
  list.scrollTop = savedScrollTop;
  if (sidebar) sidebar.scrollTop = savedSidebarScrollTop;
  list.querySelectorAll('.sidebar-folder-header').forEach(el => { el.onclick = () => toggleSidebarFolder(el.dataset.folder); });
  list.querySelectorAll('.chat-char-item').forEach(el => { el.onclick = (e) => { if (e.target.classList.contains('chat-char-checkbox')) return; selectChatPreset(el.dataset.preset); }; });
  list.querySelectorAll('.chat-char-checkbox').forEach(cb => { cb.onclick = (e) => { e.stopPropagation(); toggleChatPresetSelection(cb.dataset.preset); }; });
}



function ensureMsgVersions(msg) {
  if (!Array.isArray(msg.versions) || !msg.versions.length) {
    msg.versions = [{ content: msg.content || '', reasoning: msg.reasoning || '', timestamp: msg.timestamp || new Date().toISOString(), model: msg.model || null, provider: msg.provider || null, fellBack: msg.fellBack || false, attemptedPairs: msg.attemptedPairs || null }];
    msg.activeVersion = 0;
  }
  if (typeof msg.activeVersion !== 'number' || msg.activeVersion < 0 || msg.activeVersion >= msg.versions.length) {
    msg.activeVersion = msg.versions.length - 1;
  }
  return msg;
}
function addMsgVersion(msg, content, extra = {}) {
  ensureMsgVersions(msg);
  msg.versions.push({ content, reasoning: extra.reasoning || '', timestamp: new Date().toISOString(), model: extra.model || msg.model || null, provider: extra.provider !== undefined ? (extra.provider || null) : (msg.provider || null), fellBack: extra.fellBack !== undefined ? !!extra.fellBack : !!msg.fellBack, attemptedPairs: extra.attemptedPairs !== undefined ? (extra.attemptedPairs || null) : (msg.attemptedPairs || null), edited: extra.edited !== false });
  msg.activeVersion = msg.versions.length - 1;
  applyMsgVersion(msg);
}
function applyMsgVersion(msg) {
  const v = msg.versions[msg.activeVersion];
  if (!v) return;
  msg.content = v.content;
  msg.reasoning = v.reasoning || '';
  if (v.model) msg.model = v.model;
  if (v.provider !== undefined) msg.provider = v.provider || null;
  if (v.fellBack !== undefined) msg.fellBack = v.fellBack;
  if (v.attemptedPairs !== undefined) msg.attemptedPairs = v.attemptedPairs || null;
}
function switchMsgVersion(msg, dir, conv, idx) {
  ensureMsgVersions(msg);
  const next = msg.activeVersion + dir;
  if (next < 0 || next >= msg.versions.length) return false;
  if (Array.isArray(conv) && typeof idx === 'number' && idx >= 0 && idx < conv.length) {
    msg.versions[msg.activeVersion].children = conv.slice(idx + 1);
    msg.activeVersion = next;
    applyMsgVersion(msg);
    const nextChildren = msg.versions[msg.activeVersion].children || [];
    conv.splice(idx + 1, conv.length - (idx + 1), ...nextChildren);
  } else {
    msg.activeVersion = next;
    applyMsgVersion(msg);
  }
  return true;
}
function versionNavHtml(msg) {
  if (!Array.isArray(msg.versions) || msg.versions.length < 2) return '';
  const i = msg.activeVersion, n = msg.versions.length;
  return `<span class="msg-versions" title="Switch between edited versions">
    <button class="ver-prev" ${i === 0 ? 'disabled' : ''} title="Previous version">‹</button>
    <span>${i + 1}/${n}</span>
    <button class="ver-next" ${i === n - 1 ? 'disabled' : ''} title="Next version">›</button>
  </span>`;
}
function msgToolsHtml(canEdit, canSpeak, canResend = false) {
  const bits = [];
  if (canSpeak) bits.push('<button type="button" class="msg-speak-btn" title="Read aloud (TTS)" style="padding:1px 5px;font-size:11px;line-height:1.2;">▶</button>');
  if (canEdit) bits.push('<button type="button" class="msg-edit-btn" title="Edit message (branches chat in place)" style="padding:1px 5px;font-size:11px;line-height:1.2;">✎</button>');
  if (canResend) bits.push('<button type="button" class="msg-resend-btn" title="Resend message (branches chat in place)" style="padding:1px 5px;font-size:11px;line-height:1.2;">🔄</button>');
  if (!bits.length) return '';
  return '<span class="msg-tools">' + bits.join('') + '</span>';
}

function openMsgEditor(bubbleEl, msg, onSave, isUserMessage = false) {
  if (!bubbleEl || bubbleEl.querySelector('.msg-edit-area')) return;
  ensureMsgVersions(msg);
  msg._prevActiveVersion = msg.activeVersion;
  const original = msg.content || '';
  bubbleEl.classList.add('editing');
  bubbleEl.innerHTML = `<div class="msg-edit-area">
    <textarea spellcheck="false"></textarea>
    <div class="msg-edit-actions">
      <button class="small primary msg-save">Save</button>
      <button class="small msg-cancel">Cancel</button>
      <span class="hint">Ctrl+Enter to save · Esc to cancel</span>
    </div>
  </div>`;
  const ta = bubbleEl.querySelector('textarea');
  ta.value = original;
  const fit = () => {
    ta.style.height = 'auto';
   const max = Math.round(window.innerHeight * 0.7);
    const next = Math.min(Math.max(ta.scrollHeight, 220), max);
    ta.style.height = next + 'px';
    ta.style.overflowY = ta.scrollHeight > max ? 'auto' : 'hidden';
  };
  fit();
  ta.focus();
  ta.setSelectionRange(ta.value.length, ta.value.length);
  ta.addEventListener('input', fit);
  const finish = (changed, newText) => { bubbleEl.classList.remove('editing'); onSave(changed, newText); };
  const save = () => {
    const val = ta.value;
    if (isUserMessage && val !== original) {
      finish(true, val);
    } else {
      if (val !== original) addMsgVersion(msg, val, { reasoning: msg.reasoning });
      finish(val !== original, val);
    }
  };
  const cancel = () => finish(false, undefined);
  bubbleEl.querySelector('.msg-save').onclick = save;
  bubbleEl.querySelector('.msg-cancel').onclick = cancel;
  ta.onkeydown = (e) => {
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); save(); }
    else if (e.key === 'Escape') { e.preventDefault(); cancel(); }
  };
}

function branchUserMessageInPlace(conv, idx, newContent, sendFn) {
  const msg = Array.isArray(conv) ? conv[idx] : null;
  if (!msg || msg.role !== 'user') return;
  ensureMsgVersions(msg);
  msg.versions[msg.activeVersion].children = conv.slice(idx + 1);
  msg.versions.push({
    content: newContent,
    reasoning: '',
    timestamp: new Date().toISOString(),
    model: msg.model || null,
    children: []
  });
  msg.activeVersion = msg.versions.length - 1;
  applyMsgVersion(msg);
  conv.splice(idx + 1, conv.length - (idx + 1));
  saveState();
  if (sendFn) sendFn();
}

// The re-run after a regenerate continues the thread with no new user turn, so
// without this it had to re-derive what it was doing from a transcript whose
// nearest user turn could be twenty messages back. In the run that motivated
// it, the agent restarted a code review by re-reading a 20k-line file from the
// top instead of synthesising the reports it had already been given.
function buildRegenerateResumePrompt(t, replacedCount) {
  const firstUser = (t.messages || []).find(m => m.role === 'user' && !m.autoContinue && String(m.content || '').trim());
  const open = threadTasks(t).filter(x => !x.done).map((x, i) => `${i + 1}. ${x.text}`);
  return [
    `🔄 [regenerated] Your previous reply was discarded for regeneration, along with the ${Math.max(0, replacedCount - 1)} message(s) that followed it.`,
    'Your task is unchanged — continue it from here, and do not restart your investigation from the beginning.',
    firstUser ? `The original request was:\n${truncateWithNote(firstUser.content, 2000)}` : '',
    open.length ? `Open checklist:\n${open.join('\n')}` : '',
  ].filter(Boolean).join('\n\n');
}

function retryBigChatMessage(bcIdx) {
  const bc = getBigChatData();
  const t = bc.threads[bc.activeThreadId];
  if (!t || !t.messages || !t.messages[bcIdx]) return;
  // In a long agent run this cut is destructive: everything produced after this
  // message is discarded, including tool results the run is still working from.
  // Ask before throwing away a continuation instead of doing it silently.
  const discarded = t.messages.slice(bcIdx);
  if (discarded.length > 4 && !confirm(`Regenerate this response?\n\nThe reply and the ${discarded.length - 1} message(s) after it will be discarded (tool results included).`)) return;
  t.messages = t.messages.slice(0, bcIdx);
  t.messages.push({ role: 'user', content: buildRegenerateResumePrompt(t, discarded.length), autoContinue: true, regenerated: true, replaced: discarded.length });
  saveState();
  renderBigChatMessages();
  sendBigChatMessage(true);
}

async function sendChatRequestForPreset(preset) {
  if (isChatSending) return;
  if (!state.apiSettings.apiKey) { openSettings('api'); alert('Please enter your OpenRouter API key in Settings first.'); return; }
  const conv = getConversation(preset);
  conv.push({ role: 'assistant', content: '...', timestamp: new Date().toISOString(), pending: true });
  isChatSending = true; chatAbortController = new AbortController();
  document.getElementById('sendChatBtn').disabled = true;
  const rStop = document.getElementById('chatStopBtn'); if (rStop) { rStop.style.display = ''; rStop.disabled = false; }
  const charInfo = CHARACTERS.find(c => c[0] === preset);
  const displayName = charInfo ? charInfo[1] : preset;
  document.getElementById('chatStatus').textContent = `Sending to ${displayName}...`;
  saveState(); renderChatMessages(); renderChatSidebar();
  const allMsgsR = conv.filter(m => !m.pending && !m.error).map(m => ({ role: m.role, content: m.content }));
  let msgsForApi = presetKeepsHistory(preset) ? allMsgsR : allMsgsR.slice(-1);
  const maxHR = state.apiSettings.maxHistory;
  if (presetKeepsHistory(preset) && maxHR > 0 && msgsForApi.length > maxHR) {
    msgsForApi = capMessagesToMax(msgsForApi, maxHR);
  }
  const modelOverride = getChatModelOverride();
  const rIdx = conv.length - 1;
  let rRaf = null;
  const rOnDelta = ({ content, reasoning, reset, retryNotice }) => {
    const ph = conv[rIdx];
    if (!ph || !ph.pending) return;
    if (reset) { ph.content = ''; ph.reasoning = ''; }
    if (retryNotice) { ph.content = retryNotice; ph.streaming = true; }
    else {
      if (content) ph.content = (ph.streaming ? ph.content : '') + content;
      if (reasoning) ph.reasoning = (ph.reasoning || '') + reasoning;
      ph.streaming = true;
    }
    if (rRaf == null) rRaf = requestAnimationFrame(() => { rRaf = null; if (preset === state.activeChatPreset) renderChatMessages(); });
  };
  const result = await callApiWithAutoContinue(preset, msgsForApi, state.apiSettings, chatAbortController ? chatAbortController.signal : null, modelOverride, rOnDelta);
  if (rRaf != null) cancelAnimationFrame(rRaf);
  if (conv[rIdx] && conv[rIdx].pending) {
    if (result.ok) {
      conv[rIdx] = { role: 'assistant', content: result.content, reasoning: result.reasoning || '', timestamp: new Date().toISOString(), elapsed: result.elapsed, model: result.model || null, provider: result.provider || null, fellBack: result.fellBack || false, attemptedPairs: result.attemptedPairs || null };
    } else {
      conv[rIdx] = { role: 'assistant', content: `ERROR: ${result.error}`, timestamp: new Date().toISOString(), elapsed: result.elapsed, error: true };
    }
  }
  isChatSending = false; chatAbortController = null;
  document.getElementById('sendChatBtn').disabled = false;
  if (rStop) rStop.style.display =  'none';
  document.getElementById('chatStatus').textContent = '';
  saveState(); renderChatMessages(); renderChatSidebar(); renderChatThreadSelector(); updateBadges();
}
function renderChatMessages() {
  const container = document.getElementById('chatMessages');
  const targetInfo = document.getElementById('chatTargetInfo');
  if (!state.activeChatPreset) {
    targetInfo.innerHTM = `<span style="color: var(--text-muted);">Select a character to start chatting</span>`;
    container.innerHTML = `<div class="chat-empty"><h3>No character selected</h3><p>Click a character on the left to start chatting.</p><p style="margin-top: 12px; foont-size: 11px;">Tip: check "Send to all selected" below to broadcast a message to multiple characters at once.</p></div>`;
    return;
  }
  const preset = state.activeChatPreset;
  const charInfo = CHARACTERS.find(c => c[0] === preset);
  const displayName = charInfo ? charInfo[1] : preset, color = charInfo ? charInfo[2] : '#888';
  const conv = getConversation(preset);
  const pd = getPresetData(preset);
  const activeThread = pd.threads[pd.activeThreadId];
  const threadName = activeThread ? activeThread.name : 'Main';
  targetInfo.innerHTML = `<div class="color-dot" style="background: ${color};"></div><div><div class="target-name">${escapeHtml(displayName)}</div><div class="target-preset">@preset/${escapeHtml(preset)} · ${conv.length} message${conv.length === 1 ? '' : 's'} · ${escapeHtml(threadName)}</div></div>`;
  if (conv.length === 0) {
    container.innerHTML = `<div class="chat-empty"><h3>No messages yet</h3><p>Type a message below to start chatting with ${escapeHtml(displayName)}.</p><p style="margin-top: 12px; font-size: 11px;">${state.apiSettings.maintainHistory ? '✓ Conversation history is ON' : '⚠ Conversation history is OFF'}</p></div>`;
    return;
  }
  const nearBottomBefore = isNearChatBottom(container);
  container.innerHTML = conv.map((msg, idx) => {
    const isError = msg.error, isPending = msg.pending, isToolCall = msg.toolCall;
    let cls;
    if (msg.role === 'user') cls = isToolCall ? 'tool-call preset-colored' : 'user';
    else cls = isError ? 'assistant error' : (isPending ? 'assistant pending' : (isToolCall ? 'tool-call preset-colored' : 'assistant'));
    const msgStyle = isToolCall && !isError ? ` style="${presetColorStyle(preset, 0.10)}"` : '';
    const time = new Date(msg.timestamp).toLocaleTimeString();
    const elapsedStr = msg.elapsed != null ? ` · ${msg.elapsed.toFixed(1)}s` : '';
    const modelStr = msg.model ? ` · ${escapeHtml(msg.model)}${msg.provider ? ` (${escapeHtml(providerExportLabel(msg.provider))})` : ''}` : '';
    const fallbackBadge = msg.fellBack || (msg.attemptedPairs && msg.attemptedPairs.length > 1) ? ` · ${fallbackBadgeHtml(msg)}` : '';
    const toolHeader = isToolCall
      ? (msg.role === 'user'
        ? `<div class="tool-call-header">🔧 Big Chat → ${escapeHtml(displayName)}</div>`
        : `<div class="tool-call-header">↩ ${escapeHtml(displayName)} → Big Chat</div>`)
      : '';
    const canRetry = msg.role === 'assistant' && !isPending && !isChatSending;
    const retryBtn = canRetry ? `<button class="retry-chat-btn" data-preset="${escapeHtml(preset)}" data-idx="${idx}" style="background: var(--bg-elev); border: 1px solid var(--border); color: var(--text); padding: 0 5px; border-radius: 4px; font-size: 11px; line-height: 1.4; cursor: pointer; margin-left: 6px;" title="Regenerate this response — removes this message and everything after it, then re-runs from here">🔄</button>` : '';
    let meta;
    const isStreaming = isPending && msg.streaming;
    if (msg.role === 'user') meta = `You · ${time}`;
    else if (isStreaming) meta = msg.content ? 'Generating…' : 'Thinking…';
    else meta = isPending ? 'Thinking...' : `${escapeHtml(displayName)} · ${time}${elapsedStr}${modelStr}${fallbackBadge}${retryBtn}`;
    const think = msg.role === 'assistant' ? reasoningHtml(msg.reasoning, isStreaming) : '';
    const bodyText = isStreaming ? escapeHtml(msg.content || '') + '<span class="stream-caret"></span>' : escapeHtml(msg.content);
    const canEdit = !isPending && !isChatSending;
    const canSpeak = msg.role === 'assistant' && !isError && !isPending && !!(msg.content && String(msg.content).trim());
    const canResend = msg.role === 'user' && !isPending && !isChatSending;
    const verNav = versionNavHtml(msg);
    return `<div class="message ${cls}"${msgStyle} data-idx="${idx}">${msgToolsHtml(canEdit, canSpeak, canResend)}${toolHeader}${think}${bodyText}<div class="meta">${verNav}${meta}</div></div>`;
  }).join('');
  if (nearBottomBefore) container.scrollTop = container.scrollHeight;
  container.querySelectorAll('.retry-chat-btn').forEach(btn => { btn.onclick = (e) => { e.preventDefault(); e.stopPropagation(); retryLastChatMessage(btn.dataset.preset, parseInt(btn.dataset.idx)); }; });

  
  container.querySelectorAll('.message[data-idx]').forEach(bubble => {
    const idx = parseInt(bubble.dataset.idx);
    const msg = conv[idx];
    if (!msg) return;
    const editBtn = bubble.querySelector('.msg-edit-btn');
    if (editBtn) editBtn.onclick = (e) => {
      e.stopPropagation();
      const scrollPos = container.scrollTop;
      openMsgEditor(bubble, msg, (changed, newText) => {
        if (changed && msg.role == 'user' && newText !== undefined) {
          branchUserMessageInPlace(conv, idx, newText, () => { renderChatMessages(); sendChatRequestForPreset(preset); });
        } else if (changed) {
          ensureMsgVersions(msg);
          const prevVer = typeof msg._prevActiveVersion === 'number' ? msg._prevActiveVersion : (msg.activeVersion > 0 ? msg.activeVersion - 1 : 0);
          msg.versions[prevVer].children = conv.slice(idx + 1);
          msg.versions[msg.activeVersion].children = [];
          conv.splice(idx + 1, conv.length - (idx + 1));
          delete msg._prevActiveVersion;
          saveState();
          renderChatMessages();
          renderChatSidebar();
          renderChatThreadSelector();
          container.scrollTop = scrollPos;
        }
      }, msg.role === 'user');
    };
    const resendBtn = bubble.querySelector('.msg-resend-btn');
    if (resendBtn) resendBtn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      branchUserMessageInPlace(conv, idx, msg.content || '', () => { renderChatMessages(); sendChatRequestForPreset(preset); });
    };
    const speakBtn = bubble.querySelector('.msg-speak-btn');
    if (speakBtn) speakBtn.onclick = (e) => { e.preventDefault(); e.stopPropagation(); speakMessageText(msg.content, speakBtn); };
    const prev = bubble.querySelector('.ver-prev');
    const next = bubble.querySelector('.ver-next');
    if (prev) prev.onclick = (e) => { e.stopPropagation(); if (switchMsgVersion(msg, -1, conv, idx)) { saveState(); renderChatMessages(); } };
    if (next) next.onclick = (e) => { e.stopPropagation(); if (switchMsgVersion(msg, 1, conv, idx)) { saveState(); renderChatMessages(); } };
  });
}

function updateTurnIndicator() {
  const ind = document.getElementById('turnIndicator');
  if (state.turns.length === 0) ind.textContent = 'No turns yet';
  else { const turn = state.turns[state.turns.length - 1]; const ok = turn.outputs.filter(o => o.status === 'ok').length; ind.textContent = `Turn ${turn.turnNumber} · ${ok}/${turn.outputs.length} OK`; }
}

function updateBadges() {
  document.getElementById('turnsBadge').textContent = state.turns.length;
  let total = 0, convCount = 0;
  for (const pd of Object.values(state.conversations)) {
    if (pd && pd.threads) {
      let hasMsgs = false;
      for (const t of Object.values(pd.threads)) {
        const len = (t.messages || []).length;
        if (len > 0) hasMsgs = true;
        total += len;
      }
      if (hasMsgs) convCount++;
    }
  }
  document.getElementById('chatBadge').textContent = convCount;
  let bcTotal = 0;
  if (state.bigChat && state.bigChat.threads) {
    for (const t of Object.values(state.bigChat.threads)) bcTotal += (t.messages || []).length;
  }
  document.getElementById('bigChatBadge').textContent = bcTotal;
  document.getElementById('convSummary').textContent = `${convCount} conversation${convCount === 1 ? '' : 's'}, ${total} message${total === 1 ? '' : 's'} total`;
}


function switchTab(tabName) {
  state.activeTab = tabName;
  document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.tab === tabName));
  document.querySelectorAll('.tab-view').forEach(v => v.classList.toggle('active', v.id === `${tabName}View`));
  saveState();
  if (tabName === 'desktop') {
    syncDesktopTabVisibility(true);
    if (typeof desktopRenderAppStrip === 'function') desktopRenderAppStrip();
    // The engine and the project can both change while the tab is in the
    // background (a folder gets mounted, an install finishes), so re-read them
    // on show — from cache, so this costs no engine probes.
    if (typeof desktopGodotRefresh === 'function') desktopGodotRefresh().catch(() => {});
  }
  else if (typeof syncDesktopTabVisibility === 'function') syncDesktopTabVisibility(false);
  if (typeof window !== 'undefined' && window.desktopAgent?.desktopTabActive) window.desktopAgent.desktopTabActive(tabName === 'desktop');
  if (tabName === 'chat') { renderChatSidebar(); renderChatMessages(); renderChatThreadSelector(); updateChatInputState(); updateSelectedCount(); }
  else if (tabName === 'bigchat') { populateBigModelSelect(); populateBigProviderSelect(); populateBigThinkingSelect(); populateBigPresetSelect(); renderBigChatCapabilities(); refreshBigChatProviderCompat(); renderBigChatThreadSelector(); renderBigChatMessages(); renderBigChatSubagentSidebar(); updateBigChatInputState(); syncBigSystemPromptEditor(); }
  else if (tabName === 'browser') { agentBrowserPaintNav(); }
  else if (tabName === 'files') {
    
    refreshFilesTree().then(() => {
      if (!filesBaseline) captureFilesBaseline();
      renderFilesTab();
    });
  }
}


const THEME_COLOR_FIELDS = [
  { var: '--accent',       label: 'Accent',            hint: 'buttons, active tabs' },
  { var: '--accent-hover', label: 'Accent (hover)',    hint: 'hover state' },
  { var: '--bg',           label: 'Background',        hint: 'app background' },
  { var: '--bg-elev',      label: 'Surface',           hint: 'panels, header' },
  { var: '--bg-elev-2',    label: 'Surface (raised)',  hint: 'buttons, chips' },
  { var: '--border',       label: 'Border',            hint: 'dividers, outlines' },
  { var: '--text',         label: 'Text',              hint: 'primary text' },
  { var: '--text-muted',   label: 'Text (muted)',      hint: 'secondary text' },
  { var: '--green',        label: 'Success',           hint: 'ok status' },
  { var: '--yellow',       label: 'Warning',           hint: 'running / fallback' },
  { var: '--red',          label: 'Error',             hint: 'errors, delete' },
  { var: '--blue',         label: 'Info',              hint: 'links, model names' },
];
const BUILTIN_THEME_COLORS = {
  dark:  { '--bg': '#0d1117', '--bg-elev': '#161b22', '--bg-elev-2': '#1c2230', '--border': '#30363d', '--text': '#f0f6fc', '--text-muted': '#8b949e', '--accent': '#159c53', '--accent-hover': '#8fee6a', '--green': '#3fb950', '--yellow': '#d29922', '--red': '#f85149', '--blue': '#58a6ff' },
  light: { '--bg': '#f6f8fa', '--bg-elev': '#ffffff', '--bg-elev-2': '#eaeef2', '--border': '#d0d7de', '--text': '#1f2328', '--text-muted': '#59636e', '--accent': '#159c53', '--accent-hover': '#8fee6a', '--green': '#1a7f37', '--yellow': '#9a6700', '--red': '#cf222e', '--blue': '#0969da' },
};
const DEFAULT_PRESET_PALETTE = ['#c51111','#132ed1','#117f2d','#ed54ba','#ef7d0d','#f5f557','#3f474e','#d6e0f0','#6b2fbb','#71491e','#38fedc','#50ef39','#8b3eea','#e87e7e','#e8e8e8','#3b82f6','#10b981','#6366f1'];
const DEFAULT_PRESET_COLOR = '#6366f1';

function normalizeHex(v, fallback) {
  const s2 = (v || '').trim();
  const m = /^#?([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.exec(s2);
  if (!m) return fallback || null;
  let hex = m[1];
  if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
  return '#' + hex.toLowerCase();
}
function getThemeColors(themeName) {
  const overrides = (state.themeColors && state.themeColors[themeName]) || {};
  return { ...BUILTIN_THEME_COLORS[themeName], ...overrides };
}
function getPresetPalette() {
  const p = state.presetPalette;
  return (Array.isArray(p) && p.length) ? p : DEFAULT_PRESET_PALETTE;
}
function getPresetColor(presetId) {
  const c = (CHARACTERS.find(ch => ch[0] === presetId) || [])[2];
  return normalizeHex(c, null) || '#8b949e';
}
function hexToRgba(hex, alpha) {
  const h = normalizeHex(hex, '#8b949e').slice(1);
  const r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function presetColorStyle(presetId, tintAlpha) {
  const c = getPresetColor(presetId);
  return `--preset-color: ${c}; --preset-tint: ${hexToRgba(c, tintAlpha == null ? 0.12 : tintAlpha)};`;
}
function getDefaultPresetColor() { return normalizeHex(state.defaultPresetColor, DEFAULT_PRESET_COLOR); }
function applyThemeColors(themeName) {
  const name = themeName || state.theme || 'dark';
  const colors = getThemeColors(name);
  const root = document.documentElement;
  THEME_COLOR_FIELDS.forEach(f => {
    const val = colors[f.var];
    if (val && val !== BUILTIN_THEME_COLORS[name][f.var]) root.style.setProperty(f.var, val);
    else root.style.removeProperty(f.var);
  });
}


function applyTheme() {
  const isLight = state.theme === 'light';
  document.documentElement.dataset.theme = isLight ? 'light' : 'dark';
  document.documentElement.style.colorScheme = isLight ? 'light' : 'dark';
  const button = document.getElementById('themeToggleBtn');
  applyThemeColors(isLight ? 'light' : 'dark');
  if (button) { button.textContent = isLight ? '🌙 Dark' : '☀ Light'; const targetMode = isLight ? 'dark' : 'light'; button.setAttribute('aria-label', `Switch to ${targetMode} mode`); button.title = `witch to ${targetMode} mode`; button.setAttribute('aria-pressed', String(isLight)); }
}
function toggleTheme() { state.theme = state.theme === 'light' ? 'dark' : 'light'; applyTheme(); saveState(); }


let ttsAudioEl = null;
let ttsObjectUrl = null;
let ttsSpeakToken = 0;

function stopTtsPlayback() {
  ttsSpeakToken++;
  stopTtsProgress();
  try { if (window.speechSynthesis) window.speechSynthesis.cancel(); } catch (_) {}
  if (ttsAudioEl) {
    try { ttsAudioEl.pause(); } catch (_) {}
    ttsAudioEl.removeAttribute('src');
    try { ttsAudioEl.load(); } catch (_) {}
    ttsAudioEl = null;
  }
  if (ttsObjectUrl) {
    try { URL.revokeObjectURL(ttsObjectUrl); } catch (_) {}
    ttsObjectUrl = null;
  }
  document.querySelectorAll('.msg-speak-btn.speaking').forEach(btn => {
    btn.classList.remove('speaking');
    btn.disabled = false;
    btn.textContent = '▶ Speak';
    btn.title = 'Read aloud (TTS)';
  });
  
  const ttsTestBtn = document.getElementById('ttsTestBtn');
  if (ttsTestBtn && ttsTestBtn.classList.contains('speaking')) {
    ttsTestBtn.classList.remove('speaking');
    ttsTestBtn.disabled = false;
    ttsTestBtn.textContent = '▶ Test TTS';
    ttsTestBtn.title = 'Test TTS reading';
  }
}

let ttsProgressInterval = null;
function getTtsProgressBars() {
  
  const bars = [];
  const ids = ['ttsProgressBar', 'bigChatTtsProgress', 'chatTtsProgress'];
  for (const id of ids) {
    const el = document.getElementById(id);
    if (el) bars.push(el);
  }
  return bars;
}
function startTtsProgress() {
  stopTtsProgress();
  const bars = getTtsProgressBars();
  if (!bars.length) return;
  for (const bar of bars) {
    bar.style.display = '';
    const fill = bar.firstElementChild;
    if (fill) { fill.classList.add('pulse'); fill.style.width = '0%'; }
  }
  
  ttsProgressInterval = setInterval(() => {
    if (ttsAudioEl && ttsAudioEl.duration && isFinite(ttsAudioEl.duration) && ttsAudioEl.duration > 0) {
      for (const bar of bars) {
        const fill = bar.firstElementChild;
        if (fill) { fill.classList.remove('pulse'); fill.style.width = Math.min(100, (ttsAudioEl.currentTime / ttsAudioEl.duration) * 100) + '%'; }
      }
    }
  }, 200);
}
function stopTtsProgress() {
  if (ttsProgressInterval) { clearInterval(ttsProgressInterval); ttsProgressInterval = null; }
  for (const bar of getTtsProgressBars()) {
    bar.style.display = 'none';
    const fill = bar.firstElementChild;
    if (fill) { fill.classList.remove('pulse'); fill.style.width = '0%'; }
  }
}

function textForSpeech(raw) {
  let t = String(raw == null ? '' : raw);
  t = stripReasoningText(t);
  
  t = t.replace(/```[\s\S]*?```/g, ' ');
  t = t.replace(/`([^`]*)`/g, '$1');
  t = t.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');
  t = t.replace(/[#>*_~|]/g, ' ');
  t = t.replace(/\s+/g, ' ').trim();
  return t;
}

function markSpeakBtn(btn, mode) {
  if (!btn) return;
  if (mode === 'loading') {
    btn.disabled = true;
    btn.classList.add('speaking');
    btn.textContent = '…';
    btn.title = 'Generating speech…';
  } else if (mode === 'playing') {
    btn.disabled = false;
    btn.classList.add('speaking');
    btn.textContent = '■ Stop';
    btn.title = 'Stop playback';
  } else {
    btn.disabled = false;
    btn.classList.remove('speaking');
    if (btn.id === 'ttsTestBtn') {
      btn.textContent = '▶ Test TTS';
      btn.title = 'Test TTS reading';
    } else {
      btn.textContent = '▶ Speak';
      btn.title = 'Read aloud (TTS)';
    }
  }
}

function speakWithBrowser(text, voiceName, btn, token) {
  if (!window.speechSynthesis || typeof SpeechSynthesisUtterance === 'undefined') {
    showToast('Browser TTS is not available in this environment', 'error');
    markSpeakBtn(btn, 'idle');
    return;
  }
  const u = new SpeechSynthesisUtterance(text);
  const voices = window.speechSynthesis.getVoices() || [];
  if (voiceName) {
    const hit = voices.find(v => v.name === voiceName || v.voiceURI === voiceName);
    if (hit) u.voice = hit;
  }
  u.volume = getDefaultTtsVolume();
  u.rate = getDefaultTtsSpeed();
  u.onstart = () => { if (token === ttsSpeakToken) startTtsProgress(); };
  u.onend = () => { if (token === ttsSpeakToken) { markSpeakBtn(btn, 'idle'); stopTtsProgress(); } };
  u.onerror = () => { if (token === ttsSpeakToken) { markSpeakBtn(btn, 'idle'); showToast('Browser TTS failed', 'error'); stopTtsProgress(); } };
  markSpeakBtn(btn, 'playing');
  window.speechSynthesis.speak(u);
}

async function speakWithOpenRouter(text, model, voice, format, btn, token) {
  const settings = state.apiSettings;
  if (!settings.apiKey) {
    showToast('Set your OpenRouter API key in Settings to use cloud TTS', 'error');
    markSpeakBtn(btn, 'idle');
    return;
  }
  
  
  
  format = (format || 'mp3').trim().toLowerCase();
  if (format !== 'mp3') format = 'mp3';
  const base = (settings.apiUrl || '').replace(/\/chat\/completions\/?$/, '') || 'https://openrouter.ai/api/v1';
  const body = {
    model,
    input: text,
    response_format: format || 'mp3',
  };
  
  
  const effectiveVoice = voice || (() => {
    const cat = getCatalogModel(model);
    const voices = cat && Array.isArray(cat.voices) ? cat.voices : [];
    return voices[0] || '';
  })();
  if (effectiveVoice) body.voice = effectiveVoice;
  markSpeakBtn(btn, 'loading');
  try {
    const resp = await fetch(base + '/audio/speech', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + settings.apiKey,
        'Content-Type': 'application/json',
        'X-Title': 'Clod Code TTS',
      },
      body: JSON.stringify(body),
    });
    if (token !== ttsSpeakToken) return;
    if (!resp.ok) {
      let detail = 'HTTP ' + resp.status;
      try {
        const errBody = await resp.json();
        detail = (errBody.error && (errBody.error.message || errBody.error)) || errBody.message || detail;
      } catch (_) {
        try { detail = (await resp.text()) || detail; } catch (__) {}
      }
      throw new Error(typeof detail === 'string' ? detail : JSON.stringify(detail));
    }
    const buf = await resp.arrayBuffer();
    if (token !== ttsSpeakToken) return;
    const mime = 'audio/mpeg';
    if (ttsObjectUrl) { try { URL.revokeObjectURL(ttsObjectUrl); } catch (_) {} }
    ttsObjectUrl = URL.createObjectURL(new Blob([buf], { type: mime }));
    ttsAudioEl = new Audio(ttsObjectUrl);
    ttsAudioEl.volume = getDefaultTtsVolume();
    ttsAudioEl.playbackRate = getDefaultTtsSpeed();
    ttsAudioEl.onplay = () => { if (token === ttsSpeakToken) startTtsProgress(); };
    ttsAudioEl.onended = () => { if (token === ttsSpeakToken) { markSpeakBtn(btn, 'idle'); stopTtsProgress(); } };
    ttsAudioEl.onerror = () => { if (token === ttsSpeakToken) { markSpeakBtn(btn, 'idle'); showToast('Audio playback failed', 'error'); stopTtsProgress(); } };
    markSpeakBtn(btn, 'playing');
    await ttsAudioEl.play();
  } catch (e) {
    if (token === ttsSpeakToken) {
      markSpeakBtn(btn, 'idle');
      stopTtsProgress();
      showToast('TTS failed: ' + (e && e.message ? e.message : e), 'error');
    }
  }
}

async function speakMessageText(rawText, btn) {
  const text = textForSpeech(rawText);
  if (!text) { showToast('Nothing to speak', 'error'); return; }
  
  if (btn && btn.classList.contains('speaking')) { stopTtsPlayback(); return; }
  stopTtsPlayback();
  const token = ttsSpeakToken;
  const model = getDefaultTtsModel();
 const voice = getDefaultTtsVoice();
  const format = getDefaultTtsFormat();
  
  const clipped = text.length > 4000 ? text.slice(0, 4000) + '…' : text;
  if (!model) speakWithBrowser(clipped, voice, btn, token);
  else await speakWithOpenRouter(clipped, model, voice, format, btn, token);
}

function getBrowserTtsVoices() {
  try { return (window.speechSynthesis && window.speechSynthesis.getVoices()) || []; }
  catch (_) { return []; }
}

let ttsModelPickerOpen = false;
let speechCatalogFetchedAt = 0;
function getTtsDraftModel() {
  const manual = document.getElementById('defaultTtsModelManualInput');
  const select = document.getElementById('defaultTtsModelInput');
  return ((manual && manual.value.trim()) || (select && select.value) || '').trim();
}
function renderTtsModelPickerOptions() {
  const list = document.getElementById('ttsModelPickerList');
  if (!list) return;
  const catalog = getTtsCatalogModels();
  const q = ((document.getElementById('ttsModelPickerSearch') || {}).value || '').trim().toLowerCase();
  if (!catalog.length) {
    list.innerHTML = '<div class="mpk-empty">No speech models loaded yet. Click <strong>⟳ Refresh model list</strong> to fetch OpenRouter models, or type a custom slug below.</div>';
    return;
  }
  const matches = catalog.filter(m => !q
    || (m.id || '').toLowerCase().includes(q)
    || (m.name || '').toLowerCase().includes(q)).slice(0, 300);
  if (!matches.length) {
    list.innerHTML = `<div class="mpk-empty">No speech models match “${escapeHtml(q)}”.</div>`;
    return;
  }
  const selected = getTtsDraftModel().toLowerCase();
  list.innerHTML = matches.map(m => {
    const id = (m.id || '').trim();
    const chosen = id.toLowerCase() === selected;
    const name = (m.name && m.name !== id) ? `<span>${escapeHtml(m.name)}</span>` : '';
    const ctx = m.ctx ? `${Number(m.ctx).toLocaleString('en-US')} ctx` : 'speech';
    const modalities = (m.outMod || []).filter(Boolean).join(', ');
    return `<div class="mpk-item ${chosen ? 'added' : ''}" data-id="${escapeHtml(id)}" title="${chosen ? 'Selected TTS model' : 'Click to use this TTS model'}">
      ${name}<span class="mpk-id">${escapeHtml(id)}</span><span class="mpk-ctx">${chosen ? '✓ selected' : escapeHtml(modalities || ctx)}</span>
    </div>`;
  }).join('');
  list.querySelectorAll('.mpk-item').forEach(item => {
    item.onclick = () => setTtsDraftModel(item.dataset.id);
  });
}
let ttsVoicePickerOpen = false;
function getTtsDraftVoice() {
  const select = document.getElementById('defaultTtsVoiceInput');
  return (select && select.value || '').trim();
}
function getTtsVoiceOptions() {
  const model = getTtsDraftModel();
  if (!model) {
    return getBrowserTtsVoices().map(v => String(v.name || v.voiceURI || '').trim()).filter(Boolean);
  }
  const cat = getCatalogModel(model);
  return cat && Array.isArray(cat.voices)
    ? Array.from(new Set(cat.voices.map(v => String(v || '').trim()).filter(Boolean)))
    : [];
}
function renderTtsVoicePickerOptions() {
  const list = document.getElementById('ttsVoicePickerList');
  if (!list) return;
  const voices = getTtsVoiceOptions();
  const q = ((document.getElementById('ttsVoicePickerSearch') || {}).value || '').trim().toLowerCase();
  if (!voices.length) {
    list.innerHTML = '<div class="mpk-empty">No voices are reported for the current model. Type a voice id below if the provider documents one.</div>';
    return;
  }
  const matches = voices.filter(v => !q || v.toLowerCase().includes(q)).slice(0, 300);
  if (!matches.length) {
    list.innerHTML = `<div class="mpk-empty">No voices match “${escapeHtml(q)}”.</div>`;
    return;
  }
  const selected = getTtsDraftVoice().toLowerCase();
  list.innerHTML = matches.map(voice => {
    const chosen = voice.toLowerCase() === selected;
    return `<div class="mpk-item ${chosen ? 'added' : ''}" data-id="${escapeHtml(voice)}" title="${chosen ? 'Selected voice' : 'Click to use this voice'}">
      <span class="mpk-id">${escapeHtml(voice)}</span><span class="mpk-ctx">${chosen ? '✓ selected' : 'voice'}</span>
    </div>`;
  }).join('');
  list.querySelectorAll('.mpk-item').forEach(item => {
    item.onclick = () => setTtsDraftVoice(item.dataset.id);
  });
}
function setTtsDraftVoice(id) {
  const voice = (id || '').trim();
  const select = document.getElementById('defaultTtsVoiceInput');
  if (!select) return;
  if (voice && !Array.from(select.options).some(o => o.value === voice)) {
    select.add(new Option(voice, voice));
  }
  select.value = voice;
  if (typeof select.onchange === 'function') select.onchange();
  renderTtsVoicePickerOptions();
  toggleTtsVoicePicker(false);
}
function toggleTtsVoicePicker(force) {
  const box = document.getElementById('ttsVoicePicker');
  if (!box) return;
  ttsVoicePickerOpen = force != null ? force : !ttsVoicePickerOpen;
  box.classList.toggle('open', ttsVoicePickerOpen);
  if (ttsVoicePickerOpen) {
    renderTtsVoicePickerOptions();
    const search = document.getElementById('ttsVoicePickerSearch');
    if (search) { search.focus(); search.select(); }
  }
}
function initTtsVoicePicker() {
  const openBtn = document.getElementById('openTtsVoicePickerBtn');
  if (openBtn) openBtn.onclick = () => toggleTtsVoicePicker(true);
  const search = document.getElementById('ttsVoicePickerSearch');
  if (search) search.oninput = () => renderTtsVoicePickerOptions();
  const closeBtn = document.getElementById('ttsVoicePickerCloseBtn');
  if (closeBtn) closeBtn.onclick = () => toggleTtsVoicePicker(false);
  const manual = document.getElementById('ttsVoicePickerManual');
  const manualAdd = document.getElementById('ttsVoicePickerManualAdd');
  const useManual = () => {
    if (manual && manual.value.trim()) setTtsDraftVoice(manual.value.trim());
  };
  if (manualAdd) manualAdd.onclick = useManual;
  if (manual) manual.onkeydown = (e) => { if (e.key === 'Enter') { e.preventDefault(); useManual(); } };
}
function setTtsDraftModel(id) {
  const model = (id || '').trim();
  const modelSel = document.getElementById('defaultTtsModelInput');
  const manual = document.getElementById('defaultTtsModelManualInput');
  const known = getTtsCatalogModels().some(m => (m.id || '').trim().toLowerCase() === model.toLowerCase());
  if (!model) {
    if (modelSel) modelSel.value = '';
    if (manual) manual.value = '';
  } else if (known && modelSel) {
    modelSel.value = model;
    if (manual) manual.value = '';
  } else {
    if (modelSel) modelSel.value = '';
    if (manual) manual.value = model;
  }
  if (modelSel && typeof modelSel.onchange === 'function') modelSel.onchange();
  else if (manual && typeof manual.oninput === 'function') manual.oninput();
  renderTtsModelPickerOptions();
  renderTtsVoicePickerOptions();
  toggleTtsModelPicker(false);
}
function toggleTtsModelPicker(force) {
  const box = document.getElementById('ttsModelPicker');
  if (!box) return;
  ttsModelPickerOpen = force != null ? force : !ttsModelPickerOpen;
  box.classList.toggle('open', ttsModelPickerOpen);
  if (ttsModelPickerOpen) {
    renderTtsModelPickerOptions();
    const search = document.getElementById('ttsModelPickerSearch');
    if (search) { search.focus(); search.select(); }
    
    
    if (Date.now() - speechCatalogFetchedAt > 5 * 60 * 1000) fetchSpeechModelCatalog(true);
  }
}
function initTtsModelPicker() {
  const openBtn = document.getElementById('openTtsModelPickerBtn');
  if (openBtn) openBtn.onclick = () => toggleTtsModelPicker(true);
  const search = document.getElementById('ttsModelPickerSearch');
  if (search) search.oninput = () => renderTtsModelPickerOptions();
  const closeBtn = document.getElementById('ttsModelPickerCloseBtn');
  if (closeBtn) closeBtn.onclick = () => toggleTtsModelPicker(false);
  const refreshBtn = document.getElementById('refreshTtsModelPickerBtn');
  if (refreshBtn) refreshBtn.onclick = () => fetchSpeechModelCatalog(false);
  const manual = document.getElementById('ttsModelPickerManual');
  const manualAdd = document.getElementById('ttsModelPickerManualAdd');
  const useManual = () => {
    if (manual && manual.value.trim()) setTtsDraftModel(manual.value.trim());
  };
  if (manualAdd) manualAdd.onclick = useManual;
  if (manual) manual.onkeydown = (e) => { if (e.key === 'Enter') { e.preventDefault(); useManual(); } };
}

function populateTtsSettingsControls() {
  const modelSel = document.getElementById('defaultTtsModelInput');
  const voiceSel = document.getElementById('defaultTtsVoiceInput');
  const formatSel = document.getElementById('defaultTtsFormatInput');
  const manual = document.getElementById('defaultTtsModelManualInput');
  const hint = document.getElementById('defaultTtsHint');
  if (!modelSel || !voiceSel) return;
  
  
  if (Date.now() - speechCatalogFetchedAt > 5 * 60 * 1000) fetchSpeechModelCatalog(true);

  const savedModel = (state.apiSettings.defaultTtsModel || '').trim();
  const savedVoice = (state.apiSettings.defaultTtsVoice || '').trim();
  const savedFormat = getDefaultTtsFormat();

  const ttsModels = getTtsCatalogModels();
  const ttsIds = new Set(ttsModels.map(m => m.id));
  let html = '<option value="">Browser (Web Speech) — free, offline</option>';
  if (ttsModels.length) {
    html += ttsModels.map(m => {
      const label = (m.name && m.name !== m.id) ? (m.name + ' — ' + m.id) : m.id;
      return '<option value="' + escapeHtml(m.id) + '">' + escapeHtml(label) + '</option>';
    }).join('');
  }
  if (savedModel && !ttsIds.has(savedModel)) {
    html += '<option value="' + escapeHtml(savedModel) + '">' + escapeHtml(savedModel) + ' (saved)</option>';
  }
  modelSel.innerHTML = html;

  
  if (savedModel && ttsIds.has(savedModel)) {
    modelSel.value = savedModel;
    if (manual) manual.value = '';
  } else if (savedModel) {
    modelSel.value = '';
    if (manual) manual.value = savedModel;
  } else {
    modelSel.value = '';
    if (manual) manual.value = '';
  }
  if (formatSel) formatSel.value = savedFormat;

  const fillVoices = () => {
    const effectiveModel = ((manual && manual.value.trim()) || modelSel.value || '').trim();
    const prev = voiceSel.value || savedVoice;
    let selectedVoice = prev;
    let options = '<option value="">Default</option>';
    if (!effectiveModel) {
      const voices = getBrowserTtsVoices();
      options += voices.map(v => {
        const name = v.name || v.voiceURI;
        const lab = name + (v.lang ? ' (' + v.lang + ')' : '');
        return '<option value="' + escapeHtml(name) + '">' + escapeHtml(lab) + '</option>';
      }).join('');
    } else {
      const cat = getCatalogModel(effectiveModel);
      const voices = (cat && Array.isArray(cat.voices)) ? cat.voices : [];
      options += voices.map(v => '<option value="' + escapeHtml(v) + '">' + escapeHtml(v) + '</option>').join('');
      
      
      if (voices.length) {
        selectedVoice = voices.includes(prev) ? prev : voices[0];
      } else if (prev && (state.apiSettings.defaultTtsVoiceModel || '') === effectiveModel) {
        
        
        selectedVoice = prev;
      } else {
        selectedVoice = '';
      }
      if (prev && voices.length && !voices.includes(prev)) {
        options += '<option value="' + escapeHtml(prev) + '">' + escapeHtml(prev) + ' (saved)</option>';
      } else if (prev && !voices.length) {
        options += '<option value="' + escapeHtml(prev) + '">' + escapeHtml(prev) + '</option>';
      }
    }
    voiceSel.innerHTML = options;
    if (selectedVoice) voiceSel.value = selectedVoice;
    if (ttsVoicePickerOpen) renderTtsVoicePickerOptions();
    if (hint) {
      if (!effectiveModel) {
        hint.textContent = 'Speak buttons will use your system/browser voices (no API cost).';
      } else {
        const cat = getCatalogModel(effectiveModel);
        const n = cat && cat.voices ? cat.voices.length : 0;
        hint.textContent = n
          ? (effectiveModel + ' · ' + n + ' voice' + (n === 1 ? '' : 's') + ' reported. Uses OpenRouter /api/v1/audio/speech.')
          : (effectiveModel + ' · no voice list in catalog (you can still type a voice id if the provider needs one). Uses OpenRouter /api/v1/audio/speech.');
      }
    }
  };

  fillVoices();
  modelSel.onchange = fillVoices;
  voiceSel.onchange = () => { if (ttsVoicePickerOpen) renderTtsVoicePickerOptions(); };
  if (manual) {
    manual.oninput = () => { fillVoices(); if (ttsModelPickerOpen) renderTtsModelPickerOptions(); };
    manual.onchange = () => { fillVoices(); if (ttsModelPickerOpen) renderTtsModelPickerOptions(); };
  }
  const refreshBtn = document.getElementById('refreshTtsModelsBtn');
  if (refreshBtn) {
    refreshBtn.onclick = async () => {
      refreshBtn.disabled = true;
      try { await fetchSpeechModelCatalog(false); populateTtsSettingsControls(); }
      finally { refreshBtn.disabled = false; }
    };
  }

  
  const volSlider = document.getElementById('defaultTtsVolume');
  const volLabel = document.getElementById('ttsVolumeLabel');
  const spdSlider = document.getElementById('defaultTtsSpeed');
  const spdLabel = document.getElementById('ttsSpeedLabel');
  if (volSlider) {
    volSlider.value = String(Math.round(getDefaultTtsVolume() * 100));
    if (volLabel) volLabel.textContent = volSlider.value + '%';
    volSlider.oninput = () => {
      if (volLabel) volLabel.textContent = volSlider.value + '%';
    };
  }
  if (spdSlider) {
    spdSlider.value = String(Math.round(getDefaultTtsSpeed() * 100));
    if (spdLabel) { spdLabel.textContent = (parseFloat(spdSlider.value) / 100).toFixed(2).replace(/0+$/, '').replace(/\.$/, '') + '×'; }
    spdSlider.oninput = () => {
      if (spdLabel) {
        const v = parseFloat(spdSlider.value) / 100;
        spdLabel.textContent = v.toFixed(2).replace(/0+$/, '').replace(/\.$/, '') + '×';
      }
    };
  }
  
  if (window.speechSynthesis) {
    try { window.speechSynthesis.onvoiceschanged = fillVoices; } catch (_) {}
  }
  if (ttsModelPickerOpen) renderTtsModelPickerOptions();
  if (ttsVoicePickerOpen) renderTtsVoicePickerOptions();
}


function switchSettingsTab(tabName) {
  if (typeof tabName !== 'string') tabName = (typeof tabName === 'object' && tabName && typeof tabName.dataset?.settingsTab === 'string')
    ? tabName.dataset.settingsTab : window._currentSettingsTab || 'api';
  if (tabName === 'fallback' || tabName === 'providers') tabName = 'models'; 
  if (!document.getElementById('settingsTab' + tabName.charAt(0).toUpperCase() + tabName.slice(1))) tabName = 'api';
  window._currentSettingsTab = tabName;
  document.querySelectorAll('.settings-tab').forEach(t => t.classList.toggle('active', t.dataset.settingsTab === tabName));
  document.querySelectorAll('.settings-tab-view').forEach(v => {
    v.classList.toggle('active', v.id === `settingsTab${tabName.charAt(0).toUpperCase() + tabName.slice(1)}`);
  });
  // Which engine this app would run can change while the dialog is shut (a
  // folder gets mounted, a download finishes), so re-read it when the section
  // is shown rather than only once at startup. The lookup is cached, so this is
  // not a fresh engine probe every time the tab is clicked.
  if (tabName === 'agent') { try { refreshGodotVersionLine(); } catch {} }
}

