  document.getElementById('skillsEnabledInput').checked = state.apiSettings.skillsEnabled !== false;
  document.getElementById('webSearchEnabledInput').checked = state.apiSettings.webSearchEnabled !== false;
  const _agentBrowserInput = document.getElementById('agentBrowserEnabledInput');
  if (_agentBrowserInput) _agentBrowserInput.checked = state.apiSettings.agentBrowserEnabled !== false;
  const _browserEngineInput = document.getElementById('browserSearchEngineInput');
  if (_browserEngineInput) _browserEngineInput.value = String(state.apiSettings.browserSearchEngine || 'duckduckgo');
  document.getElementById('webSearchEndpointInput').value = state.apiSettings.webSearchEndpoint || '';
  document.getElementById('webSearchApiKeyInput').value = state.apiSettings.webSearchApiKey || '';
