  const _defSubs = document.getElementById('bigChatDefaultSubagentsEnabledInput');
  if (_defSubs) _defSubs.checked = state.apiSettings.bigChatDefaultSubagentsEnabled !== false;
  const _defPresets = document.getElementById('bigChatDefaultPresetsEnabledInput');
  if (_defPresets) _defPresets.checked = state.apiSettings.bigChatDefaultPresetsEnabled !== false;
  const _dimDefLists = () => {
    const _dim = (listId, on) => {
      const list = document.getElementById(listId);
      if (list) list.style.opacity = on ? '' : '0.4';
    };
    _dim('agentTToolList', _defTools ? _defTools.checked : true);
    _dim('bigChatDefaultSubagentsList', _defSubs ? _defSubs.checked : true);
    _dim('bigChatDefaultPresetsList', _defPresets ? _defPresets.checked : true);
  };
  if (_defTools) _defTools.onchange = _dimDefLists;
  if (_defSubs) _defSubs.onchange = _dimDefLists;
  if (_defPresets) _defPresets.onchange = _dimDefLists;
  _dimDefLists();
  document.getElementById('enableFallbackInput').checked = state.apiSettings.enableFallback;
  document.getElementById('enableProvidersInput').checked = !!state.apiSettings.enableProviders;
  document.getElementById('providerAllowFallbacksInput').checked = state.apiSettings.providerAllowFallbacks !== false;
  providersDraft = (state.apiSettings.providers || defaultProviders()).map(p => ({ name: p.name || p.slug || '', slug: p.slug || '', enabled: p.enabled !== false }));
  const modelProvidersToggle = document.getElementById('enableModelProvidersInput');
  modelProvidersToggle.checked = state.apiSettings.enableModelProviders !== false;
  modelProvidersToggle.onchange = () => { if (openModelInfo.size) renderFallbackModelsEditor(); };
  modelProvidersDraft = (state.apiSettings.modelProviders || []).map(r => ({ model: r.model || '', providers: (r.providers || []).slice(), allowFallbacks: r.allowFallbacks === true, enabled: r.enabled !== false, smartSkip: r.smartSkip || 'default' }));
  initProviderPicker();
