function updateArenaRankStatus() {
  const el = document.getElementById('arenaRankStatus');
  if (!el) return;
  if (isFetchingArena) { el.innerHTML = 'Arena.ai ranks: loading live text/overall board…'; return; }
  const cat = state.arenaCatalog;
  if (!cat) {
    el.innerHTML = 'Arena.ai ranks: not loaded yet. <a href="' + ARENA_PAGE_URL + '" target="_blank" rel="noopener noreferrer">lmarena.ai/leaderboard/text</a>';
    return;
  }
  if (cat.error && !(cat.models || []).length) {
    el.innerHTML = 'Arena.ai ranks: failed (' + escapeHtml(cat.error) + ').';
    return;
  }
  const n = (cat.models || []).length;
  el.innerHTML = 'Arena.ai text/overall: <strong style="color:var(--text)">' + n + ' models</strong>' +
    (cat.publishDate ? ' · board date ' + escapeHtml(cat.publishDate) : '') +
    (cat.fetchedAt ? ' · fetched ' + escapeHtml(arenaAgeLabel(cat.fetchedAt)) : '') +
    ' · <a href="' + ARENA_PAGE_URL + '" target="_blank" rel="noopener noreferrer">open</a>';
}
async function fetchArenaLeaderboard(force) {
  if (isFetchingArena) return state.arenaCatalog;
  const cached = state.arenaCatalog;
  if (!force && cached && cached.fetchedAt && (Date.now() - Date.parse(cached.fetchedAt) < ARENA_CACHE_MS) && (cached.models || []).length) {
    updateArenaRankStatus();
    return cached;
  }
  isFetchingArena = true;
  updateArenaRankStatus();
  const btn = document.getElementById('refreshArenaRanksBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Loading…'; }
  if (document.getElementById('fallbackModelsList')) {
    try { renderFallbackModelsEditor(); } catch (_) {}
  }
  try {
    const headers = { 'Accept': 'application/json' };
    const pageSize = 100;
    let offset = 0;
    const overall = [];
    let publishDate = '';
    
    for (let guard = 0; guard < 30; guard++) {
      const url = ARENA_TEXT_URL + '&offset=' + offset + '&length=' + pageSize;
      const resp = await fetch(url, { headers });
      if (!resp.ok) throw new Error('HTTP ' + resp.status + ' from Arena dataset');
      const body = await resp.json();
      const rows = body.rows || [];
      if (!rows.length) break;
      let pageOverall = 0;
      for (const item of rows) {
        const r = item.row || item;
        if (!r) continue;
        if ((r.category || '') !== 'overall') continue;
        pageOverall++;
        const name = (r.model_name || '').trim();
        if (!name) continue;
        const rank = Number(r.rank);
        const rating = Number(r.rating);
        if (!Number.isFinite(rank)) continue;
         overall.push({
          name: name,
          rank: rank,
          rating: Number.isFinite(rating) ? rating :  null,
          votes: Number.isFinite(Number(r.vote_count)) ? Number(r.vote_count) : null,
          organization: (r.organization || '').trim(),
        });
        if (r.leaderboard_publish_date) publishDate = String(r.leaderboard_publish_date);
      }
      offset += rows.length;
      if (pageOverall === 0) {
        if (overall.length) break;
      }
      if (body.num_rows_total != null && offset >= body.num_rows_total) break;
      if (rows.length < pageSize) break;
    }
    if (!overall.length) throw new Error('No overall ranks returned');
    const byName = new Map();
    for (const m of overall) {
      const k = m.name.toLowerCase();      const prev = byName.get(k);
      if (!prev || m.rank < prev.rank) byName.set(k, m);
    }
    const models = Array.from(byName.values()).sort((a, b) => a.rank - b.rank);
    state.arenaCatalog = {
      fetchedAt: new Date().toISOString(),
      publishDate: publishDate || null,
      source: 'huggingface:' + ARENA_HF_DATASET + '/text@latest(overall)',
      models: models,
      error: null,
    };
    saveState();
    updateArenaRankStatus();
    if (document.getElementById('fallbackModelsList')) renderFallbackModelsEditor();
    if (force) showToast('Loaded ' + models.length + ' Arena.ai text ranks' + (publishDate ? ' (' + publishDate + ')' : ''), 'success');
    return state.arenaCatalog;
  } catch (e) {
    const msg = (e && e.message) ? e.message : String(e);
    if (!state.arenaCatalog || !(state.arenaCatalog.models || []).length) {
      state.arenaCatalog = { fetchedAt: new Date().toISOString(), publishDate: null, source: null, models: [], error: msg };
    } else {
      state.arenaCatalog.error = msg;
    }
    updateArenaRankStatus();
    if (document.getElementById('fallbackModelsList')) renderFallbackModelsEditor();
    if (force) showToast('Arena ranks failed: ' + msg, 'error');
    return state.arenaCatalog;
  } finally {
    isFetchingArena = false;
    const b2 = document.getElementById('refreshArenaRanksBtn');
    if (b2) { b2.disabled = false; b2.textContent = 'Refresh Arena ranks'; }
    updateArenaRankStatus();
  }
}
function formatPrice(perToken) {
  const n = Number(perToken || 0);
  if (!n) return 'free';
  const perM = n * 1e6;
  return `$${perM >= 1 ? perM.toFixed(2) : perM.toFixed(3)}/M`;
}
function capBadges(m) {
  const b = [];
  const inMod = m.inMod || [];
  const outMod = m.outMod || [];
  const params = m.params || [];
  if (inMod.includes('image')) b.push({ t: '👁 Vision', c: 'var(--blue)' });
  if (inMod.includes('audio')) b.push({ t: '🎤 Audio', c: 'var(--blue)' });
  if (outMod.includes('speech')) b.push({ t: '🗣 TTS', c: 'var(--accent)' });
  if (inMod.includes('video')) b.push({ t: '🎬 Video', c: 'var(--blue)' });
  if (inMod.includes('file')) b.push({ t: '📎 Files', c: 'var(--blue)' });
  if (params.includes('tools')) b.push({ t: '🛠 Tools', c: 'var(--green)' });
  if (params.includes('reasoning') || params.includes('include_reasoning')) b.push({ t: '🧠 Reasoning', c: 'var(--yellow)' });
  if (params.includes('response_format') || params.includes('structured_outputs')) b.push({ t: '{} JSON', c: 'var(--text-muted)' });
  if (m.moderated) b.push({ t: '🛡 Moderated', c: 'var(--text-muted)' });
  return b;
}

async function loadModelEndpoints(slug, force) {
  const id = (slug || '').trim();
  const cached = id ? modelEndpointCache[id] : null;
   
  
  if (!id || (cached && (!force || cached.loading))) return;
  
  delete modelEndpointCache[id];
  modelEndpointCache[id] = { loading: true, providers: [], directApis: {} };
  try {
    const base = (state.apiSettings.apiUrl || '').replace(/\/chat\/completions\/?$/, '') || 'https://openrouter.ai/api/v1';
    const headers = {};
    if (state.apiSettings.apiKey) headers['Authorization'] = `Bearer ${state.apiSettings.apiKey}`;
    const resp = await fetch(`${base}/models/${id}/endpoints`, { headers });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const body = await resp.json();
    const eps = (body.data && body.data.endpoints)|| [];
    modelEndpointCache[id] = {
      loading: false,
      providers: eps.map(e => ({
        tag: (e.tag || '').trim(),
        name: (e.provider_name || e.tag || '').trim(),
        ctx: Number(e.context_length || 0) || 0,
        maxOut: Number(e.max_completion_tokens || 0) || 0,
        quant: e.quantization || '',
        pricing: e.pricing || null,
        modelId: (e.model_id || '').trim(),
      })),
      directApis: modelEndpointCache[id].directApis || {},
    };
  } catch (e) {
    modelEndpointCache[id] = { loading: false, providers: [], error: e.message, directApis: modelEndpointCache[id].directApis || {} };
  }
  
  
  
  await checkDirectApiProviders(id, !!force);
  renderFallbackModelsEditor();
  renderBigChatProviderCompat();
  if (openProviderInfo.size) renderProvidersEditor();
}


function providerMatchesTag(providerSlug, tag, providerName) {
  const norm = (x) => (x || '').trim().toLowerCase().replace(/[\s_-]+/g, '');
  const p = (providerSlug || '').trim().toLowerCase();
  const t = (tag || '').trim().toLowerCase();
  if (!p || !t) return false;
  
  const tBase = t.split('/')[0];
  if (t === p || t.startsWith(p + '/')) return true;
  
  if (norm(tBase) === norm(p)) return true;
  
  
  
  if (providerName && norm(providerName) === norm(p)) return true;
  return false;
}

function modelProviderRuleForDraft(slug) {
  const id = fallbackListId(slug).toLowerCase();
  if (!id) return null;
  return (modelProvidersDraft || []).find(r => fallbackListId(r.model).toLowerCase() === id) || null;
}
function ensureModelProviderRule(slug) {
  const id = fallbackListId(slug);
  if (!id) return null;
  let rule = modelProviderRuleForDraft(id);
  if (!rule) {
    rule = { model: id, providers: [], allowFallbacks: false, enabled: true, smartSkip: 'default' };
    modelProvidersDraft.push(rule);
  } else {
    rule.enabled = true;
    if (!Array.isArray(rule.providers)) rule.providers = [];
  }
  return rule;
}
function modelProviderOverrideHtml(slug) {
  const id = (slug || '').trim();
  if (!id) return '';
  const rule = modelProviderRuleForDraft(id);
  const enabled = !!rule && rule.enabled !== false;
  const providers = rule && Array.isArray(rule.providers) ? rule.providers : [];
  const selected = new Set(providers.map(p => (p || '').trim().toLowerCase()));
  const choices = providerChoiceList();
  const options = choices
    .filter(c => !selected.has(c.slug.toLowerCase()))
    .map(c => `<option value="${escapeHtml(c.slug)}">${escapeHtml(c.name)}</option>`).join('');
  const providerRows = providers.map((slug2, pi) => {
    const choice = choices.find(c => c.slug.toLowerCase() === (slug2 || '').trim().toLowerCase());
    const name = choice ? choice.name : slug2;
    const draft = providerDraftBySlug(slug2);
    const globalOff = draft && draft.enabled === false ? ' global-off' : '';
    return `<div class="mp-provider-row${globalOff}" data-provider-idx="${pi}" draggable="true">
      <span class="mp-provider-drag-handle" title="Drag to reorder providers">⋮⋮</span>
      <span class="mp-provider-name" title="${escapeHtml(slug2)}">${escapeHtml(name)}<small>${escapeHtml(slug2)}</small></span>
      <button type="button" class="mp-provider-remove mi-mp-provider-remove" title="Remove provider">×</button>
    </div>`;
  }).join('');
  const count = providers.length;
  const globalEnabledInput = document.getElementById('enableModelProvidersInput');
  const globalEnabled = globalEnabledInput ? globalEnabledInput.checked : state.apiSettings.enableModelProviders !== false;
  const globalNote = globalEnabled ? '' : '<div class="mi-override-help">Per-model overrides are currently disabled globally in Provider routing.</div>';
  return `<div class="mi-override${enabled ? '' : ' disabled'}" data-model="${escapeHtml(id)}">
    <div class="mi-override-head">
      <label class="mi-override-label" title="Route this model only through the providers listed below">
        <input type="checkbox" class="mi-mp-enabled" ${enabled ? 'checked' : ''}>
        Override global provider routing
      </label>
      <span class="mi-override-status">${enabled ? (count ? `${count} provider${count === 1 ? '' : 's'} selected` : 'No providers selected') : 'Using global provider order'}</span>
    </div>
    ${enabled ? `<div class="mi-override-body">
      ${globalNote}
      <div class="mi-override-help">Add providers below, then drag <strong style="color:var(--text);">⋮⋮</strong> to set this model’s provider order. The global provider fallback setting does not apply unless enabled here.</div>
      <div class="mp-provider-controls">
        <select class="mp-provider-add mi-mp-provider-add" aria-label="Add provider to this model override">
          <option value="">+ Add provider…</option>
          ${options}
        </select>
      </div>
      <div class="mp-provider-list">${providerRows || '<span style="font-size:11px;color:var(--text-muted);">No providers selected — use the dropdown above.</span>'}</div>
      <div class="mp-foot">
        <label class="mp-toggle-label"><input type="checkbox" class="mi-mp-allow-fb" ${rule && rule.allowFallbacks ? 'checked' : ''}>Allow fallbacks to other providers</label>
        <label class="mp-toggle-label" title="When this model errors, skip to the next provider instead of waiting on the retry timers">Smart Provider Skip
          <select class="mi-mp-smart-skip" style="font-size:11px;">
            <option value="default" ${(!rule || !rule.smartSkip || rule.smartSkip === 'default') ? 'selected' : ''}>Use global setting</option>
            <option value="on" ${rule && rule.smartSkip === 'on' ? 'selected' : ''}>On</option>
            <option value="off" ${rule && rule.smartSkip === 'off' ? 'selected' : ''}>Off</option>
          </select>
        </label>
        <span style="font-size:11px; color:var(--text-muted);">${count ? `${count} provider${count === 1 ? '' : 's'} allowed` : 'Rule ignored until at least one provider is selected'}</span>
      </div>
    </div>` : ''}
  </div>`;
}
let draggedInlineModelProvider = null;
function bindModelProviderOverrideControls(container) {
  container.querySelectorAll('.mi-mp-enabled').forEach(cb => {
    cb.onchange = () => {
      const model = cb.closest('.mi-override').dataset.model;
      if (cb.checked) ensureModelProviderRule(model);
      else {
        const rule = modelProviderRuleForDraft(model);
        if (rule) rule.enabled = false;
      }
      renderFallbackModelsEditor();
    };
  });
  container.querySelectorAll('.mi-mp-allow-fb').forEach(cb => {
    cb.onchange = () => {
      const rule = modelProviderRuleForDraft(cb.closest('.mi-override').dataset.model);
      if (rule) rule.allowFallbacks = cb.checked;
    };
  });
  container.querySelectorAll('.mi-mp-smart-skip').forEach(sel => {
    sel.onchange = () => {
      const rule = modelProviderRuleForDraft(sel.closest('.mi-override').dataset.model);
      if (rule) rule.smartSkip = sel.value;
    };
  });
  container.querySelectorAll('.mi-mp-provider-add').forEach(sel => {
    sel.onchange = () => {
      const rule = ensureModelProviderRule(sel.closest('.mi-override').dataset.model);
      const slug = (sel.value || '').trim();
      if (!rule || !slug) return;
      if (!rule.providers.some(p => (p || '').trim().toLowerCase() === slug.toLowerCase())) rule.providers.push(slug);
      reorderModelRuleProviders(rule);
      renderFallbackModelsEditor();
    };
  });
  container.querySelectorAll('.mi-mp-provider-remove').forEach(btn => {
    btn.onclick = () => {
      const override = btn.closest('.mi-override');
      const rule = modelProviderRuleForDraft(override.dataset.model);
      const providerIdx = parseInt(btn.closest('.mp-provider-row').dataset.providerIdx);
      if (!rule || Number.isNaN(providerIdx)) return;
      rule.providers.splice(providerIdx, 1);
      renderFallbackModelsEditor();
    };
  });
  container.querySelectorAll('.mi-override .mp-provider-row').forEach(row => {
    const model = row.closest('.mi-override').dataset.model.toLowerCase();
    const providerIdx = parseInt(row.dataset.providerIdx);
    row.addEventListener('dragstart', (e) => {
      if (e.target.closest('button')) { e.preventDefault(); return; }
      draggedInlineModelProvider = { model, providerIdx };
      row.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', String(providerIdx));
    });
    row.addEventListener('dragend', () => {
      row.classList.remove('dragging');
      container.querySelectorAll('.mi-override .mp-provider-row').forEach(r => r.classList.remove('drag-over-top', 'drag-over-bottom'));
      draggedInlineModelProvider = null;
    });
    row.addEventListener('dragover', (e) => {
      e.preventDefault();
      if (!draggedInlineModelProvider || draggedInlineModelProvider.model !== model || draggedInlineModelProvider.providerIdx === providerIdx) return;
      e.dataTransfer.dropEffect = 'move';
      const rect = row.getBoundingClientRect();
      row.classList.remove('drag-over-top', 'drag-over-bottom');
      if (e.clientY < rect.top + rect.height / 2) row.classList.add('drag-over-top');
      else row.classList.add('drag-over-bottom');
    });
    row.addEventListener('dragleave', () => row.classList.remove('drag-over-top', 'drag-over-bottom'));
    row.addEventListener('drop', (e) => {
      e.preventDefault();
      row.classList.remove('drag-over-top', 'drag-over-bottom');
      if (!draggedInlineModelProvider || draggedInlineModelProvider.model !== model || draggedInlineModelProvider.providerIdx === providerIdx) return;
      const rule = modelProviderRuleForDraft(model);
      if (!rule || !Array.isArray(rule.providers)) return;
      const rect = row.getBoundingClientRect();
      let insertIdx = providerIdx;
      if (e.clientY >= rect.top + rect.height / 2) insertIdx++;
      if (draggedInlineModelProvider.providerIdx < insertIdx) insertIdx--;
      const [moved] = rule.providers.splice(draggedInlineModelProvider.providerIdx, 1);
      rule.providers.splice(insertIdx, 0, moved);
      renderFallbackModelsEditor();
    });
  });
}

function modelInfoHtml(slug) {
  const id = (slug || '').trim();
  if (!id) return '<div class="mi-empty">Enter a model slug to see its details.</div>';
  const overrideHtml = modelProviderOverrideHtml(id);
  const m = getCatalogModel(id);
  if (!m) {
    return `<div class="mi-empty">No catalog entry for <code>${escapeHtml(id)}</code>. Click <strong>+ Add model…</strong> → <strong>⟳ Refresh model list</strong> to load model details from OpenRouter.</div>${overrideHtml}`;
  }
  const badges = capBadges(m).map(b => `<span class="mi-badge" style="border-color:${b.c};color:${b.c};">${escapeHtml(b.t)}</span>`).join('');
  const arenaBlock = arenaInfoHtml(id, m.name);
  const facts = [
    ['Context', m.ctx ? `${formatNum(m.ctx)} tokens` : 'unknown'],
    ['Max output', m.maxOut ? `${formatNum(m.maxOut)} tokens` : '—'],
    ['Input', (m.inMod || []).join(', ') || 'text'],
    ['Output', (m.outMod || []).join(', ') || 'text'],
    ['Pricing', `${formatPrice(m.pricing.prompt)} in · ${formatPrice(m.pricing.completion)} out`],
    ['Tokenizer', m.tokenizer || '—'],
  ];
  
  
  if (isGoogleAiStudioFreeModel(id)) {
    facts.push(['Google AI Studio', 'free endpoint (free tier)']);
  }
  const factsHtml = facts.map(([k, v]) => `<div class="mi-fact"><span>${escapeHtml(k)}</span><strong>${escapeHtml(String(v))}</strong></div>`).join('');

  return `<div class="mi-badges">${badges || '<span class="mi-empty">No special capabilities reported.</span>'}</div>
    ${arenaBlock}
    <div class="mi-facts">${factsHtml}</div>
    ${providerCompatibilityBlock(id)}
    ${overrideHtml}
    ${m.desc ? `<div class="mi-desc">${escapeHtml(m.desc.slice(0, 400))}${m.desc.length > 400 ? '…' : ''}</div>` : ''}`;
}






function providerCompatibilityBlock(id) {
  const configured = configuredProviders();
  const ep = modelEndpointCache[id];
  let provHtml;
  if (!ep) provHtml = `<button type="button" class="small mi-load-providers" data-slug="${escapeHtml(id)}">Check my providers</button>`;
  else if (ep.loading) provHtml = `<span class="mi-empty">Checking providers…</span>`;
  else if (!configured.length) provHtml = `<span class="mi-empty">No providers configured — add some in the Provider routing section above.</span>`;
  else {
    const rows = configured.map(p => {
      
      
      const directKind = directApiKindForSlug(p.slug);
      if (directKind) {
        const res = (ep.directApis || {})[directKind];
        let cls = 'no', mark = '✕', detail = '', hitNoFree = false;
        if (!res || res.loading) detail = 'checking…';
        else if (res.error) detail = res.error === 'no account configured' ? 'no account configured' : `check failed (${res.error})`;
        else {
          
          
          if (eolDeadProviders(id).has(p.slug.trim().toLowerCase())) {
            cls = 'no'; mark = '✕';
            detail = 'end of life (API returned 410 Gone)';
          } else {
            const base = directApiModelName(directKind, id);
            
            
            
            
            const wanted = directKind === 'free' && !/:free$/i.test(base)
              ? base + ':free'
              : directKind === 'zenmux' && zenmuxWantsFree(id) && !/-free$/i.test(base)
                ? base + '-free'
                : directKind === 'orcarouter' && !/-free$/i.test(base)
                  ? (orcarouterFreeVariantFor(id) || base)
                  : directKind === 'aihubmix' && !/-free$/i.test(base)
                    ? (aihubmixFreeVariantFor(id) || base)
                    : directKind === 'unorouter'
                    ? directApiModelName('unorouter', id)
                    : directKind === 'zen'
                    ? directApiModelName('zen', id)
                    : directKind === 'llm7'
                    ? directApiModelName('llm7', id)
                    : directKind === 'navy'
                    ? directApiModelName('navy', id)
                    : directKind === 'literouter'
                    ? literouterModelChoice(id).model
                    : directKind === 'apinex'
                    ? directApiModelName('apinex', id)
                    : directKind === 'nara'
                    ? directApiModelName('nara', id)
                    : base;
            
            
            const wantedLc = wanted.toLowerCase();
            const shortLc = wantedLc.slice(wantedLc.lastIndexOf('/') + 1);
            
            
            const freeList = directKind === 'zenmux'
              ? (res.freeModels || []).map(mid => (mid || '').trim().toLowerCase())
              : [];
            const models = (res.models || []).map(mid => (mid || '').trim().toLowerCase());
            let matched = null;
            if (models.some(mid => mid === wantedLc || mid === shortLc) || freeList.includes(wantedLc)) matched = wanted;
            else if (directKind === 'zenmux' && wantedLc !== base.toLowerCase() && models.some(mid => mid === base.toLowerCase())) {
              
              
              matched = base;
            }
            else if (directKind === 'free' && base.toLowerCase() !== wantedLc) {
              
              
              const baseLc = base.toLowerCase();
              const shortBase = baseLc.slice(baseLc.lastIndexOf('/') + 1);
              if (models.some(mid => mid === baseLc || mid === shortBase)) matched = base;
            }
            const hit = !!matched;
            // Does THIS provider actually serve a free variant of the model?
            const servesFree = directKind === 'free'
              || (directKind === 'nvidia' && isNvidiaFreeModel(matched))
              || (directKind === 'zenmux' && /-free$/i.test(String(matched || '')))
              || (directKind === 'orcarouter' && /-free$/i.test(String(matched || '')))
              || (directKind === 'aihubmix' && /-free$/i.test(String(matched || '')))
              || (directKind === 'unorouter' && /:free$/i.test(String(matched || '')))
              || (directKind === 'zen' && zenIsFreeModel(String(matched || '')))
              || (directKind === 'llm7' && llm7IsFreeModel(String(matched || '')))
              || (directKind === 'navy' && navyIsFreeModel(String(matched || '')))
              || (directKind === 'literouter' && literouterIsFreeModel(String(matched || '')))
              || (directKind === 'apinex' && apinexIsFreeModel(String(matched || '')))
              || (directKind === 'anyapi' && anyapiIsFreeModel(String(matched || '')))
              || (directKind === 'nara' && naraIsFreeModel(String(matched || '')))
              || (directKind === 'inferx' && inferxIsFreeModel(String(matched || '')));
            // Red only when: this provider serves the model, does NOT serve it
            // free, a free version exists somewhere (so it SHOULD be able to),
            // and the provider is free-capable (excludes modal/vercel and the
            // always-free openrouter(free)).
            hitNoFree = hit && !servesFree && modelHasFreeVariantAnywhere(id) && !!directFreeCapableKind(directKind);
            if (hitNoFree) cls = 'nofree'; else cls = hit ? 'yes' : 'no';
            
            mark = hit ? '✓' : '✕';
            
            
            
              
            
              
            
            
            
            const providerFreeLabel = directKind === 'free' ? 'OpenRouter'
              : directKind === 'nvidia' ? 'NVIDIA'
              : directKind === 'zenmux' ? 'ZenMux'
              : directKind === 'orcarouter' ? 'OrcaRouter'
              : directKind === 'aihubmix' ? 'AIHubMix'
              : directKind === 'unorouter' ? 'UnoRouter'
              : directKind === 'zen' ? 'OpenCode Zen'
              : directKind === 'inferx' ? 'Inferx'
              : directKind === 'modal' ? 'Modal'
              : directKind === 'vercel' ? 'Vercel'
              : directKind === 'navy' ? 'NavyAI'
              : directKind === 'literouter' ? 'LiteRouter'
              : directKind === 'apinex' ? 'APInex'
              : directKind === 'anyapi' ? 'AnyAPI'
              : directKind === 'nara' ? 'NaraRouter'
              : 'LLM7';
            detail = hit ? (servesFree ? `free on ${providerFreeLabel} (${matched})` : (hitNoFree ? `paid on ${directKind} API — no free variant` : `available on ${directKind} API`)) : `not available (looked for ${wanted})`;
          }
        }
        return `<span class="mi-prov ${cls} ${p.enabled ? '' : 'off'}" title="${escapeHtml(p.slug)}${p.enabled ? '' : ' (disabled)'}${hitNoFree ? ' — paid only for this model (a free version exists elsewhere)' : ''}">${mark} ${escapeHtml(p.name)}${detail ? ` <em>${escapeHtml(detail)}</em>` : ''}</span>`;
      }
      
      if (ep.error) {
        return `<span class="mi-prov no ${p.enabled ? '' : 'off'}" title="${escapeHtml(p.slug)}${p.enabled ? '' : ' (disabled)'}">✕ ${escapeHtml(p.name)} <em>OpenRouter check failed</em></span>`;
      }
      const hits = ep.providers.filter(e => providerMatchesTag(p.slug, e.tag, e.name));
      const hit = hits[0] || null;
      const freeThere = (p.slug || '').trim().toLowerCase() === 'google-ai-studio' && isGoogleAiStudioFreeModel(id);
      const hitFree = freeThere || hits.some(h => h.pricing && Number(h.pricing.prompt) === 0 && Number(h.pricing.completion) === 0);
      // Red for "no free version" applies only to host providers that offer
      // (free) models at all — Google AI Studio's free tier. Plain OpenRouter
      // host providers never serve the ':free' variant (free models come from
      // OpenRouter itself or the free-capable direct APIs), so they stay green
      // even when they serve the model paid; we only label the endpoint 'free'
      // when its own pricing is $0.
      const hostFreeCapable = (p.slug || '').trim().toLowerCase() === 'google-ai-studio';
      const hitNoFree = !!hit && !hitFree && hostFreeCapable && modelHasFreeVariantAnywhere(id);
      const cls = hitNoFree ? 'nofree' : (hit ? 'yes' : 'no');
      const detail = hit
        ? (hitNoFree
          ? `paid — no free variant${hit.ctx ? ' · ' + formatNum(hit.ctx) + ' ctx' : ''}${hit.quant && hit.quant !== 'unknown' ? ' · ' + hit.quant : ''}`
          : `${hitFree ? 'free' : ''}${hit.ctx ? (hitFree ? ' · ' : '') + formatNum(hit.ctx) + ' ctx' : ''}${hit.quant && hit.quant !== 'unknown' ? ' · ' + hit.quant : ''}`)
        : 'not available';
      
      
      
      
      return `<span class="mi-prov ${cls} ${p.enabled ? '' : 'off'}" title="${escapeHtml(p.slug)}${p.enabled ? '' : ' (disabled)'}${hitNoFree ? ' — paid only for this model (a free version exists elsewhere)' : ''}">${hit ? '✓' : '✕'} ${escapeHtml(p.name)}${detail ? ` <em>${escapeHtml(detail)}</em>` : ''}</span>`;
    }).join('');
    let otherHtml;
    if (ep.error) {
      otherHtml = `<div class="mi-others">OpenRouter endpoint list unavailable (${escapeHtml(ep.error)}).</div>`;
    } else {
      const seenOther = new Set();
      const others = ep.providers.filter(e => {
        if (configured.some(p => providerMatchesTag(p.slug, e.tag, e.name))) return false;
        const key = (e.name || e.tag || '').toLowerCase();
        if (seenOther.has(key)) return false;
        seenOther.add(key); return true;
      });
      otherHtml = others.length
        ? `<div class="mi-others">Also served by ${others.length} provider${others.length === 1 ? '' : 's'} you have not added: ${escapeHtml(others.map(o => o.name).slice(0, 8).join(', '))}${others.length > 8 ? '…' : ''}</div>`
        : (ep.providers.length ? '' : `<div class="mi-others">No provider endpoints reported for this model.</div>`);
    }
    provHtml = `<div class="mi-provs">${rows}</div>${otherHtml}`;
  }
  
  
  if (ep && !ep.loading) {
    provHtml += ` <button type="button" class="small mi-load-providers mi-recheck" data-slug="${escapeHtml(id)}" title="Re-check your configured providers against the latest endpoint list">↻ Re-check</button>`;
  }
  return `<div class="mi-section">Provider compatibility</div>${provHtml}`;
}





function renderBigChatProviderCompat() {
  const el = document.getElementById('bigChatProviderCompat');
  if (!el) return;
  const t = getActiveBigChatThread();
  const model = (t && t.model || '').trim();
  if (!model) { el.style.display = 'none'; return; } // Auto: per-model compat is meaningless
  el.style.display = '';
  el.innerHTML = providerCompatibilityBlock(model);
  el.querySelectorAll('.mi-load-providers').forEach(btn => {
    btn.onclick = () => { const slug = btn.dataset.slug; renderBigChatProviderCompat(); loadModelEndpoints(slug, btn.classList.contains('mi-recheck')); };
  });
}
function refreshBigChatProviderCompat() {
  const el = document.getElementById('bigChatProviderCompat');
  if (!el) return;
  const t = getActiveBigChatThread();
  const model = (t && t.model || '').trim();
  if (!model) { el.style.display = 'none'; return; } // Auto: per-model compat is meaningless
  el.style.display = '';
  if (!modelEndpointCache[model]) loadModelEndpoints(model);
  renderBigChatProviderCompat();
}

let draggedFallbackIdx = null;
let draggedPresetIdx = null;
let draggedPresetFallbackIdx = null;
let draggedPresetDefaultIdx = null;
const openModelInfo = new Set();
function renderFallbackModelsEditor() {
  const container = document.getElementById('fallbackModelsList'); if (!container) return;
  
  
  const scrollTop = container.scrollTop;
  const scrollLeft = container.scrollLeft;
  container.innerHTML = (fallbackDraft || []).map((m, i) => {
    const cat = getCatalogModel(m.slug);
    const arena = arenaPillHtml(m.slug, cat && cat.name);    const quick = cat
      ? `${cat.ctx ? formatNum(cat.ctx) + ' ctx' : ''}${(cat.inMod || []).includes('image') ? ' · 👁' : ''}${(cat.params || []).includes('tools') ? ' · 🛠' : ''}${(cat.params || []).includes('reasoning') ? ' · 🧠' : ''}`
      : '';
    return `<div class="fallback-row" data-idx="${i}" draggable="true">
      <span class="fallback-drag-handle" title="Drag to reorder">⋮⋮</span>
      <input type="text" class="fallback-slug" value="${escapeHtml(m.slug)}" placeholder="model/slug">
      <div class="fallback-right">
        <span class="fallback-quick" title="Context length, capabilities, Arena.ai rank">${arena}${quick ? `<span>${escapeHtml(quick)}</span>` : ''}</pan>
        <select class="fallback-size"><option value="small" ${m.size === 'small' ? 'selected' : ''}>Small</option><option value="big" ${m.size === 'big' ? 'selected' : ''}>Big</option></select>
        <button type="button" class="fallback-info" title="Show model details">ⓘ</button>
        <button type="button" class="fallback-remove" title="Remove">×</button>
      </div>>
    </div>
    <div class="model-info ${openModelInfo.has(i) ? 'open' : ''}" data-info-idx="${i}">${openModelInfo.has(i) ? modelInfoHtml(m.slug) : ''}</div>`;
  }).join('') + `<button type="button" id="addFallbackBtn" class="small" style="margin-top: 4px;">+ Add model…</button>`;
  container.scrollTop = scrollTop;
  container.scrollLeft = scrollLeft;

  container.querySelectorAll('.fallback-info').forEach(btn => {
    btn.onclick = () => {
      const idx = parseInt(btn.closest('.fallback-row').dataset.idx);
      if (openModelInfo.has(idx)) openModelInfo.delete(idx); else openModelInfo.add(idx);
      renderFallbackModelsEditor();
    };
  });
  container.querySelectorAll('.fallback-quick').forEach(q => {
    q.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      const row = q.closest('.fallback-row');
      if (!row) return;
      const idx = parseInt(row.dataset.idx);
      if (openModelInfo.has(idx)) openModelInfo.delete(idx); else openModelInfo.add(idx);
      renderFallbackModelsEditor();
    };
  });
  
  container.querySelectorAll('.fallback-row').forEach(row => {
    row.style.cursor = 'default';
    row.addEventListener('click', (e) => {
      const t = e.target;
      if (t.closest('input') || t.closest('select') || t.closest('button') || t.closest('.fallback-drag-handle') || t.closest('.fallback-quick')) return;
      const idx = parseInt(row.dataset.idx);
      if (Number.isNaN(idx)) return;
      if (openModelInfo.has(idx)) openModelInfo.delete(idx); else openModelInfo.add(idx);
      renderFallbackModelsEditor();
    });
  });
  container.querySelectorAll('.mi-load-providers').forEach(btn => {
    btn.onclick = () => { const slug = btn.dataset.slug; renderFallbackModelsEditor(); loadModelEndpoints(slug); };
  });
  bindModelProviderOverrideControls(container);
  container.querySelectorAll('.fallback-slug').forEach(inp => {
    inp.oninput = () => { const idx = parseInt(inp.closest('.fallback-row').dataset.idx); if (fallbackDraft[idx]) fallbackDraft[idx].slug = inp.value; };
    inp.onchange = () => { if (openModelInfo.size) renderFallbackModelsEditor(); };
  });
  container.querySelectorAll('.fallback-size').forEach(sel => { sel.onchange = () => { const idx = parseInt(sel.closest('.fallback-row').dataset.idx); if (fallbackDraft[idx]) fallbackDraft[idx].size = sel.value; }; });
  container.querySelectorAll('.fallback-remove').forEach(btn => { btn.onclick = () => { const idx = parseInt(btn.closest('.fallback-row').dataset.idx); fallbackDraft.splice(idx, 1); openModelInfo.clear(); renderFallbackModelsEditor(); }; });
  container.querySelectorAll('.fallback-row').forEach(row => {
    row.addEventListener('dragstart', (e) => {
     if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT' || e.target.tagName === 'OPTION') {
        e.preventDefaullt();
        return;
      }
      draggedFallbackIdx = parseInt(row.dataset.idx);
      row.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', String(draggedFallbackIdx));
    });
    row.addEventListener('dragend', () => {
      row.classList.remove('dragging');
      container.querySelectorAll('.fallback-row').forEach(r => r.classList.remove('drag-over-top', 'drag-over-bottom'));
      draggedFallbackIdx = null;
    });
    row.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      const targetIdx = parseInt(row.dataset.idx);
      if (draggedFallbackIdx === null || draggedFallbackIdx === targetIdx) return;
      const rect = row.getBoundingClientRect();
      const midY = rect.top + rect.height / 2;
      row.classList.remove('drag-over-top', 'drag-over-bottom');
      if (e.clientY < midY) row.classList.add('drag-over-top');
      else row.classList.add('drag-over-bottom');
    });
    row.addEventListener('dragleave', () => {
      row.classList.remove('drag-over-top', 'drag-over-bottom');
    });
    row.addEventListener('drop', (e) => {
      e.preventDefault();
      row.classList.remove('drag-over-top', 'drag-over-bottom');
      const targetIdx = parseInt(row.dataset.idx);
      if (draggedFallbackIdx === null || draggedFallbackIdx === targetIdx) return;
      const rect = row.getBoundingClientRect();
      const midY = rect.top + rect.height / 2;
      let insertIdx = targetIdx;
      if (e.clientY >= midY) insertIdx++;
      if (draggedFallbackIdx < insertIdx) insertIdx--;
      const [movedItem] = fallbackDraft.splice(draggedFallbackIdx, 1);
      fallbackDraft.splice(insertIdx, 0, movedItem);
      renderFallbackModelsEditor();
    });
  });
  const addBtn = document.getElementById('addFallbackBtn'); if (addBtn) addBtn.onclick = () => toggleModelPicker(true);
}

function getAllFolders() {
  const folders = new Set();
  folders.add("Among Us");
  if (state.presets) {
    state.presets.forEach(p => {
      if (p.folder && p.folder.trim()) folders.add(p.folder.trim());
    });
  }
  return Array.from(folders).sort();
}

let activePresetFolderFilter = "";

function presetCardHtml(p, realIdx, allFolders) {
    
    const folderOptions = allFolders.map(f => `<option value="${escapeHtml(f)}" ${f === (p.folder || 'Among Us') ? 'selected' : ''}>${escapeHtml(f)}</option>`).join('') +
      `<option value="__NEW_FOLDER__">+ Add new folder...</option>`;
    
    const fallbackListHtml = (p.fallbackModels || []).map((m, fi) => `
      <div class="preset-fallback-row" data-fi="${fi}" draggable="true" style="display:flex; gap:6px; align-items:center;">>
        <span class="preset-fallback-drag-handle" title="Drag to reorder">⋮⋮</span>
        <input type="text" class="preset-fb-slug" value="${escapeHtml(m.slug)}" placeholder="model/slug" style="flex:1; background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 8px; border-radius:4px; font-family:var(--mono); font-size:11px;">
        <select class="preset-fb-size" style="background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 6px; border-radius:4px; font-size:11px;">
          <option value="small" ${m.size == 'small' ? 'selected' : ''}>Small</option>
          <option value="big" ${m.size === 'big' ? 'selected' : ''}>Big</option>
        </select>
        <button type="button" class="preset-fb-remove" title="Remove" style="background:none; border:none; color:var(--text-muted); cursor:pointer; font-size:16px;">×</button>
      </div>
    `).join('');

    const savedFallbackSlugs = (state.apiSettings.fallbackModels || []).map(m => m.slug).filter(Boolean);
    const defaultModels = (p.defaultModels || []).map(s => (s || '').trim()).filter(Boolean);
    const selectedDefaultLc = defaultModels.map(s => s.toLowerCase());
    
    
    let presetModelOptionsHtml = `<option value="">+ Add model… (from Models &amp; Routing)</option>`;
    
    if (savedFallbackSlugs.length > 0) {
      presetModelOptionsHtml += `<optgroup label="Saved Models (Models & Routing)">`;
      savedFallbackSlugs.forEach(slug => {
        const already = selectedDefaultLc.includes(slug.toLowerCase());
        presetModelOptionsHtml += `<option value="${escapeHtml(slug)}" ${already ? 'disabled' : ''}>${escapeHtml(slug)}${already ? ' ✓' : ''}</option>`;
      });
      presetModelOptionsHtml += `</optgroup>`;
    }
    
    const notSavedDefaults = defaultModels.filter(s => !savedFallbackSlugs.some(x => x.toLowerCase() === s.toLowerCase()));
    if (notSavedDefaults.length > 0) {
      presetModelOptionsHtml += `<optgroup label="Selected (not in Models & Routing)">`;
      notSavedDefaults.forEach(slug => {
        presetModelOptionsHtml += `<option value="${escapeHtml(slug)}" disabled>${escapeHtml(slug)} ✓</option>`;
      });
      presetModelOptionsHtml += `</optgroup>`;
    }

    const defaultModelListHtml = defaultModels.map((slug, di) => {
      const cat = getCatalogModel(slug);
      const arena = arenaPillHtml(slug, cat && cat.name);
      const quick = cat
        ? `${cat.ctx ? formatNum(cat.ctx) + ' ctx' : ''}${(cat.inMod || []).includes('image') ? ' · 👁' : ''}${(cat.params || []).includes('tools') ? ' · 🛠' : ''}${(cat.params || []).includes('reasoning') ? ' · 🧠' : ''}`
        : '';
      return `<div class="preset-default-model-row" data-di="${di}" draggable="true">
        <span class="preset-default-model-drag-handle" title="Drag to reorder — first is tried first">⋮⋮</span>
        <input type="text" class="preset-default-model-slug" value="${escapeHtml(slug)}" placeholder="model/slug" spellcheck="false">
        <span class="preset-default-model-quick" title="Context length, capabilities, Arena.ai rank">${arena}${quick ? `<span>${escapeHtml(quick)}</span>` : ''}</span>
        <button type="button" class="preset-default-model-remove" title="Remove (fall back to global default)">×</button>
      </div>`;
    }).join('');

    return `
      <div class="preset-settings-card" data-idx="${realIdx}" style="background:var(--bg); border:1px solid var(--border); border-left:4px solid ${escapeHtml(p.color)}; border-radius:6px; padding:10px 12px; display:flex; flex-direction:column; gap:8px;">
        <!-- Row 1: Header -->
        <div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap;">
          <input type="color" class="preset-color-input" value="${escapeHtml(p.color)}" title="Color" style="width:28px; height:28px; padding:0; border:none; background:none; cursor:pointer;">
          <input type="text" class="preset-color-hex" value="${escapeHtml(p.color)}" spellcheck="false" title="Hex color" style="width:76px; background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 6px; border-radius:4px; font-family:var(--mono); font-size:11px;">
          <button type="button" class="preset-color-default-btn" title="Use the default preset color (${escapeHtml(getDefaultPresetColor())})" style="background:none; border:none; color:var(--text-muted); cursor:pointer; font-size:13px; padding:0 2px;">↺</button>
          <input type="text" class="preset-name-input" value="${escapeHtml(p.name)}" placeholder="Name" style="font-weight:600; width:120px; background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 8px; border-radius:4px; font-size:13px;">
          <input type="text" class="preset-id-input" value="${escapeHtml(p.id)}" placeholder="slug-id" style="font-family:var(--mono); font-size:11px; width:130px; background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 8px; border-radius:4px;">
          <select class="preset-folder-select" style="background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 8px; border-radius:4px; font-size:12px;">
            ${folderOptions}
          </select>
          <button type="button" class="preset-delete-btn" title="Delete preset" style="background:none; border:none; color:var(--text-muted); font-size:18px; cursor:pointer; margin-left:auto; line-height:1;" ${state.presets.length <= 1 ? 'disabled' : ''}>×</button>
        </div>

        <!-- Row 1b: Color palette -->
        <div class="swatches preset-color-swatches" style="padding-left:2px;">
          ${getPresetPalette().map(c => `<button type="buttn" class="swatch ${c.toLowerCase() === (p.color || '').toLowerCase() ? 'active' : ''}" data-c="${escapeHtml(c)}" style="background:${escapeHtml(c)}" title="${escapeHtml(c)}"></button>`).join('')}
        </div>

        <!-- Row 2: Default Model (multi-select, drag to sort) -->
        <div style="display:flex; gap:8px; align-items:flex-start; flex-wrap:wrap; font-size:12px;">
          <span style="color:var(--text-muted); min-width:95px; padding-top:4px;">Default Model:</span>
          <div style="flex:1; min-width:200px; display:flex; flex-direction:column; gap:4px;">
            <div style="display:flex; gap:6px;">
              <select class="preset-default-model-add" style="flex:1; min-width:120px; font-family:var(--mono); font-size:11px; background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 8px; border-radius:4px;">
                ${presetModelOptionsHtml}
              </sellect>
              <input type="text" class="preset-default-model-custom" placeholder="or type model/slug" spellcheck="false" syle="width:132px; font-family:var(--mono); font-size:11px; background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 8px; border-radius:4px;">
              <button type="button" class="preset-default-model-add-btn small" style="white-space:nowrap;">+ Add</button>
            </div>
            <div class="preset-default-model-list" style="display:flex; flex-direction:column; gap:4px;">
              ${defaultModelListHtml}
              ${defaultModelListHtml ? '<div style="font-size:10px; color:var(--text-muted);">Tried top-to-bottom, then the 🛡️ fallbacks. Drag ⋮⋮ to reorder.</div>' : '<div style="font-size:11px; color:var(--text-muted);">Use global default model — pick models from the list above or type a slug; drag ⋮⋮ to set the order they are tried.</div>'}
            </div>
          </div>
        </div>

        <!-- Row 2a: Thinking Level -->
        <div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap; font-size:12px;">
          <span style="color:var(--text-muted); min-width:95px;">Thinking Level:</span>
          <select class="preset-thinking-level-select" style="flex:1; min-width:200px; background:var(--bg); border:1px solid var(--border); color:var(--text); padding:4px 8px; border-radius:4px; font-size:12px;">
            <option value="auto" ${p.thinkingLevel === 'auto' || !p.thinkingLevel ? 'selected' : ''}>Auto / Default</option>
            <option value="none" ${p.thinkingLevel === 'none' ? 'selected' : ''}>None</option>
            <option value="minimal" ${p.thinkingLevel === 'minimal' ? 'selected' : ''}>Minimal</option>
            <option value="low" ${p.thinkingLevel === 'low' ? 'selected' : ''}>Low</option>
            <option value="medium" ${p.thinkingLevel === 'medium' ? 'selected' : ''}>Medium</option>
            <option value="high" ${p.thinkingLevel === 'high' ? 'selected' : ''}>High</option>
            <option value="xhigh" ${p.thinkingLevel === 'xhigh' ? 'selected' : ''}>X-High</option>
            <option value="max" ${p.thinkingLevel === 'max' ? 'selected' : ''}>Max</option>
          </select>
        </div>

        <!-- Row 2b: Conversation memory -->
        <div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap; font-size:12px;">
          <span style="color:var(--text-muted); min-width:95px;">Memory:</span>
          <label style="display:flex; align-items:center; gap:6px; margin:0; cursor:pointer; font-size:12px;">
            <input type="checkbox" class="preset-history-input" ${p.maintainHistory !== false ? 'checked' : ''}>
            Remember this conversation
          </label>
          <span style="font-size:10px; color:var(--text-muted);">${p.maintainHistory !== false ? 'Sends prior messages so the character recalls what was said.' : 'Every message is answered with no memory of earlier turns.'}${state.apiSettings.maintainHistory ? '' : ' ⚠ Global history is OFF, which overrides this.'}</span>
        </div>

        <!-- Row 3: Tools & System Prompt -->
        <details style="border-top:1px solid var(--border); padding-top:6px;">
          <summary style="font-size:12px; color:var(--text-muted); cursor:pointer;">🔧 Tools & System Prompt ${(p.allowedTools && p.allowedTools.length) ? '· ' + p.allowedTools.length + ' tools' : '· inherit global'} ${p.systemPrompt && p.systemPrompt.trim() ? '· prompt ✓' : ''}</summary>
          <div style="padding-top:8px; display:flex; flex-direction:column; gap:8px;">
            <label style="display:flex; align-items:center; gap:6px; font-size:12px; cursor:pointer; margin:0; color:var(--text-muted);">
              <input type="checkbox" class="preset-tools-enable" ${(p.allowedTools && p.allowedTools.length) ? 'checked' : ''}>
              Override allowed tools for this preset (unchecked = inherit global preset-safe tools)
            </label>
            <div class="preset-tools-area" style="display:${(p.allowedTools && p.allowedTools.length) ? 'grid' : 'none'}; grid-template-columns:repeat(auto-fill,minmax(200px,1fr)); gap:4px; ${p.allowedTools && p.allowedTools.length ? '' : 'opacity:0.5;'}">
              ${AGENT_TOOL_DEFS.filter(t => t.presetSafe).map(t => {
                const checked = p.allowedTools && p.allowedTools.includes(t.name);
                return `<label style="display:flex;gap:6px;align-items:flex-start;margin:0;font-size:11px;cursor:pointer;">
                  <input type="checkbox" class="preset-tool-cb" data-tool="${escapeHtml(t.name)}" ${checked ? 'checked' : ''}>
                  <span><code>${escapeHtml(t.name)}</code></span>
                </label>`;
              }).join('')}
            </div>
            <label style="font-size:12px; color:var(--text-muted); margin-top:4px; display:block;">
              System Prompt (injected as a system message on every call):
              <textarea class="preset-system-prompt" rows="3" style="width:100%; margin-top:4px; font-size:12px; background:var(--bg); border:1px solid var(--bordeer); color:var(--text); padding:6px; border-radius:4px; font-family:inherit;" placeholder="System prompt for this preset...">${escapeHtml(p.systemPrompt || '')}</textarea>
            </label>
          </div>
        </details>

        <!-- Row 4: Preset-Specific Fallback Models -->
        <details style="border-top:1px solid var(--border); padding-top:6px;">
          <summary style="font-size:12px; color:var(--text-muted); cursor:pointer;">🛡️ Preset Fallbacks (${p.enableFallback && (p.fallbackModels || []).length ? p.fallbackModels.length + ' custom fallbacks' : 'Using global fallbacks'})</summary>
          <div style="padding-top:8px; display:flex; flex-direction:column; gap:8px;">
            <label style="display:flex; align-items:center; gap:6px; font-size:12px; cursor:pointer; margin:0;">
              <input type="checkbox" class="preset-fallback-enable" ${p.enableFallback ? 'checked' : ''}>
              Enable preset-specific fallback models on HTTP 403
            </label>
            <div class="preset-fallback-editor-area" style="display:flex; flex-direction:column; gap:6px; ${p.enableFallback ? '' : 'opacity:0.5; pointer-events:none;'}">
              ${fallbackListHtml}
              <button type="button" class="small preset-add-fb-btn" style="align-self:flex-start; margin-top:2px;">+ Add fallback model</button>
            </div>
          </div>
        </details>
      </div>
    `;
  }

function wirePresetCard(card) {
    const idx = parseInt(card.dataset.idx);
    const preset = state.presets[idx];
    if (!preset) return;

    const colorInp = card.querySelector('.preset-color-input');
    const colorHex = card.querySelector('.preset-color-hex');
    const applyPresetColor = (hex, rerender) => {
      preset.color = hex;
      if (colorInp) colorInp.value = hex;
      if (colorHex) colorHex.value = hex;
      card.style.borderLeftColor = hex;
      card.querySelectorAll('.preset-color-swatches .swatch').forEach(b => b.classList.toggle('active', (b.dataset.c || '').toLowerCase() === hex.toLowerCase()));
      syncCharacters();
      if (rerender)  renderChatSidebar(); 
    };
    if (colorInp) colorInp.oninput = () => applyPresetColor(colorInp.value, false);
    if (colorHex) colorHex.onchange = () => { const hex = normalizeHex(colorHex.value, null); if (!hex) { colorHex.value = preset.color; return; } applyPresetColor(hex, true); };
    card.querySelectorAll('.preset-color-swatches .swatch').forEach(b => { b.onclick = () => applyPresetColor(b.dataset.c, true); });
    const colorDefBtn = card.querySelector('.preset-color-default-btn');
    if (colorDefBtn) colorDefBtn.onclick = () => applyPresetColor(getDefaultPresetColor(), true);

    const nameInp = card.querySelector('.preset-name-input');
    if (nameInp) nameInp.oninput = () => { preset.name = nameInp.value.trim() || 'Preset'; syncCharacters(); };

    const idInp = card.querySelector('.preset-id-input');
    if (idInp) idInp.onchange = () => {
      const newId = idInp.value.trim().toLowerCase().replace(/[^a-z0-9_-]/g, '-') || 'preset-' + idx;
      if (newId !== preset.id) {
        if (state.presets.some((item, i) => i !== idx && item.id === newId)) {
          alert(`ID "${newId}" already exists.`);
          idInp.value = preset.id;
          return;
        }
        const oldId = preset.id;
        preset.id = newId;
        if (state.conversations[oldId]) {
          state.conversations[newId] = state.conversations[oldId];
          delete state.conversations[oldId];
        }
        
        
        if (state.activeChatPreset === oldId) state.activeChatPreset = newId;
        Object.values((state.bigChat && state.bigChat.threads) || {}).forEach(t => {
          if ((t.preset || '').trim() === oldId) t.preset = newId;
        });
        syncCharacters();
      }
    };

    const folderSel = card.querySelector('.preset-folder-select');
    if (folderSel) folderSel.onchange = () => {
      if (folderSel.value === '__NEW_FOLDER__') {
        const newFolder = prompt("Enter new folder name:", "Custom");
        if (newFolder && newFolder.trim()) {
          preset.folder = newFolder.trim();
        } else {
          folderSel.value = preset.folder || 'Among Us';
          return;
        }
      } else {
        preset.folder = folderSel.value;
      }
      syncCharacters();
      renderPresetSettingsEditor();
    };

    
    const defModAdd = card.querySelector('.preset-default-model-add');
    if (defModAdd) defModAdd.onchange = () => {
      const slug = (defModAdd.value || '').trim();
      defModAdd.value = '';
      if (!slug) return;
      preset.defaultModels = preset.defaultModels || [];
      if (preset.defaultModels.some(s => (s || '').trim().toLowerCase() === slug.toLowerCase())) return;
      preset.defaultModels.push(slug);
      refreshPresetCard(idx);
    };
    const defModCustom = card.querySelector('.preset-default-model-custom');
    const defModAddBtn = card.querySelector('.preset-default-model-add-btn');
    const doAddDefaultModel = () => {
      if (!defModCustom) return;
      const slug = (defModCustom.value || '').trim();
      if (!slug) return;
      defModCustom.value = '';
      preset.defaultModels = preset.defaultModels || [];
      if (preset.defaultModels.some(s => (s || '').trim().toLowerCase() === slug.toLowerCase())) return;
      preset.defaultModels.push(slug);
      refreshPresetCard(idx);
    };
    if (defModAddBtn) defModAddBtn.onclick = doAddDefaultModel;
    if (defModCustom) defModCustom.okeydown = (e) => { if (e.key === 'Enter') { e.preventDefault(); doAddDefaultModel(); } };

    card.querySelectorAll('.preset-default-model-row').forEach(row => {
      const di = parseInt(row.dataset.di);
      const slugInp = row.querySelector('.preset-default-model-slug');
      if (slugInp) slugInp.oninput = () => { if (preset.defaultModels[di] !== undefined) preset.defaultModels[di] = slugInp.value; };
      const rmBtn = row.querySelector('.preset-default-model-remove');
      if (rmBtn) rmBtn.onclick = () => { preset.defaultModels.splice(di, 1); refreshPresetCard(idx); };

      
      row.addEventListener('dragstart', (e) => {
        if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT' || e.target.tagName === 'OPTION') {
          e.preventDefault();
          return;
        }
        draggedPresetDefaultIdx = di;
        row.classList.add('dragging');
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', String(di));
      });
      row.addEventListener('dragend', () => {
        row.classList.remove('dragging');
        card.querySelectorAll('.preset-default-model-row').forEach(r => r.classList.remove('drag-over-top', 'drag-over-bottom'));
        draggedPresetDefaultIdx = null;
      });
      row.addEventListener('dragover', (e) => {
        e.preventDefault();
        if (draggedPresetDefaultIdx === null || draggedPresetDefaultIdx === di) return;
        e.dataTransfer.dropEffect = 'move';
        const rect = row.getBoundingClientRect();
        const midY = rect.top + rect.height / 2;
        row.classList.remove('drag-over-top', 'drag-over-bottom');
        if (e.clientY < midY) row.classList.add('drag-over-top');
        else row.classList.add('drag-over-bottom');
      });
      row.addEventListener('dragleave', () => {
        row.classList.remove('drag-over-top', 'drag-over-bottom');
      });
      row.addEventListener('drop', (e) => {
        e.preventDefault();
        row.classList.remove('drag-over-top', 'drag-over-bottom');
        if (draggedPresetDefaultIdx === null || draggedPresetDefaultIdx === di) return;
        const rect = row.getBoundingClientRect();
        const midY = rect.top + rect.height / 2;
        let insertIdx = di;
        if (e.clientY >= midY) insertIdx++;
        if (draggedPresetDefaultIdx < insertIdx) insertIdx--;
        const [movedItem] = preset.defaultModels.splice(draggedPresetDefaultIdx, 1);
        preset.defaultModels.splice(insertIdx, 0, movedItem);
        refreshPresetCard(idx);
      });
    });

    const thinkSel = card.querySelector('.preset-thinking-level-select');
    if (thinkSel) thinkSel.onchange = () => { preset.thinkingLevel = thinkSel.value; };

    const histCb = card.querySelector('.preset-history-input');
    if (histCb) histCb.onchange = () => { preset.maintainHistory = histCb.checked; refreshPresetCard(idx); };

    const fbEnableCb = card.querySelector('.preset-fallback-enable');
    if (fbEnableCb) fbEnableCb.onchange = () => {
      preset.enableFallback = fbEnableCb.checked;
      refreshPresetCard(idx);
    };

    card.querySelectorAll('.preset-fallback-row').forEach(row => {
      const fi = parseInt(row.dataset.fi);
      const fbModel = preset.fallbackModels[fi];
      if (!fbModel) return;
      const slugInp = row.querySelector('.preset-fb-slug');
      if (slugInp) slugInp.oninput = () => { fbModel.slug = slugInp.value.trim(); };
      const sizeSel = row.querySelector('.preset-fb-size');
      if (sizeSel) sizeSel.onchange = () => { fbModel.size = sizeSel.value; };
      const rmBtn = row.querySelector('.preset-fb-remove');
      if (rmBtn) rmBtn.onclick = () => {
        preset.fallbackModels.splice(fi, 1);
        refreshPresetCard(idx);
      };

      
      row.addEventListener('dragstart', (e) => {
        if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT' || e.target.tagName === 'OPTION') {
          e.preventDefault();
          return;
        }
        draggedPresetIdx = idx;
        draggedPresetFallbackIdx = fi;
        row.classList.add('dragging');
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', String(fi));
      });

      row.addEventListener('dragend', () => {
        row.classList.remove('dragging');
        card.querySelectorAll('.preset-fallback-row').forEach(r => r.classList.remove('drag-over-top', 'drag-over-bottom'));
        draggedPresetIdx = null;
        draggedPresetFallbackIdx = null;
      });

      row.addEventListener('dragover', (e) => {
        e.preventDefault();
        if (draggedPresetIdx !== idx || draggedPresetFallbackIdx === null || draggedPresetFallbackIdx === fi) return;
        e.dataTransfer.dropEffect = 'move';
        const rect = row.getBoundingClientRect();
        const midY = rect.top + rect.height / 2;
        row.classList.remove('drag-over-top', 'drag-over-bottom');
        if (e.clientY < midY) {
          row.classList.add('drag-over-top');
        } else {
          row.classList.add('drag-over-bottom');
         }
      });

      row.addEventListener('dragleave', () => {
        row.classList.remove('drag-over-top', 'drag-over-bottom');
      });

      row.addEventListener('drop', (e) => {
        e.preventDefault();
        row.classList.remove('drag-over-top', 'drag-over-bottom');
        if (draggedPresetIdx !== idx || draggedPresetFallbackIdx === null || draggedPresetFallbackIdx === fi) return;
        const rect = row.getBoundingClientRect();
        const midY = rect.top + rect.height / 2;
        let insertIdx = fi;
        if (e.clientY >= midY) insertIdx++;
        if (draggedPresetFallbackIdx < insertIdx) insertIdx--;
        
        const [movedItem] = preset.fallbackModels.splice(draggedPresetFallbackIdx, 1);
        preset.fallbackModels.splice(insertIdx, 0, movedItem);
        refreshPresetCard(idx);
      });
    });

    const addFbBtn = card.querySelector('.preset-add-fb-btn');
    if (addFbBtn) addFbBtn.onclick = () => {
      preset.fallbackModels = preset.fallbackModels || [];
      preset.fallbackModels.push({ slug: '', size: 'small' });
      refreshPresetCard(idx);
    };

    const sysPromptInp = card.querySelector('.preset-system-prompt');
    if (sysPromptInp) sysPromptInp.oninput = () => { preset.systemPrompt = sysPromptInp.value; };

    
    const toolsEnable = card.querySelector('.preset-tools-enable');
    const toolsArea = card.querySelector('.preset-tools-area');
    const toolCbs = card.querySelectorAll('.preset-tool-cb');
    const updatePresetTools = () => {
      const checked = [...toolCbs].filter(cb => cb.checked).map(cb => cb.dataset.tool);
      preset.allowedTools = checked.length ? checked : null;
      if (toolsArea) toolsArea.style.display = checked.length || (toolsEnable && toolsEnable.checked) ? 'grid' : 'none';
      if (toolsArea) toolsArea.style.opacity = (toolsEnable && toolsEnable.checked) ? '' : '0.5';
      
      refreshPresetCard(idx);
    };
    if (toolsEnable) toolsEnable.onchange = () => {
      if (!toolsEnable.checked) { preset.allowedTools = null; }
      else if (!preset.allowedTools) { preset.allowedTools = [...getEnabledAgentTools()].filter(n => AGENT_TOOL_DEFS.find(t => t.name === n)?.presetSafe); }
      updatePresetTools();
    };
    toolCbs.forEach(cb => { cb.onchange = updatePresetTools; });

    const delBtn = card.querySelector('.preset-delete-btn');
    if (delBtn) delBtn.onclick = () => {
      if (state.presets.length <= 1) {
        alert("Cannot delete the last remaining preset.");
        return;
      }
      if (confirm(`Delete preset "${preset.name}" (${preset.id})?`)) {
        state.presets.splice(idx, 1);
        syncCharacters();
        renderPresetSettingsEditor();
      }
    };
  }




function refreshPresetCard(realIdx) {
  const container = document.getElementById('presetSettingsList');
  if (!container) return;
  const p = state.presets[realIdx];
  if (!p) return;
  const existing = container.querySelector('.preset-settings-card[data-idx="' + realIdx + '"]');
  if (!existing) return;
  const allFolders = getAllFolders();
  const tmp = document.createElement('div');
  tmp.innerHTML = presetCardHtml(p, realIdx, allFolders);
  const node = tmp.firstElementChild;
  if (!node) return;
  existing.replaceWith(node);
  wirePresetCard(node);
}

function renderPresetSettingsEditor() {
  const container = document.getElementById('presetSettingsList');
  const filterSelect = document.getElementById('presetSettingsFolderFilter');
  if (!container) return;
  
  
  const savedScrollTop = container.scrollTop;

  const allFolders = getAllFolders();
  if (filterSelect) {
    const curVal = activePresetFolderFilter;
    filterSelect.innerHTML = `<option value="">All folders</option>` +
      allFolders.map(f => `<option value="${escapeHtml(f)}" ${f === curVal ? 'selected' : ''}>${escapeHtml(f)}</option>`).join('');
    filterSelect.onchange = () => {
      activePresetFolderFilter = filterSelect.value;
      renderPresetSettingsEditor();
    };
  }

  const presetsToShow = (state.presets || []).filter(p => !activePresetFolderFilter || p.folder === activePresetFolderFilter);

  container.innerHTML = presetsToShow.map(p => presetCardHtml(p, state.presets.findIndex(item => item.id === p.id), allFolders)).join('');
  container.scrollTop = savedScrollTop;
  container.querySelectorAll('.preset-settings-card').forEach(card => wirePresetCard(card));

  const addPresetBtn = document.getElementById('addPresetBtn');
  if (addPresetBtn) addPresetBtn.onclick = () => {
    const id = 'custom-' + Date.now().toString(36);
    state.presets.push({
      id: id,
      name: 'New Preset',
      color: getDefaultPresetColor(),
      folder: activePresetFolderFilter || 'Among Us',
      defaultModel: '',
      defaultModels: [],
      enableFallback: false,
      fallbackModels: [],
      systemPrompt: '',
      maintainHistory: true
    });
    syncCharacters();
    renderPresetSettingsEditor();
  };
}


function humanBytes(n) {
  if (n < 1024) return n + ' B';
  if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB';
  return (n / 1024 / 1024).toFixed(2) + ' MB';
}
function countAllMessages() {
  let chat = 0, big = 0;
  for (const pd of Object.values(state.conversations || {})) {
    for (const t of Object.values((pd && pd.threads) || {})) chat += (t.messages || []).length;
  }
  for (const t of Object.values(((state.bigChat || {}).threads) || {})) big += (t.messages || []).length;
  return { chat, big };
}
function renderStorageSummary() {
  const el = document.getElementById('storageSummary');
  if (!el) return;
  let bytes = 0;
  try { bytes = (localStorage.getItem(STORAGE_KEY) || '').length; } catch {}
  const { chat, big } = countAllMessages();
  const charThreads = Object.values(state.conversations || {}).reduce((n, pd) => n + Object.keys((pd && pd.threads) || {}).length, 0);
  const bigThreads = Object.keys(((state.bigChat || {}).threads) || {}).length;
  const rows = [
    ['Stored  size', humanBytes(bytes)],
    ['Character messages', `${formatNum(chat)} in ${charThreads} thread${charThreads === 1 ? '' : 's'}`],
    ['Big Chat messages', `${formatNum(big)} in ${bigThreads} thread${bigThreads === 1 ? '' : 's'}`],
    ['Turn history', `${(state.turns || []).length} turn${(state.turns || []).length === 1 ? '' : 's'}`],
    ['Presets', `${(state.presets || []).length}`],
    ['Model catalog', `${(((state.modelCatalog || {}).models) || []).length} models cached${modelCatalogAgeLabel()}`],
    ['Provider catalog', `${(((state.providerCatalog || {}).providers) || []).length} providers cached${providerCatalogAgeLabel()}`],
    ['API key', state.apiSettings.apiKey ? 'saved' : 'not set'],
  ];
  el.innerHTML = rows.map(([k, v]) => `<div class="ss-row"><span>${escapeHtml(k)}</span><strong>${escapeHtml(String(v))}</strong></div>`).join('');
}

const CLEAR_ACTIONS = {
  chats: {
    label: 'Delete every conversation (character chats and Big Chat)?',
    run() {
      state.conversations = {};
      clearBigChatSubagentActivities();
      state.bigChat = { threads: {}, activeThreadId: null };
      state.subagentHistory = {};
      bigChatDraftsMap.clear(); attVaultWipe(); workspaceVaultWipe();
      agentFS.mem = {};
      createBigChatThread('Chat 1');
      state.activeChatPreset = null;
      state.selectedChatPresets = new Set();
    },
  },
  turns: { label: 'Delete all turn history and loaded inputs?', run() { state.turns = []; state.currentInputs = []; nextTurnId = 1; } },
  bigchat: {
    label: 'Delete all Big Chat threads? Character chats are kept.',
    run() { clearBigChatSubagentActivities(); state.bigChat = { threads: {}, activeThreadId: null }; bigChatDraftsMap.clear(); attVaultWipe(); workspaceVaultWipe(); agentFS.mem = {}; createBigChatThread('Chat 1'); },
  },
  catalog: { label: 'Clear the cached OpenRouter model and provider lists?', run() { state.modelCatalog = null; state.providerCatalog = null; state.arenaCatalog = null; for (const k of Object.keys(modelEndpointCache)) delete modelEndpointCache[k]; for (const k of Object.keys(directApiModelsCache)) delete directApiModelsCache[k]; } },
  key: { label: 'Remove your saved API key?', run() { state.apiSettings.apiKey = ''; } },
  workspace: { label: 'Delete all in-memory agent files? (Files in a mounted real folder are untouched.)', run() { agentFS.mem = {}; snapshotWorkspaceToThread(activeWorkspaceThread()); persistActiveWorkspace(); } },
  settings: {
    label: 'Reset all settings to defaults? Conversations, presets and colors are kept.',
    run() {
      const keepKey = state.apiSettings.apiKey;
      state.apiSettings = JSON.parse(JSON.stringify(DEFAULT_API_SETTINGS));
      state.apiSettings.apiKey = keepKey;
    },
  },
  presets: {
    label: 'Restore the default characters? Custom presets you added will be removed (their chats remain).',
    run() { state.presets = defaultPresets(); syncCharacters(); },
  },
  colors: {
    label: 'Reset theme colors and the preset palette to defaults?',
    run() {
      state.themeColors = { dark: {}, light: {} };
      state.presetPalette = null;
      state.defaultPresetColor = DEFAULT_PRESET_COLOR;
      applyThemeColors(state.theme);
    },
  },
  everything: {
    label: null, 
    run() { try { localStorage.removeItem(STORAGE_KEY); localStorage.removeItem('openrouter_preset_runner_state_v2'); } catch {} bigChatDraftsMap.clear(); attVaultWipe(); workspaceVaultWipe(); },
  },
};

function runClearAction(kind) {
  const action = CLEAR_ACTIONS[kind];
  if (!action) return;

  if (kind === 'everything') {
    if (!confirm('This erases EVERYTHING — conversations, presets, settings and your API key.\n\nThis cannot be undone. Export a backup first if you want one.\n\nContinue?')) return;
    const typed = prompt('Type ERASE to confirm:');
    if ((typed || '').trim().toUpperCase() !== 'ERASE') { showToast('Cancelled — nothing was deleted', 'info'); return; }
    action.run();
    location.reload();
    return;
  }

  if (!confirm(action.label + '\n\nThis cannot be undone.')) return;
  action.run();
  saveState();
  
  syncCharacters();
  syncSubagentProfiles();
  renderChatSidebar(); renderChatMessages(); renderChatThreadSelector();  renderBigChatThreadSelector();
  renderBigChatMessages();
  renderBigChatSubagentSidebar();
  renderTurnList(); renderChatHistory(); updateTurnIndicator(); updateBadges();

  populateChatModelSelect(); populateBigModelSelect(); populateBigProviderSelect(); populateBigThinkingSelect(); populateBigPresetSelect(); updateChatInputState(); updateBigChatInputState();
  renderStorageSummary();
  showToast('Done', 'success');
}

// Keys from saveState() that are configuration rather than content. A settings
// export is deliberately smaller than a full backup: conversations, turns, Big
// Chat threads, run history and the downloaded model/provider/arena caches are
// all left out — they are either personal content or regenerated on demand, so
// they have no business in a "settings" file.
const SETTINGS_EXPORT_KEYS = [
  'apiSettings', 'theme', 'themeColors', 'collapsedFolders', 'sidebars',
  'sidebarsTouched', 'bigChatSubagentsWidth', 'defaultPresetColor',
  'presetPalette', 'presets',
];

function settingsSnapshotForExport() {
  const snapshot = {};
  for (const key of SETTINGS_EXPORT_KEYS) {
    if (state[key] !== undefined) snapshot[key] = state[key];
  }
  // Deep-copy so a later mutation of state cannot alter the object we are
  // about to stringify (and to drop any non-serializable reference).
  return JSON.parse(JSON.stringify(snapshot));
}

function exportSettings() {
  const payload = {
    _format: 'clod-code-settings',
    _version: 1,
    exportedAt: new Date().toISOString(),
    data: settingsSnapshotForExport(),
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `clod-code-settings-${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  showToast('Settings exported', 'success');
}

// Import a settings export back over the current configuration. Only the keys
// the exporter wrote are touched — conversations, turns, Big Chat threads and
// the downloaded caches stay exactly as they are. The merge is applied to the
// SAVED state blob rather than to live memory, then the page reloads: loadState()
// already carries all the normalization/backfill (account lists, defaults for
// fields an older export predates, subagent profile migration), so reusing it is
// both less code and the only way to land a v1 file on a v2 schema safely.
function importSettings(file) {
  const reader = new FileReader();
  reader.onerror = () => showToast('Could not read the file', 'error');
  reader.onload = () => {
    let parsed;
    try { parsed = JSON.parse(reader.result); }
    catch { showToast('Could not import: the file is not valid JSON', 'error'); return; }
    // Prefer our envelope; accept a bare settings object so a hand-edited file
    // still works, but refuse a different _format (e.g. a full backup) instead
    // of silently merging whatever keys happen to overlap.
    const ours = parsed && parsed._format === 'clod-code-settings';
    if (!ours && parsed && parsed._format) {
      showToast(`Could not import: that is a ${parsed._format} file, not a settings export`, 'error');
      return;
    }
    const data = ours ? parsed.data : parsed;
    if (!data || typeof data !== 'object') { showToast('Could not import: unrecognised settings file', 'error'); return; }
    const found = SETTINGS_EXPORT_KEYS.filter((k) => data[k] !== undefined);
    if (!found.length) { showToast('That file contains no settings to import', 'error'); return; }
    if (!confirm('Import these settings?\n\nYour current API keys, providers, models, agent tools, colors and presets are replaced by the file. Your conversations, chats and turn history are left untouched.\n\nContinue?')) return;
    // Flush the current in-memory state first so everything we are NOT importing
    // (conversations above all) is present in the blob we merge onto.
    try { saveState(); } catch {}
    let saved;
    try { saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') || {}; } catch { saved = {}; }
    for (const k of found) saved[k] = data[k];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(saved));
    location.reload();
  };
  reader.readAsText(file);
}

function exportFullBackup() {
  const payload = {
    _format: 'clod-code-backup',
    _version: 1,
    exportedAt: new Date().toISOString(),
    data: JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'),
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `clod-code-backup-${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  showToast('Backup exported', 'success');
}

function importFullBackup(file) {
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const parsed = JSON.parse(reader.result);
      const data = parsed && (parsed._format === 'clod-code-backup' || parsed._format === 'preset-runner-backup') ? parsed.data : parsed;
      if (!data || typeof data !== 'object') throw new Error('Unrecognised file');
      if (!confirm('Restoring replaces ALL current data with the contents of this backup.\n\nContinue?')) return;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
      location.reload();
    } catch (e) { showToast(`Could not restore: ${e.message}`, 'error'); }
  };
  reader.onerror = () => showToast('Could not read the file', 'error');
  reader.readAsText(file);
}

function initDataResetTab() {
  document.querySelectorAll('.clear-btn').forEach(btn => { btn.onclick = () => runClearAction(btn.dataset.clear); });
  const setExp = document.getElementById('settingsExportBtn'); if (setExp) setExp.onclick = exportSettings;
  const setImp = document.getElementById('settingsImportBtn');
  const setImpInput = document.getElementById('settingsImportInput');
  if (setImp && setImpInput) {
    setImp.onclick = () => setImpInput.click();
    setImpInput.onchange = () => { if (setImpInput.files && setImpInput.files[0]) importSettings(setImpInput.files[0]); setImpInput.value = ''; };
  }
  const exp = document.getElementById('backupExportBtn'); if (exp) exp.onclick = exportFullBackup;
  const imp = document.getElementById('backupImportBtn');
  const impInput = document.getElementById('backupImportInput');
  if (imp && impInput) {
    imp.onclick = () => impInput.click();
    impInput.onchange = () => { if (impInput.files && impInput.files[0]) importFullBackup(impInput.files[0]); impInput.value = ''; };
  }
  renderStorageSummary();
}


// The three inner panel rails in one place. Their ids/labels are needed by the
// initial wiring, by the responsive layout (collapse on mobile, restore on
// desktop) and by the toggles themselves — a single list keeps those from
// drifting apart, which is how a rail can end up controlling nothing.
// [panelId, toggleId, label, stateKey, side, defaultCollapsedOnDesktop]
const INNER_SIDEBARS = [
  ['bigChatThreadsPanel', 'bigChatSidebarToggle', 'Chats', 'bigChat', 'left', false],
  ['bigChatSubagentsPanel', 'bigChatSubagentsToggle', 'Sub-agents', 'bigChatSubagents', 'right', false],
  ['chatSidebarPanel', 'chatSidebarToggle', 'Characters', 'chat', 'left', true],
];

function applySidebarState(panelId, toggleId, openLabel, collapsed, side = 'left') {
  const panel = document.getElementById(panelId);
  const toggle = document.getElementById(toggleId);
  if (!panel || !toggle) return;
  panel.classList.toggle('collapsed', collapsed);
  toggle.querySelector('.st-label').textContent = collapsed ? `\u25B8 ${openLabel}` : (side === 'right' ? '\u25B8' : '\u25C2');
  toggle.title = collapsed ? `Show ${openLabel.toLowerCase()}` : `Hide ${openLabel.toLowerCase()}`;
  toggle.setAttribute('aria-label', toggle.title);
  toggle.setAttribute('aria-expanded', String(!collapsed));
  toggle.setAttribute('aria-controls', panelId);
}
function initSidebarToggle(panelId, toggleId, openLabel, stateKey, defaultCollapsed = true, side = 'left') {
  const toggle = document.getElementById(toggleId);
  if (!toggle) return;
  
  const touched = !!(state.sidebarsTouched && state.sidebarsTouched[stateKey]);
  let collapsed = touched ? state.sidebars[stateKey] !== false : defaultCollapsed;
  applySidebarState(panelId, toggleId, openLabel, collapsed, side);
  toggle.onclick = () => {
    // Read the panel's real class instead of a closure copy: the responsive
    // layout collapses panels directly, and a stale copy would make the first
    // tap after that a no-op.
    const panel = document.getElementById(panelId);
    collapsed = !(panel && panel.classList.contains('collapsed'));
    if (!state.sidebars) state.sidebars = {};
    state.sidebars[stateKey] = collapsed;
    if (!state.sidebarsTouched) state.sidebarsTouched = {};
    state.sidebarsTouched[stateKey] = true;
    applySidebarState(panelId, toggleId, openLabel, collapsed, side);
    saveState();
  };
}


// ---- Responsive (desktop + mobile) --------------------------------------
// Mobile layout contract (matches the @media blocks in styles.css):
//  - ≤900px: the main left sidebar becomes an overlay drawer; body.sidebar-open
//    shows it, and the header 👽 button toggles it.
//  - Inner panels (Chats / Subagents / Characters) slide over the
//    chat as overlays; on entering mobile they auto-collapse so the chat gets
//    the screen, and on leaving mobile the persisted states are restored.
//  - Touch devices: message tools are always visible (no hover on touch).
const MOBILE_QUERY = '(max-width: 900px)';
let isMobileViewport = window.matchMedia ? window.matchMedia(MOBILE_QUERY).matches : false;

function isMobileLayout() { return isMobileViewport; }

function initResponsiveLayout() {
  if (!window.matchMedia) return;
  const mq = window.matchMedia(MOBILE_QUERY);
  const apply = () => {
    isMobileViewport = mq.matches;
    document.body.classList.toggle('is-mobile', isMobileViewport);
    // Re-apply every rail through initSidebarToggle so the panel's class, the
    // rail's label/aria-expanded and the click handler's own state can never
    // drift apart. Collapsed is the default on mobile (the chat gets the
    // screen) and whatever the panel shipped with on desktop; a rail the user
    // has explicitly touched keeps their choice either way, because
    // defaultCollapsed only applies while that rail is untouched.
    for (const [panelId, toggleId, label, stateKey, side, defaultOnDesktop] of INNER_SIDEBARS) {
      initSidebarToggle(panelId, toggleId, label, stateKey, isMobileViewport || defaultOnDesktop, side);
    }
    // The main left sidebar is a drawer on mobile only; never leave it open
    // across a layout change.
    document.body.classList.remove('sidebar-open');
  };
  (mq.addEventListener ? mq.addEventListener('change', apply) : mq.addListener(apply));
  apply();
}

// Touch devices have no hover, so message tools (copy / edit / speak / retry)
// must be visible by default; CSS gates this behind body.has-touch.
function initTouchAffordances() {
  if (!('ontouchstart' in window) && !(navigator.maxTouchPoints > 0)) return;
  document.body.classList.add('has-touch');
}



function getBigChatSubagentsCurrentWidth(panel) {
  const inlineWidth = parseFloat(panel.style.width);
  if (Number.isFinite(inlineWidth) && inlineWidth > 0) return inlineWidth;
  const measuredWidth = panel.getBoundingClientRect().width;
  return measuredWidth > 0 ? measuredWidth : normalizeBigChatSubagentsWidth(state.bigChatSubagentsWidth);
}

function getBigChatSubagentsMaxWidth(panel, basisWidth) {
  const layout = panel.closest('.bigchat-layout');
  const main = panel.previousElementSibling && panel.previousElementSibling.classList.contains('bigchat-main')
    ? panel.previousElementSibling : null;
  const mainWidth = main ? main.getBoundingClientRect().width : 0;
  const layoutWidth = layout ? layout.clientWidth : window.innerWidth;
  
  const available = mainWidth > 0
    ? basisWidth + mainWidth - BIG_CHAT_SUBAGENTS_MIN_MAIN_WIDTH
    : layoutWidth - BIG_CHAT_SUBAGENTS_MIN_MAIN_WIDTH;
  return Math.min(BIG_CHAT_SUBAGENTS_MAX_WIDTH, Math.max(BIG_CHAT_SUBAGENTS_MIN_WIDTH, Math.floor(available)));
}

function setBigChatSubagentsWidth(width, persist = false) {
  const panel = document.getElementById('bigChatSubagentsPanel');
  const handle = document.getElementById('bigChatSubagentsResizeHandle');
  if (!panel) return BIG_CHAT_SUBAGENTS_DEFAULT_WIDTH;
  const basisWidth = getBigChatSubagentsCurrentWidth(panel);
  const maxWidth = getBigChatSubagentsMaxWidth(panel, basisWidth);
  const nextWidth = Math.min(maxWidth, normalizeBigChatSubagentsWidth(width));
  panel.style.width = `${nextWidth}px`;
  if (handle) {
    handle.setAttribute('aria-valuemin', String(BIG_CHAT_SUBAGENTS_MIN_WIDTH));
    handle.setAttribute('aria-valuemax', String(maxWidth));
    handle.setAttribute('aria-valuenow', String(nextWidth));
  }
  if (persist) {
    state.bigChatSubagentsWidth = nextWidth;
    saveState();
  }
  return nextWidth;
}

function initBigChatSubagentsResize() {
  const panel = document.getElementById('bigChatSubagentsPanel');
  const handle = document.getElementById('bigChatSubagentsResizeHandle');
  if (!panel || !handle) return;

  setBigChatSubagentsWidth(state.bigChatSubagentsWidth, false);
  let drag = null;

  const finishDrag = (cancelled = false) => {
    if (!drag) return;
    const session = drag;
    drag = null;
    const width = cancelled ? session.startWidth : getBigChatSubagentsCurrentWidth(panel);
    setBigChatSubagentsWidth(width, !cancelled);
    panel.classList.remove('resizing');
    handle.classList.remove('dragging');
    document.body.classList.remove('bigchat-subagents-resizing');
    if (handle.hasPointerCapture && handle.hasPointerCapture(session.pointerId)) {
      try { handle.releasePointerCapture(session.pointerId); } catch (_) {}
    }
  };

  handle.addEventListener('pointerdown', (event) => {
    if (event.button !== 0 || panel.classList.contains('collapsed')) return;
    const main = panel.previousElementSibling && panel.previousElementSibling.classList.contains('bigchat-main')
      ? panel.previousElementSibling : null;
    const startWidth = getBigChatSubagentsCurrentWidth(panel);
    const maxWidth = getBigChatSubagentsMaxWidth(panel, startWidth);
    drag = { pointerId: event.pointerId, startX: event.clientX, startWidth, maxWidth };
    panel.classList.add('resizing');
    handle.classList.add('dragging');
    document.body.classList.add('bigchat-subagents-resizing');
    handle.setAttribute('aria-valuemax', String(maxWidth));
    try { handle.setPointerCapture(event.pointerId); } catch (_) {}
    event.preventDefault();
  });
  handle.addEventListener('pointermove', (event) => {
    if (!drag || event.pointerId !== drag.pointerId) return;
    const width = Math.min(drag.maxWidth, Math.max(BIG_CHAT_SUBAGENTS_MIN_WIDTH,
      drag.startWidth + drag.startX - event.clientX));
    setBigChatSubagentsWidth(width, false);
  });
  handle.addEventListener('pointerup', (event) => {
    if (drag && event.pointerId === drag.pointerId) finishDrag(false);
  });
  handle.addEventListener('pointercancel', (event) => {
    if (drag && event.pointerId === drag.pointerId) finishDrag(true);
  });
  handle.addEventListener('lostpointercapture', () => finishDrag(false));
  handle.addEventListener('keydown', (event) => {
    if (panel.classList.contains('collapsed')) return;
    const current = getBigChatSubagentsCurrentWidth(panel);
    const maxWidth = getBigChatSubagentsMaxWidth(panel, current);
    let next = current;
    if (event.key === 'ArrowLeft') next = current + 16;
    else if (event.key === 'ArrowRight') next = current - 16;
   else if (event.key === 'Home') next = BIG_CHAT_SUBAGENTS_MIN_WIDTH;
    else if (event.key === 'End') next = maxWidth;
    else return;
    event.preventDefault();
    setBigChatSubagentsWidth(Math.min(maxWidth, Math.max(BIG_CHAT_SUBAGENTS_MIN_WIDTH, next)), true);
  });
  window.addEventListener('resize', () => {
     if (!drag) setBigChatSubagentsWidth(state.bigChatSubagentsWidth, false);
  });
}




function buildPresetToolHistory(preset, newMessage) {
  const msgs = [];
  if (presetKeepsHistory(preset)) {
    const conv = getConversation(preset) || [];
    const max = state.apiSettings.maxHistory || 0;
    const usable = conv.filter(m => !m.pending && !m.error && m.content);
    const slice = max > 0 ? usable.slice(-max) : usable;
    for (const m of slice) msgs.push({ role: m.role, content: m.content });
  }
  msgs.push({ role: 'user', content: newMessage });
  return msgs;
}


async function retryPresetForBigChat(preset, args, settings) {
  if (!preset || !CHARACTERS.some(c => c[0] === preset)) {
    return { ok: false, content: `ERROR: unknown or missing preset "${preset}"` };
  }
  const conv = getConversation(preset);
  let lastAssistant = -1;
  for (let i = conv.length - 1; i >= 0; i--) { if (conv[i].role === 'assistant') { lastAssistant = i; break; } }
  if (lastAssistant === -1) {
    return { ok: false, content: `ERROR: ${preset} has not replied yet — use call_preset first.` };
  }

  
  const oldMsg = ensureMsgVersions(conv[lastAssistant]);
  const carry = (oldMsg.versions || []).slice();
  const rejected = oldMsg.content || '';

  
  const history = conv.slice(0, lastAssistant)
    .filter(m => !m.pending && !m.error && m.content)
    .map(m => ({ role: m.role, content: m.content }));

  const feedback = (args.feedback || '').trim();
  if (feedback) {
    history.push({ role: 'assistant', content: rejected });
    history.push({ role: 'user', content: `That response was not suitable. ${feedback}\n\nPlease redo your previous reply, addressing this. Do not repeat the rejected wording.` });
  }

  const retrySettings = { ...settings };
  if (typeof args.temperature === 'number') retrySettings.temperature = Math.max(0, Math.min(2, args.temperature));
  else retrySettings.temperature = Math.max(0, Math.min(2, (settings.temperature == null ? 1 : settings.temperature) + 0.2));

  const result = await callApi(preset, history, retrySettings);
  if (!result.ok) return { ok: false, content: `ERROR: ${result.error}` };

  
  conv.splice(lastAssistant, conv.length - lastAssistant, {
    role: 'assistant',
    content: result.content,
    reasoning: result.reasoning || '',
    timestamp: new Date().toISOString(),
    elapsed: result.elapsed,
    model: result.model || null,
    source: 'big-chat',
    toolCall: true,
    versions: carry.concat([{ content: result.content, reasoning: result.reasoning || '', timestamp: new Date().toISOString(), model: result.model || null }]),
    activeVersion: carry.length,
  });
  saveState();
  renderChatSidebar(); renderChatMessages(); renderChatThreadSelector();

  const clean = settings.stripToolReasoning !== false ? stripReasoningText(result.content) : result.content;
  return { ok: true, model: result.model || null, content: `${preset} redid its reply${feedback ? ' with your feedback' : ''}:\n\n${clean}` };
}








function threadTasks(t) { if (!Array.isArray(t.tasks)) t.tasks = []; return t.tasks; }
function renderTaskList(t) {
  const tasks = threadTasks(t);
  if (!tasks.length) return 'The task list is empty.';
  return tasks.map((x, i) => `${i + 1}. [${x.done ? 'x' : ' '}] ${x.text}`).join('\n');
}
function applyTaskOp(t, a) {
  const tasks = threadTasks(t);
  const op = (a.op || 'list').toLowerCase();
  if (op === 'set') {
    const items = Array.isArray(a.items) ? a.items :  String(a.items || '').split('\n');
    t.tasks = items.map(x => String(x).trim()).filter(Boolean).map(text => ({ text, done: false }));
    return `Task list set (${t.tasks.length} items).\n${renderTaskList(t)}`;
  }
  if (op === 'add') {
    const items = Array.isArray(a.items) ? a.items : [a.items || a.text];
    for (const it of items) { const v = String(it || '').trim(); if (v) tasks.push({ text: v, done: false }); }
    return `Added.\n${renderTaskList(t)}`;
  }
  if (op === 'done' || op === 'undone') {
    const n = parseInt(a.index);
    if (!n || n < 1 || n > tasks.length) return `No task ${a.index}. Current list:\n${renderTaskList(t)}`;
    tasks[n - 1].done = (op === 'done');
    return `Marked ${n} ${op === 'done' ? 'complete' : 'incomplete'}.\n${renderTaskList(t)}`;
  }
  if (op === 'clear') { t.tasks = []; return 'Task list cleared.'; }
  return renderTaskList(t);
}




const bigChatTasksUi = {}; 
function bigChatTasksUiState(threadId) {
  if (!bigChatTasksUi[threadId]) bigChatTasksUi[threadId] = { open: true };
  return bigChatTasksUi[threadId];
}


function bumpBigChatTasksPopup() {
  const ui = bigChatTasksUiState(getBigChatData().activeThreadId);
  ui.open = true;
  renderBigChatTasksPopup();
}
function renderBigChatTasksPopup() {
  const pop = document.getElementById('bigChatTasksPopup');
  if (!pop) return;
  const tid = getBigChatData().activeThreadId;
  const tasks = threadTasks(getActiveBigChatThread());
  const ui = bigChatTasksUi[tid];
  if (!tasks.length) { pop.hidden = true; return; }
  const open = tasks.filter(x => !x.done).length;
  const done = tasks.length - open;
  const pct = tasks.length ? Math.round((done / tasks.length) * 100) : 0;
  pop.hidden = false;
  const pillCount = document.getElementById('bigChatTasksPillCount');
  if (pillCount) pillCount.textContent = `${done}/ ${tasks.length} done`;
  const card = document.getElementById('bigChatTasksCard');
  
  
  const showCard = ui ? !!ui.open : true;
  card.hidden = !showCard;
  
  
  const pill = document.getElementById('bigChatTasksPill');
  if (pill) pill.style.display = showCard ? 'none' : '';
  const minBtn = document.getElementById('bigChatTasksMin');
  if (minBtn) minBtn.textContent = showCard ? '▾' : '▸';
  const prog = document.getElementById('bigChatTasksProgress');
  if (prog) prog.textContent = `${done}/${tasks.length} · ${pct}%`;
  const body = document.getElementById('bigChatTasksBody');
  if (body) {
    body.innerHTML = tasks.map((x, i) =>
      `<label class="bc-task-row"><input type="checkbox" data-toggle="${i}" ${x.done ? 'checked' : ''}><span>${escapeHtml(x.text)}</span></label>`
    ).join('') || '<div style="font-size:11px;color:var(--text-muted);">No tasks yet.</div>';
    body.querySelectorAll('input[data-toggle]').forEach(cb => {
      cb.onchange = () => {
        const i = parseInt(cb.dataset.toggle, 10);
        const list = threadTasks(getActiveBigChatThread());
        if (list[i]) { list[i].done = cb.checked; saveState(); renderBigChatTasksPopup(); }
      };
    });
  }
}


function modelPricing(slug) {
  const m = getCatalogModel(bareModelSlug(slug));
  return m ? m.pricing : { prompt: 0, completion: 0 };
}
function estimateCallCost(model, promptTokens, completionTokens) {
  const p = modelPricing(model);
  return (promptTokens * (p.prompt || 0)) + (completionTokens * (p.completion || 0));
}




// Where the kept tail should begin when compacting: walk back from the newest
// message until the tail budget (or the message-count cap) is spent, then make
// sure the tail does not start on a tool result. Returns the start index.
const COMPACT_KEEP_TAIL_MAX = 8;
function compactTailStart(msgs, budgetTokens) {
  let tokens = 0;
  let count = 0;
  let start = msgs.length;
  for (let i = msgs.length - 1; i >= 1; i--) {
    if (count >= COMPACT_KEEP_TAIL_MAX) break;
    const cost = estimateMessagesTokens([msgs[i]]);
    // Always keep the newest exchange whole, even when a single message alone
    // exceeds the budget — a tail that stops mid-exchange is worse than a big one.
    if (count >= 2 && tokens + cost > budgetTokens) break;
    tokens += cost;
    count++;
    start = i;
  }
  // A tool result must never open the tail: its assistant tool_calls message is
  // the one being summarised away, and the API rejects the orphaned shape.
  while (start < msgs.length && msgs[start].role === 'tool') start++;
  return start;
}

async function compactThread(t, model, settings, setStatus, ctxLimit) {
  const msgs = t.messages.filter(m => !m.streaming);
  
  // How much of the tail is kept whole is a *budget*, not a message count.
  // Keeping a fixed eight messages left three consecutive "compacted" requests
  // still above the very trigger they were compacting for, because the newest
  // eight messages were eight 42–56 KB file reads.
  const tailBudget = Math.max(6000, Math.floor((ctxLimit || 0) * 0.4) || 24000);
  const keepFrom = compactTailStart(msgs, tailBudget);
  if (keepFrom <= 1) return false;
  const head = msgs[0];
  const tail = msgs.slice(keepFrom);
  const middle = msgs.slice(1, keepFrom);
  if (!middle.length) return false;

  setStatus && setStatus('Compacting context…');
  const parts = middle.map(m => {
    // Give the summarizer more than a stub, and mark every cut so it knows
    // what it is NOT seeing. Summarizing silently-lossy input produced
    // summaries that dropped file paths and command outcomes.
    if (m.role === 'tool') return `[tool ${m.toolName || m.preset || ''}] ${truncateWithNote(String(m.content || ''), 4000)}`;
    const calls = (m.toolCalls || []).map(tc => `calls ${tc.name}(${JSON.stringify(tc.args || {}).slice(0, 300)})`).join('; ');
    return `[${m.role}] ${truncateWithNote(String(m.content || ''), 2500)}${calls ? ' | ' + calls : ''}`;
  });
  // Total budget: keep the most recent messages whole rather than shaving
  // every message uniformly (uniform clipping is what made summaries lossy).
  const TRANSCRIPT_BUDGET = 120000;
  let transcript = parts.join('\n');
  if (transcript.length > TRANSCRIPT_BUDGET) {
    const kept = [];
    let used = 0;
    for (let i = parts.length - 1; i >= 0; i--) {
      const len = parts[i].length + 1;
      if (used + len > TRANSCRIPT_BUDGET && kept.length) break;
      kept.unshift(parts[i]);
      used += len;
    }
    transcript = `[… ${parts.length - kept.length} older messages omitted before this point]\n` + kept.join('\n');
  }

  const prompt = [
    { role: 'system', content: 'You compress an agent transcript. Produce a dense factual summary that lets the agent continue without re-reading the original. Preserve: the goal, decisions made, files created or modified with their paths, commands run and their outcomes, errors hit and fixes applied, and anything still outstanding. Use terse bullets. No preamble.' },
    { role: 'user', content: `Summarise this transcript segment:\n\n${transcript}` },
  ];
  const r = await executeWithRoutingAndRetries({
    modelsToTry: [model],
    settings,
    forcedProvider: null,
    abortSignal: null,
    onDelta: null,
    isBigChat: false,
    callOnceFn: async (modelStr, provider) => await callBigChatApi({
      model: modelStr,
      messages: prompt,
      systemPrompt: '',
      tools: null,
      settings,
      providerOverride: provider,
    }),
  });
  if (!r.ok) return false;
  const summary = (r.body.choices?.[0]?.message?.content || '').trim();
  if (!summary) return false;

  t.messages = [
    head,
    { role: 'assistant', content: `📦 **Context compacted** — earlier steps summarised:\n\n${summary}`, compacted: true, replaced: middle.length },
    ...tail,
  ];
  t.compactions = (t.compactions || 0) + 1;
  return true;
}


function isTransient(result) {
  if (!result || result.ok) return false;
  if (result.aborted) return false;
  if (result.timedOut) return true; // per-request timeout — transient, not a user stop
  const s = result.httpStatus;
  if (s === 429 || (s >= 500 && s < 600)) return true;
  if (isNetFailError(result)) return true;
  return /timeout|network|fetch failed|ECONN|socket/i.test(result.error || '');
}




function providerExportLabel(slug) {
  const s = (slug || '').trim();
  if (!s) return '';
  const lower = s.toLowerCase();
  const configured = (state.apiSettings.providers || []).find(p => (p.slug || '').trim().toLowerCase() === lower);
  if (configured && configured.name && configured.name.trim()) return configured.name.trim();
  return providerDisplayName(s);
}

// Fallback badge: shown on assistant bubbles when the request had to fall back
// to another model or provider. Hovering reveals every model/provider pair that
// was tried, in order, with each attempt's outcome.
function formatAttemptedPairs(pairs) {
  const list = Array.isArray(pairs) ? pairs : [];
  if (!list.length) return '';
  return list.map((a, i) => {
    const model = bareModelSlug(a.model) || String(a.model || '?');
    const provider = a.provider ? providerExportLabel(a.provider) : 'Auto';
    const outcome = a.ok ? '✓ succeeded' : `✗ ${String(a.error || 'failed').slice(0, 90)}`;
    return `${i + 1}. ${model} — ${provider}: ${outcome}`;
  }).join('\n');
}
function fallbackBadgeHtml(msg) {
  const pairs = formatAttemptedPairs(msg && msg.attemptedPairs);
  if (msg && msg.fellBack && !pairs) return `<span class="fb-badge" title="This response used a fallback model or provider.">FALLBACK</span>`;
  if (!pairs) return '';
  const label = (msg && msg.fellBack) || (msg && msg.attemptedPairs && msg.attemptedPairs.length > 1) ? 'FALLBACK' : 'RETRY';
  return `<span class="fb-badge" title="Attempts (in order):\n${escapeHtml(pairs)}">⇄ ${label}</span>`;
}


function bigChatThreadToMarkdown(thread) {
  return bigChatThreadToMarkdownWithImages(thread, null, '');
}

// Multi-file export sink: collects text files (markdown) plus binary image
// files decoded from data: URLs, so an export can be written as a folder.
function createExportSink() {
  const files = [];
  const used = new Set();
  return {
    files,
    usedNames: used,
    addText(name, content) {
      files.push({ name, kind: 'text', content: String(content) });
      return name;
    },
    // nameHint: base name without extension; mimeHint: from the data URL.
    // Returns the file's relative name for markdown references, or null when
    // the caller should fall back to embedding the data URL inline.
    addImage(nameHint, dataUrl, mimeHint) {
      const m = /^data:([^;,]+)?(;base64)?,([\s\S]*)$/.exec(String(dataUrl || ''));
      if (!m || !m[3]) return null;
      let ext = String(mimeHint || m[1] || '').split('/').pop() || '';
      ext = ext.replace(/[^a-z0-9]/gi, '').toLowerCase().slice(0, 5);
      if (!ext) ext = 'png';
      // Drop a trailing image extension first so "shot.png" stays "shot.png"
      // instead of becoming "shot_png.png" once the decoded ext is appended.
      const safe = String(nameHint || 'image').trim().replace(/\.(png|jpe?g|gif|webp|bmp|svg)$/i, '').replace(/[^a-zA-Z0-9_-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60) || 'image';
      let name = `${safe}.${ext}`;
      for (let i = 2; used.has(name.toLowerCase()); i++) name = `${safe}-${i}.${ext}`;
      used.add(name.toLowerCase());
      files.push({ name, kind: 'image', base64: m[3] });
      return name;
    },
    // Total decoded byte size of collected images (transport sanity limit).
    get imageBytes() {
      let total = 0;
      for (const f of files) if (f.kind === 'image') total += Math.floor(f.base64.length * 3 / 4);
      return total;
    },
  };
}

// Markdown builder shared by every Big Chat export path. When sink is non-null,
// screenshots and image attachments are decoded into it and referenced by
// relative path; when it is null (or a payload cannot be decoded) the raw
// data URL is embedded inline exactly as before.
function bigChatThreadToMarkdownWithImages(thread, sink, imagesDir) {
  const stamp = new Date().toLocaleString();
  const msgs = thread.messages || [];
  const dirPrefix = imagesDir ? `${imagesDir}/` : '';
  let md = `# ${thread.name || 'Big Chat'}\n\n`;
  md += `**Exported:** ${stamp}  \n`;  if (thread.model) {
    let provStr = '';
    let lastProvider = '';
    for (let i = msgs.length - 1; i >= 0; i--) {
      if (msgs[i].role === 'assistant' && msgs[i].provider) { lastProvider = msgs[i].provider; break; }
    }
    if (lastProvider) {
      provStr = `  \n**Provider:** ${providerExportLabel(lastProvider)}`;
    } else {
      const modalInfo = getApiEndpointAndHeaders(thread.model, state.apiSettings);
      if (modalInfo.isModal) provStr = '  \n**Provider:** Modal.com (direct endpoint)';
      else if (modalInfo.isNvidia) provStr = '  \n**Provider:** NVIDIA (direct endpoint)';
      else if (modalInfo.isVercel) provStr = '  \n**Provider:** Vercel (direct endpoint)';
      else if (modalInfo.isInferx) provStr = '  \n**Provider:** Inferx.net (direct endpoint)';
    }
    md += `**Model:** \`${thread.model}\`${provStr}  \n`;
  }
  md += `**Messages:** ${msgs.filter(m => !m.streaming).length}\n\n`;
  if (thread.systemPrompt && thread.systemPrompt.trim()) {
    md += `## System Prompt\n\n\`\`\`\n${thread.systemPrompt.trim()}\n\`\`\`\n\n`;
  }
  md += `---\n\n`;

  // Shared helper: decode a data: URL into the sink and return a relative
  // markdown image reference, or fall back to inline embedding when no sink
  // was provided (or the payload is not a decodable base64 data URL).
  const addDataUrl = (base, dataUrl, label) => {
    const name = sink ? sink.addImage(base, dataUrl, '') : null;
    if (name) return `![${label}](${dirPrefix}${name})`;
    return `![${label}](${dataUrl})`;
  };

  for (const m of msgs) {
    if (m.streaming) continue;                      

    if (m.role === 'user') {
      md += `### 🧑 You\n\n${m.content || ''}\n\n`;
      const atts = (m.attachments || []).filter(a => a && a.name);
      for (const a of atts) {
        if (a.dataUrl && /^data:image\/(?:png|jpe?g|gif|webp);base64,/i.test(a.dataUrl)) {
          const label = String(a.name || 'attachment').replace(/\]\(|[\r\n]/g, '_');
          md += `${addDataUrl(a.name || 'attachment', a.dataUrl, label)}\n\n`;
        }
      }
      continue;
    }

    if (m.role === 'tool') {
      
      if (m.toolName) {
        md += `#### 🔧 Tool — \`${m.toolName}\`${m.ok === false ? ' *(error)*' : ''}\n\n`;
        if (m.content) md += `\`\`\`\n${m.content}\n\`\`\`\n\n`;
        if (m.image) md += `${addDataUrl(`${m.toolName || 'tool'}-screenshot`, m.image, `${m.toolName || 'tool'} screenshot`)}\n\n`;
        continue;
      }
      
      const info = CHARACTERS.find(c => c[0] === m.preset);
      const name = info ? info[1] : (m.preset || 'preset');
      md += `#### 🎭 ${name}${m.model ? ` — \`${m.model}\`` : ''}${m.ok === false ? ' *(error)*' : ''}\n\n`;
      md += `${m.content || ''}\n\n`;
      continue;
    }

    if (m.role === 'assistant') {
      if (m.error) { md += `### 🧠 Big Model\n\n**ERROR:** ${m.error}\n\n`; continue; }
      const bits = [];
      if (m.model) bits.push(`\`${m.model}\``);
      if (m.provider) bits.push(providerExportLabel(m.provider));
      if (m.elapsed != null) bits.push(`${m.elapsed.toFixed(1)}s`);
      md += `### 🧠 Big Model${bits.length ? ` · ${bits.join(' · ')}` : ''}\n\n`;
      if (m.reasoning && state.apiSettings.exportReasoning !== false) {
        md += `<details><summary>🧠 Thinking</summary>\n\n\`\`\`\n${m.reasoning}\n\`\`\`\n\n</details>\n\n`;
      }
      if (m.content) md += `${m.content}\n\n`;
      if (m.toolCalls && m.toolCalls.length) {
        for (const tc of m.toolCalls) {
          const args = JSON.stringify(tc.args || {}, null, 2);
          md += `> 🛠 **Calls \`${tc.name}\`**\n>\n> \`\`\`json\n${args.split('\n').map(l => '> ' + l).join('\n')}\n> \`\`\`\n\n`;
        }
      }
      continue;
    }
  }
  return md;
}

function slugifyName(s) {
  return String(s || 'chat').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'chat';
}

function localDateStr(d = new Date()) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function exportBigChatThread(threadId) {
  const bc = getBigChatData();
  const t = bc.threads[threadId || bc.activeThreadId];
  if (!t) { showToast('No chat to export', 'error'); return; }
  if (!(t.messages || []).length) { showToast('That chat has no messages yet', 'info'); return; }
  const base = `bigchat-${slugifyName(t.name)}-${localDateStr()}`;
  const sink = createExportSink();
  sink.addText(`${base}.md`, bigChatThreadToMarkdownWithImages(t, sink, 'images'));
  saveChatExportWithImages(base, sink);
}

function exportAllBigChatThreads() {
  const bc = getBigChatData();
  const threads = Object.values(bc.threads).filter(t => (t.messages || []).length);
  if (!threads.length) { showToast('No Big Chat messages to export', 'info'); return; }
  const base = `bigchat-all-${localDateStr()}`;
  const sink = createExportSink();
  let md = `# Big Chat — all threads\n\n**Exported:** ${new Date().toLocaleString()}  \n**Threads:** ${threads.length}\n\n`;
  md += threads.map(t => bigChatThreadToMarkdownWithImages(t, sink, 'images')).join('\n\n---\n\n');
  sink.addText(`${base}.md`, md);
  saveChatExportWithImages(base, sink);
}


function exportMarkdown() {
  if (state.turns.length === 0 && Object.keys(state.conversations).length === 0) { alert('Nothing to export.'); return; }
  const outputsOnly = state.apiSettings.exportOutputsOnly;
  let md = `# Clod Code - Export\n\nGenerated: ${new Date().toISOString()}\n\n`;
  md += `## Settings\n\n- Maintain history: ${state.apiSettings.maintainHistory ? 'ON' : 'OFF'}\n- Max history: ${state.apiSettings.maxHistory || 'unlimited'}\n- Export outputs only: ${outputsOnly ? 'ON' : 'OFF'}\n\n`;
  if (state.turns.length > 0) {
    md += `## Turns\n\n`;
    for (const turn of state.turns) {
      md += `---\n\n### Turn ${turn.turnNumber}\n\n**Started:** ${turn.startedAt}\n**Completed:** ${turn.completedAt || '(running)'}\n\n`;
      for (let i = 0; i < turn.outputs.length; i++) { const input = turn.inputs[i], out = turn.outputs[i]; md += `#### ${input.preset}\n\n**Status:** ${out.status} · **Elapsed:** ${out.elapsed != null ? out.elapsed.toFixed(1) + 's' : '—'}\n\n`; if (!outputsOnly) { md += `**Input:**\n\n\`\`\`\n${input.content}\n\`\`\`\n\n**Output:**\n\n`; } if (out.status === 'ok') md += `${out.content}\n\n`; else md += `**ERROR:** ${out.error}\n\n`; }
    }
  }
  if (Object.keys(state.conversations).length > 0) {
    md += `## Conversations\n\n`;
    for (const [preset, pd] of Object.entries(state.conversations)) {
      if (!pd || !pd.threads) continue;
      for (const [tid, t] of Object.entries(pd.threads)) {
        if (!t.messages || t.messages.length === 0) continue;
        md += `---\n\n### ${preset} / ${t.name || tid}\n\n`;
        for (const msg of t.messages) { if (outputsOnly && msg.role === 'user') continue; const time = new Date(msg.timestamp).toLocaleString(); const elapsedStr = msg.elapsed != null ? ` (${msg.elapsed.toFixed(1)}s)` : ''; md += `**${msg.role.toUpperCase()}** · ${time}${elapsedStr}:\n\n${msg.content}\n\n`; }
      }
    }
  }
  const latestTurnNumber = state.turns.length > 0 ? state.turns[state.turns.length - 1].turnNumber : 0;
  downloadFile(`openrouter_preset_runner_export_turn-${latestTurnNumber}.md`, md, 'text/markdown');
}

function exportJSON() {
  if (state.turns.length === 0 && Object.keys(state.conversations).length === 0) { alert('Nothing to export.'); return; }
  const data = { exportedAt: new Date().toISOString(), apiSettings: { ...state.apiSettings, apiKey: '***REDACTED***' }, turns: state.turns, conversations: state.conversations };
  downloadFile('openrouter_preset_runner_export.json', JSON.stringify(data, null, 2), 'application/json');
}

function downloadFile(filename, content, mime) {
  let body = content;
  if (mime === 'text/markdown' || /[.]md$/i.test(filename)) {
    body = '\uFEFF' + String(content);
  }
  const blob = new Blob([body], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
}

// ---- multi-file chat export (.md + images) ----------------------------------

// Decode a data: URL to raw bytes. Returns null for anything that is not a
// base64 data URL so callers can fall back to inline embedding.
function dataUrlToBytes(dataUrl) {
  const m = /^data:[^;,]+;base64,([\s\S]*)$/.exec(String(dataUrl || ''));
  if (!m) return null;
  const bin = atob(m[1]);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

// Persist a chat export with its collected images. Transport order:
//   1. Desktop (Electron): native save dialog picks the .md location; images
//      are written as sibling files in <chosen name>_images/ next to it.
//   2. Real workspace folder (Android port / browser with folder attached):
//      everything is written under the workspace via the existing workspace
//      bridge, then the .md is also downloaded through the normal path.
//   3. Memory-only / no bridge: plain .md download with data URLs inline —
//      exactly the pre-image-export behaviour, so nothing regresses.
async function saveChatExportWithImages(base, sink) {
  const mdFile = sink.files.find(f => f.kind === 'text');
  const mdText = mdFile ? mdFile.content : '';
  const images = sink.files.filter(f => f.kind === 'image');
  const mdName = `${base}.md`;

  const nw = (typeof window !== 'undefined' && window.desktopAgent && typeof window.desktopAgent.exportChatWithImages === 'function') ? window.desktopAgent : null;
  // Text-only exports keep the old silent-download behaviour — a save dialog
  // and an empty images folder would be pure noise.
  if (nw && images.length) {
    const files = [{ name: mdName, base64: btoa(unescape(encodeURIComponent('\uFEFF' + mdText))) }];
    for (const img of images) files.push({ name: `images/${img.name}`, base64: img.base64 });
    try {
      const r = await nw.exportChatWithImages({ baseName: base, files });
      if (r && r.ok) {
        const where = r.canceled ? 'Export canceled' : `Exported "${r.mdName || mdName}"${r.savedImages ? ` + ${r.savedImages} image${r.savedImages === 1 ? '' : 's'}` : ''}${r.dir ? ` → ${r.dir}` : ''}`;
        showToast(where, r.canceled ? 'info' : 'success');
        return;
      }
      // Handler missing or failed: fall through to the other transports.
    } catch (e) { /* fall through */ }
  }

  if (agentFS.usingReal && agentFS.rootPath && nw?.workspaceWriteBinary) {
    try {
      const dir = `chat-exports/${base}`;
      await nw.workspaceMkdir(agentFS.rootPath, `${dir}/images`);
      const ws = await nw.workspaceWrite(agentFS.rootPath, `${dir}/${mdName}`, '\uFEFF' + mdText);
      if (!ws.ok) throw new Error(ws.error || 'workspace write failed');
      let saved = 0;
      for (const img of images) {
        const r = await nw.workspaceWriteBinary(agentFS.rootPath, `${dir}/images/${img.name}`, img.base64);
        if (r.ok) saved++; else throw new Error(r.error || `could not write images/${img.name}`);
      }
      downloadFile(mdName, mdText, 'text/markdown');
      showToast(`Exported to workspace ${dir}/ (${saved} image${saved === 1 ? '' : 's'}) + .md download`, 'success');
      return;
    } catch (e) { showToast(`Workspace export failed (${e && e.message ? e.message : e}) — falling back to .md download`, 'error'); }
  }

  downloadFile(mdName, mdText, 'text/markdown');
  showToast(images.length ? `Exported "${mdName}" (no file access for images — ${images.length} image${images.length === 1 ? '' : 's'} embedded inline)` : `Exported "${mdName}"`, 'success');
}

function clearHistory() {
  if (!confirm('Clear ALL turn history and every individual chat conversation? This cannot be undone.')) return;
  clearBigChatSubagentActivities();
  state.turns = []; state.conversations = {}; state.bigChat = { threads: {}, activeThreadId: null }; nextTurnId = 1;
  workspaceVaultWipe(); agentFS.mem = {}; agentFS.dirs = {};
  saveState(); renderTurnList(); renderChatHistory(); renderChatSidebar(); renderChatMessages(); updateTurnIndicator(); updateBadges(); updateChatInputState();
  showToast('All turn and chat history cleared', 'success');
}

const TOAST_ICONS = { collapse: '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M1.5 6.5 5 3l3.5 3.5"/></svg>', expand: '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M1.5 3.5 5 7l3.5-3.5"/></svg>', close: '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M1.5 1.5l7 7M8.5 1.5l-7 7"/></svg>' };

function showToast(message, type = 'success') {
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;

  const body = document.createElement('div');
  body.className = 'toast-body';
  body.textContent = message;

  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = 'toast-btn toast-toggle';
  toggle.title = 'Expand';
  toggle.innerHTML = TOAST_ICONS.collapse;

  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'toast-btn toast-close';
  close.title = 'Dismiss';
  close.innerHTML = TOAST_ICONS.close;

  const tools = document.createElement('div');
  tools.className = 'toast-tools';
  tools.append(toggle, close);
  toast.append(body, tools);

  let collapsed = true;
  function applyMode() {
    toast.classList.toggle('collapsed', collapsed);
    toggle.innerHTML = collapsed ? TOAST_ICONS.collapse : TOAST_ICONS.expand;
    toggle.title = collapsed ? 'Expand' : 'Collapse';
  }
  toggle.addEventListener('click', e => { e.stopPropagation(); collapsed = !collapsed; applyMode(); });
  close.addEventListener('click', () => dismiss());

  function dismiss() {
    toast.style.transition = 'opacity 0.3s';
    toast.style.opacity = '0';
    setTimeout(() => toast.remove(), 300);
  }
  let container = document.getElementById('toast-container');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toast-container';
    document.body.appendChild(container);
  }
  container.appendChild(toast);
  applyMode();

  // Errors and warnings stay until dismissed; other toasts auto-hide after 4s.
  if (type !== 'error' && type !== 'warning') {
    setTimeout(dismiss, 4000);
  }
  if (type === 'error') {
    try { playRandomErrorSound(); } catch {}
  }
}


function notifyDesktop(title, body) {
  
  
  
  if (IS_DESKTOP) {
    if (!state.apiSettings.desktopNotifications) return;
    if (!window.desktopAgent || typeof window.desktopAgent.notify !== 'function') {
      console.warn('Notification bridge missing — update the desktop app.');
      return;
    }
    window.desktopAgent.notify({ title: String(title || 'Clod Code'), body: String(body || '') })
      .then(r => {
        if (r && r.ok === false && r.supported === false) {
          state._notifyUnsupported = true;
          refreshNotificationHint();
        }
      })
      .catch(err => console.warn('Native notification failed:', err));
    return;
  }

  
  if (!state.apiSettings.desktopNotifications) return;
  try {
    if (!('Notification' in window)) { state._notifyUnsupported = true; return; }
    if (Notification.permission === 'granted') {
      new Notification(String(title || 'Clod Code'), { body: String(body || '') });
    } else if (Notification.permission !== 'denied') {
     Notification.requestPermission().then(perm => {
        if (perm === 'granted') new Notification(String(title || 'Clod Code'), { body: String(body || '') });
        else if (perm === 'denied') { state._notifyUnsupported = true; refreshNotificationHint(); }
      }).catch(() => {});
    } else {
      state._notifyUnsupported = true;
      refreshNotificationHint();
    }
  } catch (e) {  }
}


function refreshNotificationHint() {
  const hint = document.getElementById('notificationsHint');
  if (!hint) return;
  const on = !!state.apiSettings.desktopNotifications;
  const unsupported = !!state._notifyUnsupported;
  const hasBridge = !!(IS_DESKTOP && window.desktopAgent && typeof window.desktopAgent.notify === 'function');
  const browserPerms  = (typeof Notification !== 'undefined') ? Notification.permission : 'denied';
  if (!on) hint.textContent = 'Off — no notifications will be shown.';
  else if (unsupported || (!IS_DESKTOP && browserPerms === 'denied'))
    hint.textContent = '⚠ Notifications are blocked / not supported in this environment. Check OS-level permission for this app.';
  else if (IS_DESKTOP && !hasBridge)
    hint.textContent = '⚠ Update the desktop app (main.js/preload.js) — this build does not have the native notification bridge.';
  else if (IS_DESKTOP) hint.textContent = '✓ On — native OS toasts when a run finishes. Click 🔔 Send test to verify.';
  else if (browserPerms === 'granted') hint.textContent = '✓ On — browser notifications when a run finishes. Click 🔔 Send test to verify.';
  else hint.textContent = 'On — you may need to grant notification permission. Click 🔔 Send test to verify.';
}


let _errorAudioUnlocked = false;
function _unlockErrorAudio() {
  if (_errorAudioUnlocked) return;
  _errorAudioUnlocked = true;
  try {
    const a = new Audio();
    a.volume = 0.001;
    a.play().catch(() => {});
  } catch {}
}
document.addEventListener('click', _unlockErrorAudio, { once: true, capture: true });
document.addEventListener('keydown', _unlockErrorAudio, { once: true, capture: true });

function getErrorSounds() {
  return Array.isArray(state.apiSettings.errorSounds) ? state.apiSettings.errorSounds : [];
}

function playRandomErrorSound() {
  try {
    const enabled = !!state.apiSettings.errorSoundsEnabled;
    const sounds = getErrorSounds();
    if (!enabled || !sounds.length) return;
    const vol = Math.max(0, Math.min(1, state.apiSettings.errorSoundVolume ?? 0.8));
    const pick = sounds[Math.floor(Math.random() * sounds.length)];
    if (!pick || !pick.dataUrl) return;
    const audio = new Audio(pick.dataUrl);
    audio.volume = vol;
    audio.play().catch(err => console.warn('Error sound play blocked:', err));
  } catch (e) {
    console.warn('playRandomErrorSound failed', e);
  }
}

function playErrorSoundById(id) {
  try {
    const sounds = getErrorSounds();
    const found = sounds.find(s => s.id === id) || sounds[0];
    if (!found) return;
    const vol = Math.max(0, Math.min(1, state.apiSettings.errorSoundVolume ?? 0.8));
    const audio = new Audio(found.dataUrl);
    audio.volume = vol;
    audio.play().catch(err => console.warn('Error sound play blocked:', err));
  } catch (e) { console.warn(e); }
}

function renderErrorSoundsList() {
  const list = document.getElementById('errorSoundsList');
  const count = document.getElementById('errorSoundsCount');
  if (!list) return;
  const savedScrollTop = list.scrollTop;
  const sounds = getErrorSounds();
  if (count) count.textContent = sounds.length ? `${sounds.length} sound${sounds.length === 1 ? '' : 's'} loaded` : 'No sounds added';
  if (!sounds.length) {
    list.innerHTML = `<div style="font-size:11px; color:var(--text-muted); padding:6px; border:1px dashed var(--border); border-radius:6px; text-align:center;">No error sounds yet. Click +Add sound(s) to upload mp3/wav/ogg files.</div>`;
    list.scrollTop = savedScrollTop;
    return;
  }
  list.innerHTML = sounds.map(s => {
    const sizeKB = s.dataUrl ? Math.round((s.dataUrl.length * 0.75) / 1024) : 0;
    return `<div style="display:flex; align-items:center; gap:8px; background:var(--bg-elev); border:1px solid var(--border); border-radius:6px; padding:6px 8px;">
      <span style="font-size:12px; flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${escapeHtml(s.name)}">${escapeHtml(s.name)}</span>
      <span style="font-size:10px; color:var(--text-muted); font-family:var(--mono);">${sizeKB ? sizeKB + ' KB' : ''}</span>
      <button type="button" class="small error-sound-play" data-id="${escapeHtml(s.id)}" title="Play this sound">▶</button>
      <button type="button" class="small error-sound-remove danger" data-id="${escapeHtml(s.id)}" title="Remove">×</button>
    </div>`;
  }).join('');
  list.scrollTop = savedScrollTop;
  list.querySelectorAll('.error-sound-play').forEach(btn => {
    btn.onclick = () => playErrorSoundById(btn.dataset.id);
  });
  list.querySelectorAll('.error-sound-remove').forEach(btn => {
    btn.onclick = () => {
      const id = btn.dataset.id;
      state.apiSettings.errorSounds = getErrorSounds().filter(s => s.id !== id);
      saveState();
      renderErrorSoundsList();
    };
  });
}

function initErrorSoundsEditor() {
  const enabledCb = document.getElementById('errorSoundsEnabledInput');
  const volInput = document.getElementById('errorSoundVolumeInput');
  const volLabel = document.getElementById('errorSoundVolumeLabel');
  const addBtn = document.getElementById('addErrorSoundBtn');
  const fileInput = document.getElementById('errorSoundFileInput');
  const clearBtn = document.getElementById('clearErrorSoundsBtn');
  const testBtn = document.getElementById('testErrorSoundBtn');

  if (enabledCb) {
    enabledCb.checked = !!state.apiSettings.errorSoundsEnabled;
    enabledCb.onchange = () => {
      state.apiSettings.erorSoundsEnabled = enabledCb.checked;
      saveState();
    };
  }
  if (volInput) {
    const v = Math.round((state.apiSettings.errorSoundVolume ?? 0.8) * 100);
    volInput.value = String(v);
    if (volLabel) volLabel.textContent = v + '%';
    volInput.oninput = () => {
      const val = parseInt(volInput.value) || 0;
      if (volLabel) volLabel.textContent = val + '%';
      state.apiSettings.errorSoundVolume = val / 100;
      saveState();
    };
  }
  if (addBtn && fileInput) {
    addBtn.onclick = () => fileInput.click();
    fileInput.onchange = async () => {
      const files = Array.from(fileInput.files || []);
      if (!files.length) return;
      for (const f of files) {
        if (!f.type.startsWith('audio/') && !/\.(mp3|wav|ogg|m4a|mp4|aac|flac)$/i.test(f.name)) continue;
        if (f.size > 5 * 1024 * 1024) {
          showToast(`Skipped ${f.name}: >5MB`, 'error');
          continue;
        }
        const dataUrl = await new Promise((res, rej) => {
          const r = new FileReader();
          r.onload = () => res(r.result);
          r.onerror = () => rej(r.error);
          r.readAsDataURL(f);
        }).catch(() => null);
        if (!dataUrl) continue;
        state.apiSettings.errorSounds = state.apiSettings.errorSounds || [];
        state.apiSettings.errorSounds.push({
          id: 'err_' + Math.random().toString(36).slice(2, 9),
          name: f.name,
          type: f.type || 'audio/*',
          dataUrl: dataUrl,
        });
      }
      fileInput.value = '';
      saveState();
      renderErrorSoundsList();
      showToast(`Added ${files.length} error sound${files.length === 1 ? '' : 's'}`, 'success');
    };
  }
  if (clearBtn) {
    clearBtn.onclick = () => {
      if (!getErrorSounds().length) return;
      if (!confirm('Remove all error sounds?')) return;
      state.apiSettings.errorSounds = [];
      saveState();
      renderErrorSoundsList();
      showToast('All error sounds cleared', 'success');
    };
  }
  if (testBtn) {
    testBtn.onclick = () => {
      if (!getErrorSounds().length) {
        showToast('No error sounds added yet', 'info');
        return;
      }
      playRandomErrorSound();
      showToast('Played random error sound', 'success');
    };
  }
  renderErrorSoundsList();
}

function escapeHtml(s) { if (s == null) return ''; return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }
function escapeHtmlBase64(s) { if (s == null) return ''; return btoa(unescape(encodeURIComponent(s))); }


function markdownToHtml(text) {
  if (text == null) return '';
  
  let html = escapeHtml(String(text));

  
  const codeBlocks = [];
  html = html.replace(/```(\w*)\n([\s\S]*?)```/g, function(_, lang, code) {
    codeBlocks.push('<pre><code class="' + (lang ? 'language-' + escapeHtml(lang) : '') + '">' + code + '</code></pre>');
    return '\x00CODE' + (codeBlocks.length - 1) + '\x00';
  });

  
  const inlineCodes = [];
  html = html.replace(/`([^`]+)`/g, function(_, code) {
    inlineCodes.push('<code>' + code + '</code>');
    return '\x00ICODE' + (inlineCodes.length - 1) + '\x00';
  });

  
  html = html.replace(/^(---|\*\*\*|___)\s*$/gm, '<hr>');

  
  html = html.replace(/^#### (.+)$/gm, '<h4>$1</h4>');
  html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');

  
  
  html = html.replace(/^(?:&gt; ?[^\n]*\n?)+/gm, function(block) {
    var lines = block.split('\n');
    var content = lines.map(function(line) {
      return line.replace(/^&gt; ?/, '');
    }).join('<br>');
    return '<blockquote>' + content + '</blockquote>';
  });

  
  html = html.replace(/^(?:[-*+] .+\n?)+/gm, function(block) {
    var items = block.split('\n').filter(Boolean).map(function(line) {
      return '<li>' + line.replace(/^[-*+] /, '') + '</li>';
    }).join('');
    return '<ul>' + items + '</ul>';
  });

  
  html = html.replace(/^(?:\d+\. .+\n?)+/gm, function(block) {
    var items = block.split('\n').filter(Boolean).map(function(line) {
      return '<li>' + line.replace(/^\d+\. /, '') + '</li>';
    }).join('');
    return '<ol>' + items + '</ol>';
  });

  
  var parts = html.split(/\n\n+/);
  html = parts.map(function(p) {
    p = p.trim();
    if (!p) return '';
    
    if (/^<(h[1-4]|ul|ol|li|blockquote|pre|hr|div|table)/.test(p)) return p;
    
    return '<p>' + p.replace(/\n/g, '<br>') + '</p>';
  }).join('\n');

  
  html = html.replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>');
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
  html = html.replace(/___(.+?)___/g, '<strong><em>$1</em></strong>');
  html = html.replace(/__(.+?)__/g, '<strong>$1</strong>');
  
  html = html.replace(/(^|\s)_(\S(?:.*?\S)?)_(?=\s|[.,;:!?)]|$)/g, '$1<em>$2</em>');
  html = html.replace(/~~(.+?)~~/g, '<del>$1</del>');

  
  html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');

  
  html = html.replace(/\x00ICODE(\d+)\x00/g, function(_, i) { return inlineCodes[+i]; });
  html = html.replace(/\x00CODE(\d+)\x00/g, function(_, i) { return codeBlocks[+i]; });

  return html;
}

// Rendered-markdown cache keyed on the owning message/turn object and
// invalidated by comparing the source string. Every full re-render of a thread
// (each step, each tool result, each version switch) used to re-run
// markdownToHtml's ~20 regex passes over EVERY message's content, so painting a
// long conversation cost more the longer it ran. Now only the message being
// streamed or edited re-parses; finished messages replay their cached HTML.
const markdownHtmlCache = new WeakMap();
function cachedMarkdownHtml(owner, text) {
  const src = text == null ? '' : String(text);
  if (!owner) return markdownToHtml(src);
  const hit = markdownHtmlCache.get(owner);
  if (hit && hit.src === src) return hit.html;
  const html = markdownToHtml(src);
  markdownHtmlCache.set(owner, { src, html });
  return html;
}


