// Big Chat controls toggle (collapsible model controls)
(function initBigChatControlsToggle() {
  const toggleBtn = document.getElementById('bigChatControlsToggleBtn');
  const body = document.getElementById('bigChatControlsBody');
  if (!toggleBtn || !body) return;

  // Always start expanded; user can collapse via the toggle button
  body.classList.remove('collapsed');
  toggleBtn.setAttribute('aria-expanded', 'true');

  toggleBtn.onclick = () => {
    const collapsed = body.classList.toggle('collapsed');
    toggleBtn.setAttribute('aria-expanded', String(!collapsed));
  };

  // Update the summary line whenever the model/provider changes
  function refreshSummary() {
    const summaryEl = document.getElementById('bigChatControlsSummary');
    if (!summaryEl) return;
    const model = (document.getElementById('bigModelSelect') || {}).value || '';
    const provider = (document.getElementById('bigProviderSelect') || {}).value || '';
    const preset = (document.getElementById('bigPresetSelect') || {}).value || '';
    const parts = [];
    if (model) parts.push(model.replace(/^[^/]+\//, ''));
    else parts.push('⚡ Auto');
    if (provider && provider !== 'Auto (per-model override)') parts.push(provider);
    if (preset) parts.push(preset);
    summaryEl.textContent = parts.length ? parts.join(' · ') : 'Model controls';
  }
  window.refreshBigChatControlsSummary = refreshSummary;
  document.getElementById('bigModelSelect')?.addEventListener('change', refreshSummary);
  document.getElementById('bigProviderSelect')?.addEventListener('change', refreshSummary);
  document.getElementById('bigPresetSelect')?.addEventListener('change', refreshSummary);
  refreshSummary();
})();

