function persistWorkspaceOnClose() {
  try { persistActiveWorkspace(); } catch {}
}
// ---- Hard-kill durability for the Big Chat orchestrator ----
// The orchestrator's in-flight response lives in the thread as a streaming
// message, but the thread was only persisted at step boundaries — a crash or
// power loss mid-stream lost the whole response. Stream deltas now debounce a
// saveState() so the partial reply survives; the load-time sanitizer turns any
// dangling streaming message into a recovered reply (and closes dangling
// tool_calls shapes the API would reject on a re-send).
const BIGCHAT_LIVE_SAVE_MS = 2500;
let bigChatLiveSaveTimer = null;
let bigChatLiveSaveAt = 0;
function scheduleBigChatLiveSave() {
  if (bigChatLiveSaveTimer) return;
  bigChatLiveSaveTimer = setTimeout(() => {
    bigChatLiveSaveTimer = null;
    try { saveState(); bigChatLiveSaveAt = Date.now(); } catch {}
  }, BIGCHAT_LIVE_SAVE_MS);
}
function flushBigChatLiveSave() {
  if (bigChatLiveSaveTimer) { clearTimeout(bigChatLiveSaveTimer); bigChatLiveSaveTimer = null; }
  try { saveState(); bigChatLiveSaveAt = Date.now(); } catch {}
}
// Convert every dangling streaming message left by a hard kill into a real
// (non-streaming) assistant message carrying what was streamed before the
// crash, plus a marker the UI shows as a "recovered" badge. Also close
// assistant tool_calls messages that lost their tool results — the API
// rejects that shape on the next request.
function sanitizeBigChatThreadAfterCrash(t) {
  if (!t || !Array.isArray(t.messages) || !t.messages.length) return false;
  let changed = false;
  const out = [];
  for (let i = 0; i < t.messages.length; i++) {
    const m = t.messages[i];
    if (m && m.streaming) {
      const content = String(m.content || '');
      const reasoning = String(m.reasoning || '');
      if (!content.trim() && !reasoning.trim()) { changed = true; continue; } // nothing arrived — drop
      out.push({ role: 'assistant', content, reasoning, recovered: true });
      changed = true;
      continue;
    }
    if (m && m.role === 'assistant' && Array.isArray(m.toolCalls) && m.toolCalls.length) {
      out.push(m);
      // Did the tool results for this call make it to disk? (The API needs a
      // tool message for every tool_call id.)
      const need = new Set(m.toolCalls.map(tc => String(tc && tc.id || '')));
      for (let j = i + 1; j < t.messages.length; j++) {
        const n = t.messages[j];
        if (n && n.role === 'tool' && need.has(String(n.tool_call_id || ''))) need.delete(String(n.tool_call_id || ''));
      }
      if (need.size) {
        for (const tcId of need) {
          out.push({ role: 'tool', tool_call_id: tcId, content: '(no result recorded — the app shut down before this tool ran; re-issue it if still needed)', ok: false, toolName: 'unknown' });
        }
        changed = true;
      }
      continue;
    }
    out.push(m);
  }
  if (!changed) return false;
  t.messages = out;
  return true;
}
function sanitizeBigChatThreadsAfterCrash() {
  const bc = state.bigChat;
  if (!bc || !bc.threads) return false;
  let any = false;
  for (const t of Object.values(bc.threads)) {
    try { if (sanitizeBigChatThreadAfterCrash(t)) any = true; } catch {}
  }
  return any;
}
window.addEventListener('pagehide', persistWorkspaceOnClose);
