// Auto-pause live sub-agents before the window goes away: the first close
// attempt holds the window open while every running sub-agent gracefully
// parks (finishes its current step, saves its transcript + paused flag), then
// the close proceeds. A second close click (or a 120s cap) force-closes.
window.addEventListener('beforeunload', (e) => {
  flushAllLiveSubagentTranscripts();
  if (subagentCloseWindDownForce) { subagentCloseWindDownForce = false; return; }
  if (!liveSubagentCount()) return;
  if (subagentCloseWindDown) {
    // User insisted (second close click): force-close without waiting.
    if (subagentCloseWindDown.timer) clearTimeout(subagentCloseWindDown.timer);
    subagentCloseWindDown = null;
    return;
  }
  e.preventDefault();
  e.returnValue = false;
  beginSubagentCloseWindDown('close');
});
window.addEventListener('pagehide', flushAllLiveSubagentTranscripts);
// Orchestrator counterpart: capture the in-flight reply if the page is being
// torn down outside the graceful close wind-down (hard kill, crash, reload).
window.addEventListener('pagehide', flushBigChatLiveSave);
// A debounced save that never fired would lose the last edit (see saveStateSoon).
window.addEventListener('pagehide', flushStateSaveSoon);
window.addEventListener('beforeunload', flushStateSaveSoon);


function autoGrowTextarea(el) {
  if (!el) return;
  el.style.height = 'auto';
  const max = Math.round(window.innerHeight * 0.45);
  const next = Math.min(el.scrollHeight, max);
  el.style.height = next + 'px';
  el.style.overflowY = el.scrollHeight > max ? 'auto' : 'hidden';
}
function initAutoGrow(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const grow = () => autoGrowTextarea(el);
  el.addEventListener('input', grow);
  
  el.addEventListener('paste', () => setTimeout(grow, 0));
  el.addEventListener('cut', () => setTimeout(grow, 0));
  window.addEventListener('resize', grow);
  grow();
}



function initInputScrollNav(inputId, topBtnId, bottomBtnId) {
  const ta = document.getElementById(inputId);
  const upBtn = document.getElementById(topBtnId);
  const downBtn = document.getElementById(bottomBtnId);
  if (!ta || !upBtn || !downBtn) return;

  const refresh = () => {
    const scrollable = ta.scrollHeight - ta.clientHeight;
    const canScroll = scrollable > 4;
    upBtn.disabled = !canScroll || ta.scrollTop <= 2;
    downBtn.disabled = !canScroll || ta.scrollTop >= scrollable - 2;
    
    const vis = canScroll ? '' : 'none';
    upBtn.style.display = vis; downBtn.style.display = vis;
  };

  
  const jump = (toEnd) => {
    ta.focus();
    const pos = toEnd ? ta.value.length : 0;
    try { ta.setSelectionRange(pos, pos); } catch {}
    ta.scrollTop = toEnd ? ta.scrollHeight : 0;
    refresh();
  };
  upBtn.onclick = (e) => { e.preventDefault(); jump(false); };
  downBtn.onclick = (e) => { e.preventDefault(); jump(true); };

  ta.addEventListener('scroll', refresh, { passive: true });
  ta.addEventListener('input', () => setTimeout(refresh, 0));
  ta.addEventListener('keyup', refresh);
  ta.addEventListener('click', refresh);
  window.addEventListener('resize', refresh);
  refresh();
}


function initScrollNav(paneId, topBtnId, bottomBtnId) {
  const pane = document.getElementById(paneId);
  const topBtn = document.getElementById(topBtnId);
  const bottomBtn = document.getElementById(bottomBtnId);
  if (!pane || !topBtn || !bottomBtn) return;
  const refresh = () => {
    const scrollable = pane.scrollHeight - pane.clientHeight;
    if (scrollable < 60) { topBtn.classList.remove('show'); bottomBtn.classList.remove('show'); return; }
    topBtn.classList.toggle('show', pane.scrollTop > 40);
    bottomBtn.classList.toggle('show', pane.scrollTop < scrollable - 40);
  };
  topBtn.onclick = () => pane.scrollTo({ top: 0, behavior: 'smooth' });
  bottomBtn.onclick = () => pane.scrollTo({ top: pane.scrollHeight, behavior: 'smooth' });
  pane.addEventListener('scroll', refresh, { passive: true });
  
  if (window.MutationObserver) new MutationObserver(refresh).observe(pane, { childList: true, subtree: true });
  window.addEventListener('resize', refresh);
  refresh();
}

