// ===================== AGENT BROWSER (Web Browser tab) =====================
// Real Chromium guests (Electron <webview>, each a separate renderer process)
// that the user can drive manually AND the agent can drive through the
// browser_* tools. Multiple tabs are supported: each tab is its own <webview>
// with its own page, history and cached snapshot. The agent's tools resolve
// elements by the data-agent-ref labels stamped by the snapshot, so clicks
// stay correct across reflows, and accept tab=N to act on a background tab.
const AGENT_BROWSER_MAX_TABS = 8;
const agentBrowser = {
  tabs: [],           // [{ id, wcId, lastUrl, lastTitle, lastSnapshot, ready }]
  activeId: 0,        // id of the visible tab
  nextTabId: 1,
  wcId: 0,            // webContents id of the ACTIVE tab (legacy compat)
  lastUrl: '',
  lastTitle: '',
  lastSnapshot: null, // { at, url, title } — cached snapshot of the active tab
  ready: false,
};

function agentBrowserApi() { return (IS_DESKTOP && window.desktopAgent) || null; }
function agentBrowserWebview() { return document.getElementById('browserWebview'); }
function agentBrowserStatus(msg) { const el = document.getElementById('browserStatus'); if (el) el.textContent = msg || 'Idle'; }

function agentBrowserActiveTab() {
  return agentBrowser.tabs.find(t => t.id === agentBrowser.activeId) || null;
}
// Make sure a tab's guest is attached and expose its webContents id. A freshly
// created <webview> attaches asynchronously (getWebContentsId() returns 0 until
// did-attach), so poll briefly instead of failing on the first agent call.
async function agentBrowserEnsureAttached(tab) {
  if (!tab) throw new Error('No active browser tab.');
  if (!tab.wcId && tab.wv) {
    const grab = () => {
      try {
        const id = tab.wv.getWebContentsId();
        if (id) { tab.wcId = id; tab.ready = true; agentBrowser.ready = true; }
      } catch {}
    };
    grab();
    const deadline = Date.now() + 2000;
    while (!tab.wcId && Date.now() < deadline) {
      await new Promise(r => setTimeout(r, 50));
      grab();
    }
  }
  if (!tab.wcId) throw new Error('Browser page is still initializing — retry in a moment.');
  return tab.wcId;
}

// Resolve a tab for a tool call: explicit tab=N (1-based, as shown by
// browser_tabs), or the active tab when omitted.
function agentBrowserResolveTab(tabNum) {
  if (tabNum != null && Number(tabNum) > 0) {
    const idx = Math.round(Number(tabNum)) - 1;
    const t = agentBrowser.tabs[idx];
    if (!t) return { tab: null, error: `Tab ${Math.round(Number(tabNum))} does not exist. Call browser_tabs (action=list) to see open tabs.` };
    return { tab: t, error: '' };
  }
  const t = agentBrowserActiveTab();
  if (!t) return { tab: null, error: 'No active browser tab — open one with browser_navigate or browser_tabs (action=new).' };
  return { tab: t, error: '' };
}

// Normalize what the user or agent types into a URL: bare words become a search
// query on the configured engine, otherwise https:// is assumed.
function agentBrowserNormalizeInput(input) {
  const s = String(input || '').trim();
  if (!s) return '';
  if (/^(https?:\/\/|about:|data:)/i.test(s)) return s;
  // Dotted IPv4 hosts (e.g. 192.168.1.10:8080) and bracketed IPv6 are hosts,
  // not search queries.
  if (/^\d{1,3}(\.\d{1,3}){3}(:\d+)?(\/|$)/.test(s)) return 'https://' + s;
  if (/^\[[0-9a-fA-F:]+\](:\d+)?(\/|$)/.test(s)) return 'https://' + s;
  if (/^[\w-]+(\.[\w-]+)+(\/|$|:)/.test(s) && !s.includes(' ')) return 'https://' + s;
  const engine = String(state.apiSettings.browserSearchEngine || 'duckduckgo');
  const q = encodeURIComponent(s);
  if (engine === 'google') return 'https://www.google.com/search?q=' + q;
  if (engine === 'bing') return 'https://www.bing.com/search?q=' + q;
  return 'https://duckduckgo.com/?q=' + q;
}

function agentBrowserPaintNav() {
  const api = agentBrowserApi();
  const tab = agentBrowserActiveTab();
  const urlInput = document.getElementById('browserUrlInput');
  if (urlInput && document.activeElement !== urlInput && tab && tab.lastUrl) urlInput.value = tab.lastUrl;
  if (api && tab && tab.wcId) {
    api.browserHistory(tab.wcId, 'state').then(h => {
      const back = document.getElementById('browserBackBtn');
      const fwd = document.getElementById('browserFwdBtn');
      if (back) back.disabled = !h || !h.canGoBack;
      if (fwd) fwd.disabled = !h || !h.canGoForward;
    }).catch(() => {});
  }
}

// ---- Tab strip UI ----
function agentBrowserPaintTabs() {
  const strip = document.getElementById('browserTabStrip');
  if (!strip) return;
  strip.innerHTML = '';
  agentBrowser.tabs.forEach((t, i) => {
    const el = document.createElement('div');
    el.className = 'browser-tab' + (t.id === agentBrowser.activeId ? ' active' : '');
    el.title = `${t.lastTitle || t.lastUrl || 'New tab'}\nTab ${i + 1} — click to switch`;
    const label = document.createElement('span');
    label.className = 'browser-tab-label';
    label.textContent = (t.lastTitle || (t.lastUrl && t.lastUrl !== 'about:blank' ? t.lastUrl.replace(/^https?:\/\//, '').split('/')[0] : '') || `Tab ${i + 1}`);
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'browser-tab-close';
    close.textContent = '×';
    close.title = 'Close tab';
    close.onclick = (e) => { e.stopPropagation(); agentBrowserCloseTab(t.id); };
    el.appendChild(label);
    el.appendChild(close);
    el.onclick = () => agentBrowserActivateTab(t.id);
    strip.appendChild(el);
  });
  const plus = document.createElement('button');
  plus.type = 'button';
  plus.id = 'browserNewTabBtn';
  plus.className = 'browser-tab-new';
  plus.textContent = '+';
  plus.title = `New tab${agentBrowser.tabs.length >= AGENT_BROWSER_MAX_TABS ? ' (limit reached)' : ''}`;
  plus.disabled = agentBrowser.tabs.length >= AGENT_BROWSER_MAX_TABS;
  plus.onclick = () => agentBrowserCreateTab();
  strip.appendChild(plus);
}

// Wire a <webview> guest's lifecycle events into its tab record.
function agentBrowserWireWebview(wv, tab) {
  wv.addEventListener('did-attach', () => {
    try { tab.wcId = wv.getWebContentsId(); tab.ready = true; agentBrowser.ready = true; } catch {}
    if (tab.id === agentBrowser.activeId) { agentBrowser.wcId = tab.wcId; }
  });
  wv.addEventListener('did-start-loading', () => { if (tab.id === agentBrowser.activeId) agentBrowserStatus('Loading…'); agentBrowserPaintTabs(); });
  wv.addEventListener('did-stop-loading', () => {
    if (tab.id === agentBrowser.activeId) agentBrowserStatus('Ready');
    agentBrowserPaintTabs();
    agentBrowserPaintNav();
  });
  wv.addEventListener('did-navigate', (e) => {
    tab.lastUrl = e.url || '';
    tab.lastSnapshot = null; // stale after navigation
    if (tab.id === agentBrowser.activeId) {
      agentBrowser.lastUrl = tab.lastUrl;
      agentBrowser.lastSnapshot = null;
      const empty = document.getElementById('browserEmpty');
      if (empty && e.url && e.url !== 'about:blank') empty.style.display = 'none';
      agentBrowserPaintNav();
    }
    agentBrowserPaintTabs();
  });
  wv.addEventListener('did-navigate-in-page', (e) => {
    if (e.isMainFrame && e.url) {
      tab.lastUrl = e.url;
      tab.lastSnapshot = null;
      if (tab.id === agentBrowser.activeId) { agentBrowser.lastUrl = e.url; agentBrowser.lastSnapshot = null; }
      agentBrowserPaintTabs();
    }
  });
  wv.addEventListener('page-title-updated', (e) => {
    tab.lastTitle = e.title || '';
    if (tab.id === agentBrowser.activeId) agentBrowser.lastTitle = tab.lastTitle;
    agentBrowserPaintTabs();
  });
  wv.addEventListener('did-fail-load', (e) => {
    if (e.isMainFrame && e.errorCode !== -3 && tab.id === agentBrowser.activeId) agentBrowserStatus(`Failed: ${e.errorDescription || e.errorCode} (${e.validatedURL || ''})`);
  });
  // Popups open inside the same guest so the agent keeps control of them.
  wv.addEventListener('new-window', (e) => { try { wv.loadURL(e.url); } catch {} });
}

// Create a new tab (its own <webview> guest) and make it active. Returns the
// tab record, or null if the limit is hit or the UI is missing.
function agentBrowserCreateTab(url, opts = {}) {
  if (agentBrowser.tabs.length >= AGENT_BROWSER_MAX_TABS) {
    showToast(`Browser tab limit reached (${AGENT_BROWSER_MAX_TABS}). Close a tab first.`, 'error');
    return null;
  }
  const stage = document.getElementById('browserStage');
  const strip = document.getElementById('browserTabStrip');
  if (!stage || !strip) return null;
  const tab = { id: agentBrowser.nextTabId++, wcId: 0, lastUrl: 'about:blank', lastTitle: '', lastSnapshot: null, ready: false };
  const wv = document.createElement('webview');
  wv.src = 'about:blank';
  wv.className = 'browser-webview';
  wv.style.display = 'none';
  stage.appendChild(wv);
  tab.wv = wv;
  agentBrowserWireWebview(wv, tab);
  agentBrowser.tabs.push(tab);
  if (!opts.background) agentBrowserActivateTab(tab.id);
  if (url && url !== 'about:blank') agentBrowserNavigate(url, { tabId: tab.id }).catch(() => {});
  agentBrowserPaintTabs();
  return tab;
}

// Make a tab visible: show its webview, hide the others, update active state.
function agentBrowserActivateTab(tabId) {
  const tab = agentBrowser.tabs.find(t => t.id === tabId);
  if (!tab) return;
  agentBrowser.activeId = tabId;
  for (const t of agentBrowser.tabs) {
    if (t.wv) t.wv.style.display = (t.id === tabId) ? '' : 'none';
  }
  agentBrowser.wcId = tab.wcId || 0;
  agentBrowser.lastUrl = tab.lastUrl || '';
  agentBrowser.lastTitle = tab.lastTitle || '';
  agentBrowser.lastSnapshot = tab.lastSnapshot || null;
  const empty = document.getElementById('browserEmpty');
  if (empty) empty.style.display = (tab.lastUrl && tab.lastUrl !== 'about:blank') ? 'none' : '';
  agentBrowserStatus('Ready');
  agentBrowserPaintTabs();
  agentBrowserPaintNav();
}

// Close a tab (destroying its guest). If it was active, focus a neighbour. If
// it was the last tab, keep one empty tab so the browser never disappears.
function agentBrowserCloseTab(tabId) {
  const idx = agentBrowser.tabs.findIndex(t => t.id === tabId);
  if (idx === -1) return;
  const tab = agentBrowser.tabs[idx];
  try { if (tab.wv) tab.wv.remove(); } catch {}
  agentBrowser.tabs.splice(idx, 1);
  if (agentBrowser.activeId === tabId) {
    if (agentBrowser.tabs.length) {
      agentBrowserActivateTab(agentBrowser.tabs[Math.max(0, idx - 1)].id);
    } else {
      agentBrowserCreateTab(); // keep one empty tab
    }
  }
  agentBrowserPaintTabs();
}
function initAgentBrowser() {
  const api = agentBrowserApi();
  const tabBtn = document.querySelector('.tab[data-tab="browser"]');
  if (!api || !api.browserNavigate) {
    // Static HTML/browser version: webview is an unknown element and the IPC
    // bridge is missing — hide the tab.
    if (tabBtn) tabBtn.style.display = 'none';
    return;
  }
  const wv = agentBrowserWebview();
  if (!wv) return;

  // The static-HTML webview in index.html becomes the FIRST tab.
  wv.className = 'browser-webview';
  const first = { id: agentBrowser.nextTabId++, wcId: 0, lastUrl: 'about:blank', lastTitle: '', lastSnapshot: null, ready: false };
  first.wv = wv;
  agentBrowserWireWebview(wv, first);
  agentBrowser.tabs.push(first);
  agentBrowser.activeId = first.id;
  agentBrowserPaintTabs();

  const go = () => {
    const url = agentBrowserNormalizeInput(document.getElementById('browserUrlInput').value);
    if (url) agentBrowserNavigate(url).catch(() => {});
  };
  document.getElementById('browserGoBtn').onclick = go;
  document.getElementById('browserUrlInput').addEventListener('keydown', (e) => { if (e.key === 'Enter') go(); });
  document.getElementById('browserBackBtn').onclick = () => api.browserHistory(agentBrowser.wcId, 'back').catch(() => {});
  document.getElementById('browserFwdBtn').onclick = () => api.browserHistory(agentBrowser.wcId, 'forward').catch(() => {});
  document.getElementById('browserReloadBtn').onclick = () => api.browserHistory(agentBrowser.wcId, 'reload').catch(() => {});
  // Open a web app from disk (HTML file or folder) in this browser tab.
  document.getElementById('browserOpenWebappBtn').onclick = async () => {
    const api = agentBrowserApi();
    if (!api || !api.webappPick) return;
    try {
      const picked = await api.webappPick();
      if (!picked || !picked.ok || !picked.path) return;
      let r;
      if (picked.kind === 'file') {
        const dir = picked.path.replace(/[\\/][^\\/]*$/, '') || picked.path;
        r = await api.webappStart(dir, '/');
        if (r.ok) {
          const name = picked.path.split(/[\\/]/).pop();
          r.url = r.url.replace(/\/?$/, '/') + encodeURIComponent(name);
        }
      } else {
        r = await api.webappStart(picked.path, '/');
      }
      if (!r.ok) throw new Error(r.error || 'Could not serve that path.');
      if (state.activeTab !== 'browser') switchTab('browser');
      await agentBrowserNavigate(r.url);
      agentBrowserStatus('Web app: ' + picked.path);
    } catch (e) { showToast('Open web app failed: ' + e.message, 'error'); }
  };
  // Reload the current web app: re-serve the workspace subtree so edits show up.
  document.getElementById('browserReloadWebappBtn').onclick = async () => {
    try {
      const tab = agentBrowserActiveTab();
      const url = (tab && tab.lastUrl) || agentBrowser.lastUrl || '';
      const api = agentBrowserApi();
      if (/127\.0\.0\.1:\d+/.test(url) && api && api.webappStart && agentFS.usingReal && api.webappReload) {
        const r = await api.webappReload();
        if (!r.ok) throw new Error(r.error || 'reload failed');
      }
      if (tab) await agentBrowserNavigate(url || 'about:blank', { tabId: tab.id });
      else await agentBrowserNavigate(url || 'about:blank');
      showToast('Web app reloaded', 'success');
    } catch (e) { showToast('Reload failed: ' + e.message, 'error'); }
  };
  document.getElementById('browserClearBtn').onclick = async () => {
    if (!confirm('Clear this browser\'s cookies, cache and site storage?\nCache is shared; site data is cleared for the current site only.')) return;
    try { await api.browserSession(agentBrowser.wcId, 'clearData'); showToast('Browser data cleared', 'success'); } catch (e) { showToast('Clear failed: ' + e.message, 'error'); }
  };
  // Manual /map and /text buttons: paste what the agent sees into the Big Chat
  // input so the user can reason with the same representation.
  document.getElementById('browserSnapshotBtn').onclick = async () => {
    try {
      const snap = await api.browserSnapshot(agentBrowser.wcId);
      if (!snap.ok) throw new Error(snap.error || 'snapshot failed');
      const text = `Page: ${snap.title}\nURL: ${snap.url}\n\n${snap.elements}`;
      const inp = document.getElementById('bigChatInput');
      if (inp) { inp.value = (inp.value ? inp.value + '\n\n' : '') + '[Web page element map]\n' + text; inp.dispatchEvent(new Event('input')); }
      showToast('Element map copied to Big Chat input', 'success');
    } catch (e) { showToast('Snapshot failed: ' + e.message, 'error'); }
  };
  document.getElementById('browserTextBtn').onclick = async () => {
    try {
      const r = await api.browserText(agentBrowser.wcId);
      if (!r.ok) throw new Error(r.error || 'text extraction failed');
      const inp = document.getElementById('bigChatInput');
      if (inp) { inp.value = (inp.value ? inp.value + '\n\n' : '') + '[Web page text]\n' + r.text.slice(0, 4000); inp.dispatchEvent(new Event('input')); }
      showToast('Page text copied to Big Chat input', 'success');
    } catch (e) { showToast('Text extraction failed: ' + e.message, 'error'); }
  };
}

// Navigate a tab (default: the active one). Waits for load so callers (the
// agent tools and the manual Go button) get the final URL back.
async function agentBrowserNavigate(url, opts = {}) {
  const api = agentBrowserApi();
  if (!api) throw new Error('Browser is not available (desktop app only).');
  let tab = opts.tabId ? agentBrowser.tabs.find(t => t.id === opts.tabId) : agentBrowserActiveTab();
  if (!tab) {
    // No tab yet (agent tools before the browser tab was ever opened): create one.
    tab = agentBrowserCreateTab();
    if (!tab) throw new Error('Browser page is not initialized.');
  }
  if (tab.id === agentBrowser.activeId) { agentBrowser.wcId = tab.wcId; agentBrowserStatus('Loading ' + url + '…'); }
  await agentBrowserEnsureAttached(tab);
  const r = await api.browserNavigate(tab.wcId, url);
  if (!r.ok) {
    if (tab.id === agentBrowser.activeId) agentBrowserStatus('Error: ' + (r.error || 'navigation failed'));
    throw new Error(r.error || 'navigation failed');
  }
  tab.lastUrl = r.url || url;
  tab.lastSnapshot = null;
  if (tab.id === agentBrowser.activeId) {
    agentBrowser.lastUrl = tab.lastUrl;
    agentBrowser.lastSnapshot = null;
    agentBrowserStatus('Ready');
    agentBrowserPaintNav();
  }
  agentBrowserPaintTabs();
  return r;
}

// Shared guard + result formatting for the agent's browser_* tools. Resolves
// the target tab from args.tab (1-based, per browser_tabs) and passes it to
// fn(api, tab).
async function agentBrowserCall(args, fn) {
  const api = agentBrowserApi();
  if (!api || !api.browserNavigate) return { ok: false, content: 'The browser tools are only available in the installed desktop app.' };
  if (state.apiSettings.agentBrowserEnabled === false) return { ok: false, content: 'Browser tools are disabled in Settings → Agent Tools.' };
  if (!agentBrowser.tabs.length) {
    // First agent use: make sure a guest exists even if the tab was never opened.
    const wv = agentBrowserWebview();
    if (wv) {
      const first = { id: agentBrowser.nextTabId++, wcId: 0, lastUrl: 'about:blank', lastTitle: '', lastSnapshot: null, ready: false };
      first.wv = wv;
      wv.className = 'browser-webview';
      agentBrowserWireWebview(wv, first);
      agentBrowser.tabs.push(first);
      agentBrowser.activeId = first.id;
      agentBrowserPaintTabs();
    } else return { ok: false, content: 'Browser page is not initialized.' };
  }
  const { tab, error } = agentBrowserResolveTab(args && args.tab);
  if (!tab) return { ok: false, content: error };
  try { await agentBrowserEnsureAttached(tab); }
  catch (e) { return { ok: false, content: e.message }; }
  try { return await fn(api, tab); }
  catch (e) { return { ok: false, content: `Browser tool failed: ${e.message}` }; }
}

// Wait until the main frame settles after an action, so the agent's next read
// sees the post-action DOM. Bounded; never hangs the tool loop.
function agentBrowserSettle(ms) {
  return new Promise((resolve) => setTimeout(resolve, Math.max(300, Math.min(5000, Number(ms) || 800))));
}

async function agentBrowserToolSnapshot(api, tab) {
  const r = await api.browserSnapshot(tab.wcId);
  if (!r.ok) return { ok: false, content: 'Snapshot failed: ' + (r.error || 'unknown') };
  tab.lastSnapshot = { at: Date.now(), url: r.url, title: r.title };
  if (tab.id === agentBrowser.activeId) agentBrowser.lastSnapshot = tab.lastSnapshot;
  const hdr = `Page: ${r.title || '(untitled)'}\nURL: ${r.url}\nInteractive elements (use refs in browser_click / browser_type):\n`;
  return { ok: true, content: r.count ? hdr + r.elements : hdr + '(no interactive elements found — try browser_scroll or browser_extract_text)' };
}

// List tabs for the browser_tabs tool; returns the numbered list the agent
// passes back as tab=N.
function agentBrowserTabsSummary() {
  const active = agentBrowserActiveTab();
  return agentBrowser.tabs.map((t, i) => {
    const url = t.lastUrl || 'about:blank';
    const title = t.lastTitle || (url !== 'about:blank' ? '(untitled)' : 'New tab');
    const snap = t.lastSnapshot ? ` [snapshot cached]` : '';
    return `${i + 1}. ${title} — ${url}${t.id === (active && active.id) ? '  ← active' : ''}${snap}`;
  }).join('\n');
}

function initAgentBrowserTabVisibility() {
  // Called on startup: if not desktop, the tab button is hidden by initAgentBrowser.
}

// ===================== DESKTOP TAB (hosted native apps) =====================
// The main process re-parents launched exes' windows into this window and
// positions them over #desktopGuestAnchor. The renderer only reports rects and
// active state; it never touches native window handles.
const desktopApps = []; // mirrors main's app list [{ id, exe, pid, title, cls, alive }]
let desktopActiveId = null;
let desktopSyncTimer = null;
let desktopKnownIds = null; // ids seen in the last sync — detects newly promoted/adopted apps

function desktopIsSupported() { return typeof window.desktopAgent?.desktopLaunch === 'function'; }

function desktopGuestRect() {
  const anchor = document.getElementById('desktopGuestAnchor');
  if (!anchor) return null;
  const r = anchor.getBoundingClientRect();
  if (r.width < 4 || r.height < 4) return null;
  return { x: r.left, y: r.top, w: r.width, h: r.height };
}

// Tell main which guests should be visible right now (Desktop tab active and
// their app tab selected) and where exactly the stage div sits.
async function syncDesktopTabVisibility(desktopTabActive) {
  if (!desktopIsSupported()) return;
  // Tell main whether the Desktop tab is in front, so a screenshot that
  // temporarily shows a parked app can restore the parked state afterwards.
  if (window.desktopAgent?.desktopTabActive) { try { window.desktopAgent.desktopTabActive(desktopTabActive); } catch {} }
  try {
    const res = await window.desktopAgent.desktopList();
    const apps = (res && res.ok && Array.isArray(res.apps)) ? res.apps : [];
    desktopApps.length = 0;
    desktopApps.push(...apps);
    // A brand-new app id (main just promoted an unowned game window — e.g. the
    // Godot editor's F5 run — or adopted a successor) takes the stage: main
    // shows it, so the renderer must not leave the OLD app active while the
    // new one gets parked hidden by the visibility sync below.
    if (!desktopKnownIds) desktopKnownIds = new Set(apps.map(a => a.id));
    const fresh = apps.filter(a => !desktopKnownIds.has(a.id));
    for (const a of fresh) desktopKnownIds.add(a.id);
    if (fresh.length) desktopActiveId = fresh[fresh.length - 1].id;
    if (desktopActiveId && !apps.some(a => a.id === desktopActiveId)) desktopActiveId = null;
    if (!desktopActiveId && apps.length) desktopActiveId = apps[apps.length - 1].id;
    for (const a of apps) {
      const wantVisible = !!desktopTabActive && a.id === desktopActiveId;
      await window.desktopAgent.desktopVisible(a.id, wantVisible);
      if (wantVisible) {
        const rect = desktopGuestRect();
        if (rect) await window.desktopAgent.desktopResize(a.id, rect);
      }
    }
    desktopRenderAppStrip();
    renderDesktopEmptyState();
  } catch (e) { console.warn('desktop sync failed:', e); }
}

function desktopRenderAppStrip() {
  const strip = document.getElementById('desktopAppStrip');
  if (!strip) return;
  strip.innerHTML = '';
  for (const a of desktopApps) {
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'desktop-app-tab' + (a.id === desktopActiveId ? ' active' : '');
    el.title = `${a.exe} (pid ${a.pid})`;
    const label = document.createElement('span');
    label.className = 'desktop-app-label';
    label.textContent = a.title || a.exe;
    const close = document.createElement('span');
    close.className = 'desktop-app-close';
    close.textContent = '✕';
    close.title = 'Close this app';
    close.onclick = async (ev) => {
      ev.stopPropagation();
      await window.desktopAgent.desktopKill(a.id);
      await syncDesktopTabVisibility(state.activeTab === 'desktop');
    };
    el.appendChild(label);
    el.appendChild(close);
    el.onclick = async () => {
      desktopActiveId = a.id;
      desktopRenderAppStrip();
      await window.desktopAgent.desktopFocus(a.id);
      const rect = desktopGuestRect();
      if (rect) await window.desktopAgent.desktopResize(a.id, rect);
      await syncDesktopTabVisibility(state.activeTab === 'desktop');
    };
    strip.appendChild(el);
  }
}

async function desktopLaunchPickedExe() {
  if (!desktopIsSupported()) {
    console.warn('desktop launch: desktopAgent missing — app was started before this session loaded preload.js? Restart the app.');
    if (typeof notify === 'function') notify({ body: 'Open App needs an app restart to work (native bridge not loaded).' });
    return;
  }
  try {
    const pick = await window.desktopAgent.desktopPickExe();
    if (!pick || !pick.ok) {
      // The native file dialog failed — surface it instead of dying silently
      // (a hidden/behind-window dialog previously looked like "button does nothing").
      const msg = (pick && pick.error) || 'file picker failed';
      console.warn('desktop pick failed:', msg);
      if (typeof notify === 'function') notify({ body: 'Could not open the file picker: ' + msg });
      return;
    }
    if (!pick.path) return; // user canceled — not an error
    const rect = desktopGuestRect();
    const res = await window.desktopAgent.desktopLaunch({ exe: pick.path, rect, waitMs: 30000 });
    if (!res || !res.ok) {
      const msg = (res && res.error) || 'launch failed';
      console.warn('desktop launch failed:', msg);
      if (typeof notify === 'function') notify({ body: 'Could not host app: ' + msg });
      return;
    }
    desktopActiveId = res.app.id;
    await syncDesktopTabVisibility(true);
  } catch (e) {
    console.warn('desktop launch error:', e);
    if (typeof notify === 'function') notify({ body: 'Open App failed: ' + ((e && e.message) || e) });
  }
}

// ---- Godot card (Desktop tab) ----------------------------------------------
// The visible half of the integration. Every button here calls the SAME agent
// tool the AI calls, so the two can never drift apart in behaviour — a fix to
// godot_run's capture path fixes this card too, and vice versa.
let desktopGodotBusy = false;

function desktopGodotStatus(msg) {
  const el = document.getElementById('desktopGodotStatus');
  if (el) el.textContent = msg || '';
}

async function desktopGodotRefresh(opts = {}) {
  const engineEl = document.getElementById('desktopGodotEngine');
  const projEl = document.getElementById('desktopGodotProject');
  if (!engineEl) return null;
  if (!IS_DESKTOP) { engineEl.textContent = 'desktop app only'; return null; }
  engineEl.textContent = 'checking…';
  const local = await localGodotVersion({ fresh: !!opts.fresh });
  const where = godotSourceLabel(local.source);
  engineEl.textContent = local.exe
    ? `${local.version || 'unknown version'}${where ? ` · ${where}` : ''}`
    : (godotProvisionEnabled() ? 'no engine yet — installed on first use' : 'no engine found');
  engineEl.title = local.exe || '';
  let proj = null;
  try { proj = await godotProjectInfo(); } catch {}
  if (projEl) {
    // The parsed keys live under proj.file (parseProjectGodot owns that shape);
    // reading proj.mainScene directly silently reports "no main scene set" for
    // every project, which is the one line here worth getting right.
    const f = (proj && proj.file) || {};
    const sceneState = proj && (proj.mainSceneByUid ? ' (by uid)' : proj.mainSceneFound ? '' : ' (MISSING)');
    projEl.textContent = proj
      ? `${f.name || 'unnamed project'} · ${f.mainScene ? 'main scene ' + f.mainScene + sceneState : 'no main scene set'}`
      : 'no project.godot in this workspace';
    projEl.title = proj ? proj.dir : '';
  }
  return { local, proj };
}

// Where the card's own captures land, and how many it keeps. Each one is a
// ~800 KB PNG, so without pruning every click would leave another file in the
// workspace for good.
const GODOT_CAPTURE_DIR = '/.freebuff/godot_desktop';
const GODOT_CAPTURE_KEEP = 5;

async function pruneGodotCardCaptures() {
  try {
    const entries = await agentListDir(GODOT_CAPTURE_DIR);
    const shots = entries
      .filter((e) => e.kind === 'file' && /\.png$/i.test(e.name))
      .map((e) => e.name)
      .sort(); // the names carry a millisecond timestamp
    for (const old of shots.slice(0, Math.max(0, shots.length - GODOT_CAPTURE_KEEP))) {
      try { await agentDeleteFile(GODOT_CAPTURE_DIR + '/' + old, { recursive: false }); } catch {}
    }
  } catch {}
}

// One card action at a time, with the button states showing it: two Godot runs
// at once would fight over the same project, and a double-click must not start
// a second download.
async function desktopGodotAction(btn, label, fn) {
  if (desktopGodotBusy) return;
  desktopGodotBusy = true;
  const buttons = Array.from(document.querySelectorAll('.godot-card-actions button'));
  buttons.forEach((b) => { b.disabled = true; });
  desktopGodotStatus(label + '…');
  try {
    await fn();
  } catch (e) {
    desktopGodotStatus(label + ' failed: ' + ((e && e.message) || e));
  } finally {
    desktopGodotBusy = false;
    buttons.forEach((b) => { b.disabled = false; });
  }
}

function initGodotCard() {
  const runBtn = document.getElementById('desktopGodotRunBtn');
  const editorBtn = document.getElementById('desktopGodotEditorBtn');
  const checkBtn = document.getElementById('desktopGodotCheckBtn');
  const engineBtn = document.getElementById('desktopGodotEngineBtn');
  const shot = document.getElementById('desktopGodotShot');
  if (!runBtn) return;
  runBtn.onclick = () => desktopGodotAction(runBtn, 'Running the game', async () => {
    const dest = GODOT_CAPTURE_DIR + '/shot-' + Date.now() + '.png';
    const r = await executeAgentTool('godot_run', { screenshotPaths: [dest], frames: 30, timeoutMs: 300000 });
    desktopGodotStatus(r.content || (r.ok ? 'done' : 'failed'));
    if (shot && r.image) { shot.src = r.image; shot.hidden = false; }
    // The image above is already in memory, so the file on disk is only a
    // record — keep the newest few and drop the rest.
    await pruneGodotCardCaptures();
  });
  if (editorBtn) editorBtn.onclick = () => desktopGodotAction(editorBtn, 'Opening the editor', async () => {
    const r = await executeAgentTool('godot_editor', { action: 'open' });
    desktopGodotStatus(r.content || 'done');
  });
  if (checkBtn) checkBtn.onclick = () => desktopGodotAction(checkBtn, 'Loading the project', async () => {
    const r = await executeAgentTool('godot_check', { timeoutMs: 600000 });
    desktopGodotStatus(r.content || 'done');
  });
  if (engineBtn) engineBtn.onclick = () => desktopGodotAction(engineBtn, 'Installing the engine', async () => {
    const r = await ensureGodotEngine({ force: true });
    desktopGodotStatus(r.ok
      ? (r.installed ? `Installed Godot ${r.version} into the app's engine folder.` : `An engine is already available: ${r.version} (${godotSourceLabel(r.source)}).`)
      : 'Could not install an engine: ' + r.error);
    await desktopGodotRefresh({ fresh: true });
  });
}

function initDesktopTab() {
  if (!desktopIsSupported()) {
    // The Godot card's buttons all drive native processes; with no desktop host
    // they would be dead controls, so the card hides itself.
    const card = document.getElementById('desktopGodotCard');
    if (card) card.hidden = true;
    return;
  }
  const launchBtn = document.getElementById('desktopLaunchBtn');
  const refreshBtn = document.getElementById('desktopRefreshBtn');
  if (launchBtn) launchBtn.onclick = desktopLaunchPickedExe;
  if (refreshBtn) refreshBtn.onclick = () => syncDesktopTabVisibility(state.activeTab === 'desktop');
  initGodotCard();

  // Keep the guest window glued to the stage div on every layout change.
  const stage = document.getElementById('desktopStage');
  if (stage && typeof ResizeObserver === 'function') {
    let pending = false;
    const ro = new ResizeObserver(() => {
      if (pending) return;
      pending = true;
      requestAnimationFrame(async () => {
        pending = false;
        if (state.activeTab !== 'desktop' || !desktopActiveId) return;
        const rect = desktopGuestRect();
        if (rect) await window.desktopAgent.desktopResize(desktopActiveId, rect);
      });
    });
    ro.observe(stage);
  }

  // Hide hosted apps while another tab is in front (so a stray click on a
  // hidden tab's area can't land on a parked guest window).
  // Also reap dead apps periodically.
  desktopSyncTimer = setInterval(async () => {
    const before = desktopApps.map(a => a.id + ':' + a.alive).join(',');
    await syncDesktopTabVisibility(state.activeTab === 'desktop');
    const after = desktopApps.map(a => a.id + ':' + a.alive).join(',');
    if (before !== after && typeof renderDesktopEmptyState === 'function') renderDesktopEmptyState();
  }, 3000);

  // Initial visibility in case the tab was restored as active.
  if (state.activeTab === 'desktop') syncDesktopTabVisibility(true);
}

function renderDesktopEmptyState() {
  const empty = document.getElementById('desktopEmpty');
  if (empty) empty.style.display = desktopApps.length ? 'none' : 'flex';
}

document.addEventListener('DOMContentLoaded', () => { setTimeout(initDesktopTab, 0); });


